'use client';

import { useState, useEffect } from 'react';
import AdminLayout from '@/components/AdminLayout';
import ConfirmationModal from '@/components/ConfirmationModal';
import AlertModal from '@/components/AlertModal';
import { FiCheck, FiX, FiEye, FiClock, FiSearch, FiFilter, FiDownload, FiRefreshCw } from 'react-icons/fi';

interface IDeposit {
    _id: string;
    userId: {
        firstName: string;
        lastName: string;
        email: string;
    };
    amount: number;
    cryptoSymbol: string;
    network: string;
    transactionId: string;
    status: 'pending' | 'completed' | 'rejected';
    createdAt: string;
    proofImage?: string;
}

export default function AdminDepositsPage() {
    const [deposits, setDeposits] = useState<IDeposit[]>([]);
    const [loading, setLoading] = useState(true);
    const [filterStatus, setFilterStatus] = useState('all');
    const [searchQuery, setSearchQuery] = useState('');
    const [viewProof, setViewProof] = useState<string | null>(null);
    const [actionLoading, setActionLoading] = useState<string | null>(null);

    // Modal States
    const [confirmModal, setConfirmModal] = useState<{ isOpen: boolean; id: string; status: 'completed' | 'rejected' }>({
        isOpen: false,
        id: '',
        status: 'completed'
    });

    const [alertState, setAlertState] = useState<{
        isOpen: boolean;
        title: string;
        message: string;
        type: 'success' | 'error' | 'info';
    }>({
        isOpen: false,
        title: '',
        message: '',
        type: 'info'
    });

    useEffect(() => {
        fetchDeposits();
    }, []);

    const fetchDeposits = async () => {
        setLoading(true);
        try {
            const res = await fetch('/api/admin/deposits', {
                headers: { 'x-is-admin': 'true' }
            });
            const data = await res.json();
            if (data.success) {
                setDeposits(data.deposits);
            }
        } catch (error) {
            console.error('Error fetching deposits:', error);
        } finally {
            setLoading(false);
        }
    };

    const initiateUpdate = (id: string, newStatus: 'completed' | 'rejected') => {
        setConfirmModal({
            isOpen: true,
            id,
            status: newStatus
        });
    };

    const handleConfirmUpdate = async () => {
        const { id, status } = confirmModal;
        setActionLoading(id);

        try {
            const res = await fetch(`/api/admin/deposits/${id}`, {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                    'x-is-admin': 'true'
                },
                body: JSON.stringify({ status })
            });
            const data = await res.json();

            if (data.success) {
                setDeposits(deposits.map(d => d._id === id ? { ...d, status } : d));
                setAlertState({
                    isOpen: true,
                    title: 'Status Updated',
                    message: `Deposit marked as ${status} successfully.`,
                    type: 'success'
                });
            } else {
                setAlertState({
                    isOpen: true,
                    title: 'Update Failed',
                    message: data.error || 'Failed to update status',
                    type: 'error'
                });
            }
        } catch (error) {
            setAlertState({
                isOpen: true,
                title: 'Error',
                message: 'An unexpected error occurred.',
                type: 'error'
            });
        } finally {
            setActionLoading(null);
        }
    };

    const filteredDeposits = deposits.filter(deposit => {
        const matchesStatus = filterStatus === 'all' || deposit.status === filterStatus;
        const matchesSearch =
            deposit.transactionId.toLowerCase().includes(searchQuery.toLowerCase()) ||
            deposit.userId.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
            deposit.amount.toString().includes(searchQuery);
        return matchesStatus && matchesSearch;
    });

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'completed': return 'bg-green-500/20 text-green-400 border-green-500/50';
            case 'rejected': return 'bg-red-500/20 text-red-400 border-red-500/50';
            default: return 'bg-yellow-500/20 text-yellow-400 border-yellow-500/50';
        }
    };

    return (
        <AdminLayout>
            <section className="py-8 px-6 lg:px-8">
                <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
                    <div>
                        <h1 className="text-3xl font-bold font-serif text-white mb-2">Deposit Requests</h1>
                        <p className="text-gray-400">Manage and approve incoming user deposits.</p>
                    </div>
                    <button onClick={fetchDeposits} className="btn-secondary self-start md:self-auto flex items-center space-x-2">
                        <FiRefreshCw className={loading ? 'animate-spin' : ''} />
                        <span>Refresh</span>
                    </button>
                </div>

                {/* Filters */}
                <div className="card-premium mb-8">
                    <div className="flex flex-col md:flex-row gap-4">
                        <div className="flex-1 relative">
                            <FiSearch className="absolute left-4 top-3.5 text-gray-500" />
                            <input
                                type="text"
                                placeholder="Search by TxID, Email, or Amount..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                className="w-full bg-primary-900 border border-primary-700 rounded-lg pl-10 pr-4 py-3 text-white focus:outline-none focus:border-accent-gold transition-colors"
                            />
                        </div>
                        <div className="flex space-x-2 overflow-x-auto pb-2 md:pb-0">
                            {['all', 'pending', 'completed', 'rejected'].map(status => (
                                <button
                                    key={status}
                                    onClick={() => setFilterStatus(status)}
                                    className={`px-4 py-3 rounded-lg capitalize whitespace-nowrap transition-colors ${filterStatus === status
                                        ? 'bg-accent-gold text-primary-950 font-bold'
                                        : 'bg-primary-900 border border-primary-700 text-gray-400 hover:text-white'
                                        }`}
                                >
                                    {status}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>

                {/* Table */}
                <div className="card-premium overflow-hidden p-0">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="bg-primary-900/50 text-gray-400 text-xs uppercase font-semibold">
                                <tr>
                                    <th className="px-6 py-4">User</th>
                                    <th className="px-6 py-4">Amount / Crypto</th>
                                    <th className="px-6 py-4">Transaction ID</th>
                                    <th className="px-6 py-4">Status</th>
                                    <th className="px-6 py-4">Date</th>
                                    <th className="px-6 py-4 text-right">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-primary-800">
                                {loading ? (
                                    <tr>
                                        <td colSpan={6} className="text-center py-12 text-gray-500">Loading deposits...</td>
                                    </tr>
                                ) : filteredDeposits.length === 0 ? (
                                    <tr>
                                        <td colSpan={6} className="text-center py-12 text-gray-500">No deposits found.</td>
                                    </tr>
                                ) : (
                                    filteredDeposits.map((deposit) => (
                                        <tr key={deposit._id} className="hover:bg-primary-800/30 transition-colors">
                                            <td className="px-6 py-4">
                                                <div>
                                                    <p className="text-white font-medium">{deposit.userId?.firstName} {deposit.userId?.lastName}</p>
                                                    <p className="text-xs text-gray-400">{deposit.userId?.email}</p>
                                                </div>
                                            </td>
                                            <td className="px-6 py-4">
                                                <div>
                                                    <p className="text-white font-bold">${deposit.amount.toLocaleString()}</p>
                                                    <p className="text-xs text-accent-gold">{deposit.cryptoSymbol} ({deposit.network})</p>
                                                </div>
                                            </td>
                                            <td className="px-6 py-4">
                                                <div className="max-w-[150px] truncate text-gray-400 font-mono text-xs" title={deposit.transactionId}>
                                                    {deposit.transactionId}
                                                </div>
                                                {deposit.proofImage && (
                                                    <button
                                                        onClick={() => setViewProof(deposit.proofImage!)}
                                                        className="text-xs text-accent-gold hover:underline mt-1 flex items-center gap-1"
                                                    >
                                                        <FiEye className="w-3 h-3" /> View Proof
                                                    </button>
                                                )}
                                            </td>
                                            <td className="px-6 py-4">
                                                <span className={`px-2 py-1 rounded-full text-xs font-medium border ${getStatusColor(deposit.status)} capitalize`}>
                                                    {deposit.status}
                                                </span>
                                            </td>
                                            <td className="px-6 py-4 text-sm text-gray-400">
                                                {new Date(deposit.createdAt).toLocaleDateString()}
                                                <br />
                                                <span className="text-xs text-gray-500">{new Date(deposit.createdAt).toLocaleTimeString()}</span>
                                            </td>
                                            <td className="px-6 py-4">
                                                <div className="flex justify-end space-x-2">
                                                    {deposit.status === 'pending' && (
                                                        <>
                                                            <button
                                                                onClick={() => initiateUpdate(deposit._id, 'completed')}
                                                                disabled={!!actionLoading}
                                                                className="p-2 bg-green-500/20 text-green-400 rounded-lg hover:bg-green-500 hover:text-white transition-colors border border-green-500/30"
                                                                title="Approve"
                                                            >
                                                                <FiCheck className="w-4 h-4" />
                                                            </button>
                                                            <button
                                                                onClick={() => initiateUpdate(deposit._id, 'rejected')}
                                                                disabled={!!actionLoading}
                                                                className="p-2 bg-red-500/20 text-red-400 rounded-lg hover:bg-red-500 hover:text-white transition-colors border border-red-500/30"
                                                                title="Reject"
                                                            >
                                                                <FiX className="w-4 h-4" />
                                                            </button>
                                                        </>
                                                    )}
                                                </div>
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>

                {/* Proof Image Modal */}
                {viewProof && (
                    <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-fade-in" onClick={() => setViewProof(null)}>
                        <div className="max-w-3xl max-h-[90vh] overflow-auto relative rounded-xl shadow-2xl animate-scale-in" onClick={e => e.stopPropagation()}>
                            <button
                                onClick={() => setViewProof(null)}
                                className="absolute top-2 right-2 p-2 bg-black/50 text-white rounded-full hover:bg-red-500 transition-colors"
                            >
                                <FiX className="w-6 h-6" />
                            </button>
                            <img src={viewProof} alt="Payment Proof" className="w-full h-auto rounded-xl" />
                        </div>
                    </div>
                )}

                {/* Confirmation Modal */}
                <ConfirmationModal
                    isOpen={confirmModal.isOpen}
                    onClose={() => setConfirmModal(prev => ({ ...prev, isOpen: false }))}
                    onConfirm={handleConfirmUpdate}
                    title={confirmModal.status === 'completed' ? 'Approve Deposit' : 'Reject Deposit'}
                    message={confirmModal.status === 'completed'
                        ? 'Are you sure you want to approve this deposit? The funds will be credited to the user\'s wallet.'
                        : 'Are you sure you want to reject this deposit? This action cannot be undone.'}
                    confirmLabel={confirmModal.status === 'completed' ? 'Approve' : 'Reject'}
                    isDestructive={confirmModal.status === 'rejected'}
                />

                <AlertModal
                    isOpen={alertState.isOpen}
                    onClose={() => setAlertState(prev => ({ ...prev, isOpen: false }))}
                    title={alertState.title}
                    message={alertState.message}
                    type={alertState.type}
                />

            </section>
        </AdminLayout>
    );
}

'use client';

import { useState, useEffect } from 'react';
import AdminLayout from '@/components/AdminLayout';
import { FiSearch, FiTrash2, FiEdit2, FiX, FiCheck, FiAlertCircle, FiInfo } from 'react-icons/fi';
import AlertModal from '@/components/AlertModal';
import Link from 'next/link';

interface Investment {
    _id: string;
    investmentId: string;
    userId: {
        _id: string;
        firstName: string;
        lastName: string;
        email: string;
    };
    planId: {
        name: string;
        roiPercentage: number;
    };
    amount: number;
    expectedReturn: number;
    status: 'active' | 'completed' | 'cancelled';
    startDate: string;
    endDate: string;
}

export default function AdminInvestmentsPage() {
    const [investments, setInvestments] = useState<Investment[]>([]);
    const [loading, setLoading] = useState(true);
    const [filter, setFilter] = useState('active');
    const [search, setSearch] = useState('');

    // Modal States
    const [editModalOpen, setEditModalOpen] = useState(false);
    const [selectedInvestment, setSelectedInvestment] = useState<Investment | null>(null);
    const [newCapital, setNewCapital] = useState('');
    const [actionLoading, setActionLoading] = useState(false);

    // Alert
    const [alertState, setAlertState] = useState<{
        isOpen: boolean;
        title: string;
        message: string;
        type: 'success' | 'error' | 'info';
    }>({ isOpen: false, title: '', message: '', type: 'info' });

    const fetchInvestments = async () => {
        setLoading(true);
        try {
            const queryParams = new URLSearchParams({
                status: filter,
                search: search
            });
            const res = await fetch(`/api/admin/investments?${queryParams}`);
            const data = await res.json();
            if (data.success) {
                setInvestments(data.investments);
            }
        } catch (error) {
            console.error('Error fetching investments:', error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        const debounce = setTimeout(() => {
            fetchInvestments();
        }, 300);
        return () => clearTimeout(debounce);
    }, [filter, search]);

    const handleCancel = async (id: string) => {
        if (!confirm('Are you sure you want to cancel this investment? This will refund the user and delete the record permanently.')) return;

        try {
            const res = await fetch(`/api/admin/investments?id=${id}`, {
                method: 'DELETE',
            });
            const data = await res.json();

            if (data.success) {
                setAlertState({ isOpen: true, title: 'Success', message: 'Investment cancelled and refunded.', type: 'success' });
                fetchInvestments();
            } else {
                setAlertState({ isOpen: true, title: 'Error', message: data.error, type: 'error' });
            }
        } catch (error) {
            setAlertState({ isOpen: true, title: 'Error', message: 'Failed to cancel investment', type: 'error' });
        }
    };

    const handleEdit = (inv: Investment) => {
        setSelectedInvestment(inv);
        setNewCapital(inv.amount.toString());
        setEditModalOpen(true);
    };

    const saveCapital = async () => {
        if (!selectedInvestment) return;
        setActionLoading(true);

        try {
            const res = await fetch('/api/admin/investments', {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    id: selectedInvestment._id,
                    amount: newCapital
                })
            });
            const data = await res.json();

            if (data.success) {
                setAlertState({ isOpen: true, title: 'Success', message: 'Investment capital updated successfully.', type: 'success' });
                setEditModalOpen(false);
                fetchInvestments();
            } else {
                setAlertState({ isOpen: true, title: 'Error', message: data.error, type: 'error' });
            }
        } catch (error) {
            setAlertState({ isOpen: true, title: 'Error', message: 'Failed to update investment', type: 'error' });
        } finally {
            setActionLoading(false);
        }
    };

    return (
        <AdminLayout>
            <section className="py-8 px-6 lg:px-8">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
                    <div>
                        <h1 className="text-3xl font-bold font-serif text-white">Manage Investments</h1>
                        <p className="text-gray-400">View and manage user investments.</p>
                    </div>
                </div>

                {/* Filters & Search */}
                <div className="flex flex-col md:flex-row gap-4 mb-6">
                    {/* Search */}
                    <div className="relative flex-1">
                        <FiSearch className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                        <input
                            type="text"
                            placeholder="Search by ID, User name or email..."
                            className="input-premium pl-12"
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                        />
                    </div>

                    {/* Tabs */}
                    <div className="flex bg-primary-900/50 p-1 rounded-lg border border-primary-700/50">
                        {['active', 'completed', 'all'].map((tab) => (
                            <button
                                key={tab}
                                onClick={() => setFilter(tab)}
                                className={`px-6 py-2 rounded-md text-sm font-medium transition-all ${filter === tab
                                    ? 'bg-accent-gold text-primary-950 shadow-lg'
                                    : 'text-gray-400 hover:text-white'
                                    }`}
                            >
                                {tab.charAt(0).toUpperCase() + tab.slice(1)}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Table */}
                <div className="card-premium overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead className="bg-primary-900/50 border-b border-primary-800">
                                <tr>
                                    <th className="px-6 py-4 text-left text-xs font-bold text-gray-400 uppercase tracking-wider">ID</th>
                                    <th className="px-6 py-4 text-left text-xs font-bold text-gray-400 uppercase tracking-wider">User</th>
                                    <th className="px-6 py-4 text-left text-xs font-bold text-gray-400 uppercase tracking-wider">Plan</th>
                                    <th className="px-6 py-4 text-left text-xs font-bold text-gray-400 uppercase tracking-wider">Capital</th>
                                    <th className="px-6 py-4 text-left text-xs font-bold text-gray-400 uppercase tracking-wider">Return</th>
                                    <th className="px-6 py-4 text-left text-xs font-bold text-gray-400 uppercase tracking-wider">Status</th>
                                    <th className="px-6 py-4 text-right text-xs font-bold text-gray-400 uppercase tracking-wider">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-primary-800">
                                {loading ? (
                                    <tr>
                                        <td colSpan={7} className="px-6 py-8 text-center text-gray-400">Loading investments...</td>
                                    </tr>
                                ) : investments.length === 0 ? (
                                    <tr>
                                        <td colSpan={7} className="px-6 py-8 text-center text-gray-400">No investments found.</td>
                                    </tr>
                                ) : (
                                    investments.map((inv) => (
                                        <tr key={inv._id} className="hover:bg-primary-900/20 transition-colors">
                                            <td className="px-6 py-4 text-sm font-mono text-gray-300">
                                                #{inv.investmentId || 'N/A'}
                                            </td>
                                            <td className="px-6 py-4">
                                                <Link href={`/admin/users/${inv.userId?._id}`} className="flex flex-col group">
                                                    <span className="text-sm font-medium text-white group-hover:text-accent-gold transition-colors">
                                                        {inv.userId?.firstName} {inv.userId?.lastName}
                                                    </span>
                                                    <span className="text-xs text-gray-500">{inv.userId?.email}</span>
                                                </Link>
                                            </td>
                                            <td className="px-6 py-4 text-sm text-gray-300">
                                                {inv.planId?.name}
                                                <span className="text-xs text-accent-gold ml-1">({inv.planId?.roiPercentage}%)</span>
                                            </td>
                                            <td className="px-6 py-4 text-sm font-mono text-white">
                                                ${inv.amount.toLocaleString()}
                                            </td>
                                            <td className="px-6 py-4 text-sm font-mono text-emerald-400">
                                                ${inv.expectedReturn.toLocaleString()}
                                            </td>
                                            <td className="px-6 py-4">
                                                <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${inv.status === 'active' ? 'bg-green-500/10 text-green-400 border border-green-500/20' :
                                                    inv.status === 'completed' ? 'bg-blue-500/10 text-blue-400 border border-blue-500/20' :
                                                        'bg-red-500/10 text-red-400 border border-red-500/20'
                                                    }`}>
                                                    {inv.status.toUpperCase()}
                                                </span>
                                            </td>
                                            <td className="px-6 py-4 text-right">
                                                {inv.status === 'active' && (
                                                    <div className="flex items-center justify-end space-x-2">
                                                        <button
                                                            onClick={() => handleEdit(inv)}
                                                            className="p-2 text-gray-400 hover:text-accent-gold hover:bg-white/5 rounded-lg transition-colors"
                                                            title="Edit Capital"
                                                        >
                                                            <FiEdit2 className="w-4 h-4" />
                                                        </button>
                                                        <button
                                                            onClick={() => handleCancel(inv._id)}
                                                            className="p-2 text-gray-400 hover:text-red-400 hover:bg-red-500/10 rounded-lg transition-colors"
                                                            title="Cancel & Refund"
                                                        >
                                                            <FiTrash2 className="w-4 h-4" />
                                                        </button>
                                                    </div>
                                                )}
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>

                {/* Edit Modal */}
                {editModalOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                        <div className="bg-background-dark border border-primary-700 rounded-2xl w-full max-w-md p-6 shadow-2xl animate-scale-in">
                            <div className="flex items-center justify-between mb-6">
                                <h3 className="text-xl font-bold font-serif text-white">Edit Investment Capital</h3>
                                <button onClick={() => setEditModalOpen(false)} className="text-gray-400 hover:text-white">
                                    <FiX className="w-6 h-6" />
                                </button>
                            </div>

                            <div className="mb-6 bg-primary-900/30 p-4 rounded-lg border border-primary-800/50">
                                <div className="flex items-start space-x-3 text-sm text-gray-300">
                                    <FiAlertCircle className="w-5 h-5 text-accent-gold flex-shrink-0 mt-0.5" />
                                    <p>
                                        Changing the capital will adjust the user&apos;s wallet balance automatically.
                                        If increasing, the difference will be deducted. If decreasing, the difference will be refunded.
                                    </p>
                                </div>
                            </div>

                            <div className="space-y-4 mb-8">
                                <div>
                                    <label className="block text-sm text-gray-400 mb-2">Investment Capital ($)</label>
                                    <input
                                        type="number"
                                        value={newCapital}
                                        onChange={(e) => setNewCapital(e.target.value)}
                                        className="input-premium text-lg font-mono"
                                        placeholder="0.00"
                                    />
                                </div>
                            </div>

                            <div className="flex space-x-3">
                                <button
                                    onClick={() => setEditModalOpen(false)}
                                    className="btn-secondary flex-1"
                                    disabled={actionLoading}
                                >
                                    Cancel
                                </button>
                                <button
                                    onClick={saveCapital}
                                    className="btn-primary flex-1 flex items-center justify-center space-x-2"
                                    disabled={actionLoading}
                                >
                                    {actionLoading ? 'Saving...' : <> <FiCheck /> <span>Update</span> </>}
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                <AlertModal
                    isOpen={alertState.isOpen}
                    onClose={() => setAlertState(prev => ({ ...prev, isOpen: false }))}
                    title={alertState.title}
                    message={alertState.message}
                    type={alertState.type}
                />
            </section>
        </AdminLayout>
    );
}

'use client';

import { useState, useEffect } from 'react';
import AdminLayout from '@/components/AdminLayout';
import { FiCheck, FiX, FiShield, FiUser, FiMapPin, FiCalendar, FiExternalLink } from 'react-icons/fi';
import AlertModal from '@/components/AlertModal';

interface KYCRequest {
    _id: string;
    userId: {
        _id: string;
        firstName: string;
        lastName: string;
        email: string;
    };
    fullName: string;
    country: string;
    address: string;
    idDocument: string;
    status: 'pending' | 'approved' | 'rejected';
    rejectionReason?: string;
    createdAt: string;
}

export default function AdminKYCPage() {
    const [kycs, setKycs] = useState<KYCRequest[]>([]);
    const [loading, setLoading] = useState(true);
    const [filter, setFilter] = useState('pending');

    // Modal State
    const [selectedKYC, setSelectedKYC] = useState<KYCRequest | null>(null);
    const [viewModalOpen, setViewModalOpen] = useState(false);
    const [rejectReason, setRejectReason] = useState('');
    const [showRejectInput, setShowRejectInput] = useState(false);

    const [alertState, setAlertState] = useState<{
        isOpen: boolean;
        title: string;
        message: string;
        type: 'success' | 'error' | 'info';
    }>({ isOpen: false, title: '', message: '', type: 'info' });

    const fetchKYCs = async () => {
        setLoading(true);
        try {
            const res = await fetch(`/api/admin/kyc?status=${filter}`);
            const data = await res.json();
            if (data.success) {
                setKycs(data.kycs);
            }
        } catch (error) {
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchKYCs();
    }, [filter]);

    const handleAction = async (status: 'approved' | 'rejected') => {
        if (!selectedKYC) return;

        if (status === 'rejected' && !showRejectInput) {
            setShowRejectInput(true);
            return;
        }

        try {
            const res = await fetch('/api/admin/kyc', {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    id: selectedKYC._id,
                    status,
                    reason: status === 'rejected' ? rejectReason : undefined
                })
            });
            const data = await res.json();

            if (data.success) {
                setAlertState({ isOpen: true, title: 'Success', message: `KYC ${status} successfully.`, type: 'success' });
                setViewModalOpen(false);
                setSelectedKYC(null);
                setRejectReason('');
                setShowRejectInput(false);
                fetchKYCs();
            } else {
                setAlertState({ isOpen: true, title: 'Error', message: data.error, type: 'error' });
            }

        } catch (error) {
            setAlertState({ isOpen: true, title: 'Error', message: 'Action failed', type: 'error' });
        }
    };

    const openViewModal = (kyc: KYCRequest) => {
        setSelectedKYC(kyc);
        setShowRejectInput(false);
        setRejectReason('');
        setViewModalOpen(true);
    };

    return (
        <AdminLayout>
            <section className="py-8 px-4 sm:px-6 lg:px-8">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-8">
                    <div>
                        <h1 className="text-2xl md:text-3xl font-bold font-serif text-white">KYC Applications</h1>
                        <p className="text-gray-400 text-sm md:text-base">Review and verify user identities.</p>
                    </div>
                    <div className="flex flex-wrap gap-2 bg-primary-900/50 p-1 rounded-lg w-full md:w-auto overflow-x-auto">
                        {['pending', 'approved', 'rejected', 'all'].map(t => (
                            <button key={t} onClick={() => setFilter(t)} className={`flex-1 md:flex-none px-3 py-2 text-xs md:text-sm font-medium rounded-md whitespace-nowrap transition-all ${filter === t ? 'bg-accent-gold text-primary-950 shadow-lg' : 'text-gray-400 hover:text-white'}`}>{t.charAt(0).toUpperCase() + t.slice(1)}</button>
                        ))}
                    </div>
                </div>

                {loading ? (
                    <div className="flex justify-center py-20"><div className="animate-spin rounded-full h-12 w-12 border-t-2 border-accent-gold" /></div>
                ) : (
                    <div className="card-premium overflow-hidden">
                        <div className="overflow-x-auto">
                            <table className="w-full whitespace-nowrap">
                                <thead className="text-xs uppercase text-gray-500 bg-primary-900/50">
                                    <tr>
                                        <th className="px-6 py-4 text-left">User</th>
                                        <th className="px-6 py-4 text-left">Submitted As</th>
                                        <th className="px-6 py-4 text-left">Country</th>
                                        <th className="px-6 py-4 text-left">Date</th>
                                        <th className="px-6 py-4 text-left">Status</th>
                                        <th className="px-6 py-4 text-right">Action</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-primary-800 text-sm">
                                    {kycs.length === 0 ? (
                                        <tr><td colSpan={6} className="px-6 py-8 text-center text-gray-500">No applications found.</td></tr>
                                    ) : (
                                        kycs.map(kyc => (
                                            <tr key={kyc._id} className="hover:bg-primary-900/20 transition-colors">
                                                <td className="px-6 py-4">
                                                    <div className="flex items-center">
                                                        <div className="w-8 h-8 rounded-full bg-primary-800 flex-shrink-0 flex items-center justify-center text-accent-gold mr-3">
                                                            <FiUser />
                                                        </div>
                                                        <div>
                                                            <div className="text-white font-medium">{kyc.userId?.firstName} {kyc.userId?.lastName}</div>
                                                            <div className="text-xs text-gray-500">{kyc.userId?.email}</div>
                                                        </div>
                                                    </div>
                                                </td>
                                                <td className="px-6 py-4 text-gray-300">{kyc.fullName}</td>
                                                <td className="px-6 py-4 text-gray-300">{kyc.country}</td>
                                                <td className="px-6 py-4 text-gray-400 font-mono">{new Date(kyc.createdAt).toLocaleDateString()}</td>
                                                <td className="px-6 py-4">
                                                    <span className={`px-2 py-1 rounded-full text-xs font-bold uppercase ${kyc.status === 'pending' ? 'bg-yellow-500/10 text-yellow-500' : kyc.status === 'approved' ? 'bg-green-500/10 text-green-400' : 'bg-red-500/10 text-red-400'}`}>{kyc.status}</span>
                                                </td>
                                                <td className="px-6 py-4 text-right">
                                                    <button onClick={() => openViewModal(kyc)} className="px-4 py-2 bg-primary-800 hover:bg-primary-700 text-white rounded-lg text-xs font-medium transition-colors">Review</button>
                                                </td>
                                            </tr>
                                        ))
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}
            </section>

            {/* View Modal */}
            {viewModalOpen && selectedKYC && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
                    <div className="bg-background-dark border border-primary-700 rounded-2xl w-full max-w-2xl max-h-[90vh] flex flex-col shadow-2xl animate-scale-in">
                        <div className="p-4 md:p-6 border-b border-primary-800 flex justify-between items-center flex-shrink-0">
                            <h3 className="text-lg md:text-xl font-bold font-serif text-white">KYC Application Review</h3>
                            <button onClick={() => setViewModalOpen(false)} className="text-gray-400 hover:text-white p-1"><FiX size={24} /></button>
                        </div>

                        <div className="p-4 md:p-6 overflow-y-auto custom-scrollbar">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8">
                                <div className="space-y-4 md:space-y-6">
                                    <div>
                                        <label className="text-xs text-gray-400 uppercase tracking-widest block mb-1">Applicant Name</label>
                                        <p className="text-base md:text-lg text-white font-medium bg-primary-900/40 p-3 rounded-lg border border-primary-800 break-words">{selectedKYC.fullName}</p>
                                    </div>
                                    <div>
                                        <label className="text-xs text-gray-400 uppercase tracking-widest block mb-1">Country</label>
                                        <p className="text-base md:text-lg text-white font-medium bg-primary-900/40 p-3 rounded-lg border border-primary-800 flex items-center"><FiMapPin className="mr-2 text-accent-gold flex-shrink-0" />{selectedKYC.country}</p>
                                    </div>
                                    <div>
                                        <label className="text-xs text-gray-400 uppercase tracking-widest block mb-1">Address</label>
                                        <p className="text-sm text-gray-300 bg-primary-900/40 p-3 rounded-lg border border-primary-800 min-h-[80px] break-words">{selectedKYC.address}</p>
                                    </div>
                                    <div>
                                        <label className="text-xs text-gray-400 uppercase tracking-widest block mb-1">Submitted On</label>
                                        <p className="text-sm text-gray-400 flex items-center"><FiCalendar className="mr-2" />{new Date(selectedKYC.createdAt).toLocaleString()}</p>
                                    </div>
                                </div>

                                <div>
                                    <label className="text-xs text-gray-400 uppercase tracking-widest block mb-3">ID Document</label>
                                    <div className="relative group rounded-xl overflow-hidden border border-primary-700 bg-black aspect-[4/3] flex items-center justify-center">
                                        <img src={selectedKYC.idDocument} alt="ID Document" className="w-full h-full object-contain" />
                                        <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                                            <a href={selectedKYC.idDocument} download={`kyc-${selectedKYC._id}.png`} className="px-4 py-2 bg-white text-black rounded-lg font-bold flex items-center text-sm transform translate-y-2 group-hover:translate-y-0 transition-transform">
                                                <FiExternalLink className="mr-2" /> Download
                                            </a>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="p-4 md:p-6 border-t border-primary-800 bg-primary-900/20 flex-shrink-0">
                            {showRejectInput ? (
                                <div className="space-y-4 animate-fade-in">
                                    <label className="text-sm text-red-400 font-bold block">Reason for Rejection</label>
                                    <textarea
                                        value={rejectReason}
                                        onChange={e => setRejectReason(e.target.value)}
                                        className="input-premium w-full h-24 text-sm"
                                        placeholder="Please explain why this application is being rejected..."
                                    ></textarea>
                                    <div className="flex gap-3">
                                        <button onClick={() => setShowRejectInput(false)} className="btn-secondary flex-1 text-sm">Cancel</button>
                                        <button onClick={() => handleAction('rejected')} className="btn-primary bg-red-600 hover:bg-red-700 border-red-600 text-white flex-1 text-sm">Confirm Rejection</button>
                                    </div>
                                </div>
                            ) : selectedKYC.status === 'pending' ? (
                                <div className="flex flex-col md:flex-row gap-3 md:gap-4">
                                    <button onClick={() => handleAction('rejected')} className="flex-1 py-3 bg-red-500/10 hover:bg-red-500/20 text-red-400 border border-red-500/20 rounded-xl font-bold transition-all text-sm">Reject Application</button>
                                    <button onClick={() => handleAction('approved')} className="flex-1 py-3 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-400 border border-emerald-500/20 rounded-xl font-bold transition-all text-sm">Approve & Verify</button>
                                </div>
                            ) : (
                                <div className="text-center">
                                    <p className={`text-lg font-bold ${selectedKYC.status === 'approved' ? 'text-emerald-400' : 'text-red-400'}`}>
                                        Application {selectedKYC.status.charAt(0).toUpperCase() + selectedKYC.status.slice(1)}
                                    </p>
                                    {selectedKYC.rejectionReason && <p className="text-sm text-gray-400 mt-2 break-words">Reason: {selectedKYC.rejectionReason}</p>}
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            )}

            <AlertModal isOpen={alertState.isOpen} onClose={() => setAlertState(prev => ({ ...prev, isOpen: false }))} title={alertState.title} message={alertState.message} type={alertState.type} />
        </AdminLayout>
    );
}

'use client';

import { useState, useEffect } from 'react';
import AdminLayout from '@/components/AdminLayout';
import { FiPieChart, FiPlus, FiEdit, FiTrash2, FiCheckCircle, FiX } from 'react-icons/fi';

export default function AdminPlansPage() {
    const [plans, setPlans] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedCategory, setSelectedCategory] = useState('all');
    const [showCreateModal, setShowCreateModal] = useState(false);
    const [showEditModal, setShowEditModal] = useState(false);
    const [creating, setCreating] = useState(false);
    const [editing, setEditing] = useState(false);
    const [editingPlanId, setEditingPlanId] = useState<string | null>(null);

    // Form state
    const [formData, setFormData] = useState({
        name: '',
        description: '',
        category: 'crypto',
        minInvestment: '',
        maxInvestment: '',
        duration: '',
        roiPercentage: '',
        riskLevel: 'low',
        payoutFrequency: 'at-end',
        features: '',
        isActive: true,
    });

    useEffect(() => {
        fetchPlans();
    }, [selectedCategory]);

    const fetchPlans = async () => {
        try {
            const url = selectedCategory === 'all'
                ? '/api/plans'
                : `/api/plans?category=${selectedCategory}`;

            const response = await fetch(url);
            const data = await response.json();

            if (data.success) {
                setPlans(data.plans);
            }
        } catch (error) {
            console.error('Error fetching plans:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleCreatePlan = async (e: React.FormEvent) => {
        e.preventDefault();
        setCreating(true);

        try {
            const featuresArray = formData.features
                .split('\n')
                .map(f => f.trim())
                .filter(f => f.length > 0);

            const planData = {
                ...formData,
                minInvestment: Number(formData.minInvestment),
                maxInvestment: Number(formData.maxInvestment),
                duration: Number(formData.duration),
                roiPercentage: Number(formData.roiPercentage),
                features: featuresArray,
            };

            const response = await fetch('/api/plans', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'x-is-admin': 'true',
                },
                body: JSON.stringify(planData),
            });

            const data = await response.json();

            if (data.success) {
                setShowCreateModal(false);
                setFormData({
                    name: '',
                    description: '',
                    category: 'crypto',
                    minInvestment: '',
                    maxInvestment: '',
                    duration: '',
                    roiPercentage: '',
                    riskLevel: 'low',
                    payoutFrequency: 'at-end',
                    features: '',
                    isActive: true,
                });
                fetchPlans();
                alert('Plan created successfully!');
            } else {
                alert(data.message || 'Failed to create plan');
            }
        } catch (error) {
            console.error('Error creating plan:', error);
            alert('An error occurred while creating the plan');
        } finally {
            setCreating(false);
        }
    };

    const openEditModal = (plan: any) => {
        setEditingPlanId(plan._id);
        setFormData({
            name: plan.name,
            description: plan.description,
            category: plan.category,
            minInvestment: plan.minInvestment.toString(),
            maxInvestment: plan.maxInvestment.toString(),
            duration: plan.duration.toString(),
            roiPercentage: plan.roiPercentage.toString(),
            riskLevel: plan.riskLevel,
            payoutFrequency: plan.payoutFrequency || 'at-end',
            features: plan.features.join('\n'),
            isActive: plan.isActive,
        });
        setShowEditModal(true);
    };

    const handleEditPlan = async (e: React.FormEvent) => {
        e.preventDefault();
        setEditing(true);

        try {
            const featuresArray = formData.features
                .split('\n')
                .map(f => f.trim())
                .filter(f => f.length > 0);

            const planData = {
                planId: editingPlanId,
                ...formData,
                minInvestment: Number(formData.minInvestment),
                maxInvestment: Number(formData.maxInvestment),
                duration: Number(formData.duration),
                roiPercentage: Number(formData.roiPercentage),
                features: featuresArray,
            };

            const response = await fetch('/api/plans', {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                    'x-is-admin': 'true',
                },
                body: JSON.stringify(planData),
            });

            const data = await response.json();

            if (data.success) {
                setShowEditModal(false);
                setEditingPlanId(null);
                setFormData({
                    name: '',
                    description: '',
                    category: 'crypto',
                    minInvestment: '',
                    maxInvestment: '',
                    duration: '',
                    roiPercentage: '',
                    riskLevel: 'low',
                    payoutFrequency: 'at-end',
                    features: '',
                    isActive: true,
                });
                fetchPlans();
                alert('Plan updated successfully!');
            } else {
                alert(data.message || 'Failed to update plan');
            }
        } catch (error) {
            console.error('Error updating plan:', error);
            alert('An error occurred while updating the plan');
        } finally {
            setEditing(false);
        }
    };

    const openCreateModal = () => {
        // Reset form to default values
        setFormData({
            name: '',
            description: '',
            category: 'crypto',
            minInvestment: '',
            maxInvestment: '',
            duration: '',
            roiPercentage: '',
            riskLevel: 'low',
            payoutFrequency: 'at-end',
            features: '',
            isActive: true,
        });
        setShowCreateModal(true);
    };

    const handleDelete = async (planId: string) => {
        if (!confirm('Are you sure you want to delete this plan?')) return;

        try {
            const response = await fetch(`/api/plans?planId=${planId}`, {
                method: 'DELETE',
                headers: {
                    'x-is-admin': 'true',
                },
            });

            const data = await response.json();

            if (data.success) {
                fetchPlans();
            } else {
                alert(data.message || 'Failed to delete plan');
            }
        } catch (error) {
            console.error('Error deleting plan:', error);
            alert('An error occurred while deleting the plan');
        }
    };

    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('en-US', {
            style: 'currency',
            currency: 'USD',
            minimumFractionDigits: 0,
        }).format(amount);
    };

    const categoryConfig: Record<string, { label: string; gradient: string; icon: string }> = {
        crypto: { label: 'Cryptocurrency', gradient: 'from-orange-500 to-yellow-500', icon: '₿' },
        'real-estate': { label: 'Real Estate', gradient: 'from-blue-500 to-cyan-500', icon: '🏢' },
        agriculture: { label: 'Agriculture', gradient: 'from-green-500 to-emerald-500', icon: '🌾' },
        stocks: { label: 'Stocks', gradient: 'from-purple-500 to-pink-500', icon: '📈' },
    };

    const categories = [
        { value: 'all', label: 'All Categories' },
        { value: 'crypto', label: 'Cryptocurrency' },
        { value: 'real-estate', label: 'Real Estate' },
        { value: 'agriculture', label: 'Agriculture' },
        { value: 'stocks', label: 'Stocks' },
    ];

    const sortOptions = [
        { value: 'amount-low', label: 'Lowest Amount' },
        { value: 'amount-high', label: 'Highest Amount' },
        { value: 'roi-high', label: 'Highest ROI' },
        { value: 'roi-low', label: 'Lowest ROI' },
        { value: 'duration-short', label: 'Shortest Duration' },
        { value: 'duration-long', label: 'Longest Duration' },
        { value: 'newest', label: 'Newest First' },
        { value: 'oldest', label: 'Oldest First' },
    ];

    const [sortBy, setSortBy] = useState('amount-low');

    // Filter by category
    const filteredPlans = selectedCategory === 'all'
        ? plans
        : plans.filter(p => p.category === selectedCategory);

    // Sort plans
    const sortedPlans = [...filteredPlans].sort((a, b) => {
        switch (sortBy) {
            case 'amount-low':
                return a.minInvestment - b.minInvestment;
            case 'amount-high':
                return b.minInvestment - a.minInvestment;
            case 'roi-high':
                return b.roiPercentage - a.roiPercentage;
            case 'roi-low':
                return a.roiPercentage - b.roiPercentage;
            case 'duration-short':
                return a.duration - b.duration;
            case 'duration-long':
                return b.duration - a.duration;
            case 'newest':
                return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
            case 'oldest':
                return new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime();
            default:
                return a.minInvestment - b.minInvestment;
        }
    });

    return (
        <AdminLayout>
            <section className="py-8">
                <div className="px-6 lg:px-8">
                    <div className="flex items-center justify-between mb-6">
                        <div>
                            <h1 className="text-3xl font-bold font-serif text-white mb-2">
                                Investment Plans
                            </h1>
                            <p className="text-gray-400">Create and manage investment plans</p>
                        </div>
                        <button
                            onClick={openCreateModal}
                            className="btn-primary flex items-center space-x-2"
                        >
                            <FiPlus className="w-5 h-5" />
                            <span>Create New Plan</span>
                        </button>
                    </div>

                    {/* Category Filter */}
                    <div className="mb-6">
                        <div className="flex flex-wrap gap-2">
                            {categories.map((cat) => (
                                <button
                                    key={cat.value}
                                    onClick={() => setSelectedCategory(cat.value)}
                                    className={`px-4 py-2 rounded-lg font-semibold text-sm transition-all duration-200 ${selectedCategory === cat.value
                                        ? 'bg-accent-gold text-primary-950'
                                        : 'bg-primary-800 text-gray-300 hover:bg-primary-700'
                                        }`}
                                >
                                    {cat.label}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Sort & Stats */}
                    <div className="mb-6 flex items-center justify-between">
                        <div className="flex items-center space-x-3">
                            <p className="text-sm text-gray-400">
                                Showing <span className="text-accent-gold font-semibold">{sortedPlans.length}</span> plan{sortedPlans.length !== 1 ? 's' : ''}
                            </p>
                        </div>
                        <div className="flex items-center space-x-3">
                            <label className="text-sm text-gray-400">Sort by:</label>
                            <select
                                value={sortBy}
                                onChange={(e) => setSortBy(e.target.value)}
                                className="input-premium py-2 px-4 text-sm"
                            >
                                {sortOptions.map((option) => (
                                    <option key={option.value} value={option.value}>
                                        {option.label}
                                    </option>
                                ))}
                            </select>
                        </div>
                    </div>

                    {loading ? (
                        <div className="flex items-center justify-center py-20">
                            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-accent-gold"></div>
                        </div>
                    ) : sortedPlans.length === 0 ? (
                        <div className="card-premium text-center py-12">
                            <div className="w-16 h-16 rounded-full bg-primary-800/50 flex items-center justify-center mx-auto mb-4">
                                <FiPieChart className="w-8 h-8 text-gray-500" />
                            </div>
                            <p className="text-gray-400 mb-4">No investment plans found</p>
                            <p className="text-sm text-gray-500 mb-4">
                                Seed the database with plans by visiting:
                            </p>
                            <a
                                href="/api/seed/plans"
                                target="_blank"
                                className="btn-secondary inline-flex items-center space-x-2"
                            >
                                <span>Seed Plans</span>
                            </a>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            {sortedPlans.map((plan) => {
                                const category = categoryConfig[plan.category];
                                return (
                                    <div key={plan._id} className="card-premium">
                                        <div className="flex items-start justify-between">
                                            <div className="flex items-center space-x-4 flex-grow">
                                                <div
                                                    className={`w-16 h-16 rounded-xl bg-gradient-to-br ${category.gradient} flex items-center justify-center text-2xl flex-shrink-0`}
                                                >
                                                    {category.icon}
                                                </div>
                                                <div className="flex-grow">
                                                    <div className="flex items-center space-x-3 mb-2">
                                                        <h3 className="text-xl font-bold text-white">{plan.name}</h3>
                                                        <span
                                                            className={`badge ${plan.isActive ? 'badge-emerald' : 'bg-gray-700 text-gray-400'
                                                                }`}
                                                        >
                                                            {plan.isActive ? 'Active' : 'Inactive'}
                                                        </span>
                                                    </div>
                                                    <p className="text-sm text-gray-400 mb-3">{plan.description}</p>

                                                    <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                                                        <div>
                                                            <p className="text-xs text-gray-500">ROI</p>
                                                            <p className="text-lg font-bold text-accent-gold font-mono">
