'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import AdminLayout from '@/components/AdminLayout';
import { useSiteSettings } from '@/context/SiteContext';
import AlertModal from '@/components/AlertModal';
import { FiSave, FiSettings, FiImage, FiUploadCloud, FiMail, FiSend, FiKey, FiServer, FiSlash, FiGlobe, FiCode, FiPlus, FiTrash2, FiAlertTriangle } from 'react-icons/fi';

export default function AdminSettingsPage() {
    const { refreshSettings } = useSiteSettings();
    const router = useRouter();
    const [activeTab, setActiveTab] = useState<'general' | 'email' | 'seo'>('general');
    const [showWarning, setShowWarning] = useState(true);

    // ... (rest of state)

    const handleProceed = () => {
        setShowWarning(false);
    };

    const handleDecline = () => {
        router.push('/admin');
    };


    // Combined form data
    const [formData, setFormData] = useState({
        // General
        siteName: '',
        contactEmail: '',
        siteLogo: '',
        primaryColor: '#0a0e1a',
        accentColor: '#953bad',
        minDeposit: 100,
        minWithdrawal: 50,

        // Email
        emailProvider: 'none',
        mailjetApiKey: '',
        mailjetSecretKey: '',
        smtpHost: '',
        smtpPort: 587,
        smtpUser: '',
        smtpPassword: '',
        smtpSecure: false,
        senderEmail: '',
        senderName: '',
        adminReceiverEmail: '',

        // SEO
        seoTitle: '',
        seoDescription: '',
        seoKeywords: '',

        // Scripts
        customScripts: [] as { name: string, content: string, location: 'head' | 'body', isActive: boolean }[]
    });

    const [loading, setLoading] = useState(false);
    const [testingEmail, setTestingEmail] = useState(false);
    const [scriptName, setScriptName] = useState('');
    const [scriptContent, setScriptContent] = useState('');
    const [scriptLocation, setScriptLocation] = useState<'head' | 'body'>('head');

    // Alert State
    const [alertState, setAlertState] = useState<{
        isOpen: boolean;
        title: string;
        message: string;
        type: 'success' | 'error' | 'info';
    }>({
        isOpen: false,
        title: '',
        message: '',
        type: 'info'
    });

    useEffect(() => {
        const fetchSettings = async () => {
            try {
                const res = await fetch('/api/admin/settings', { headers: { 'x-is-admin': 'true' } });
                const data = await res.json();
                if (data.success && data.settings) {
                    const s = data.settings;
                    let provider = s.emailProvider || 'none';
                    if (provider === 'none' && s.emailEnabled) provider = 'mailjet';

                    setFormData({
                        siteName: s.siteName || '',
                        contactEmail: s.contactEmail || '',
                        siteLogo: s.siteLogo || '',
                        primaryColor: s.primaryColor || '#0a0e1a',
                        accentColor: s.accentColor || '#953bad',
                        minDeposit: s.minDeposit || 100,
                        minWithdrawal: s.minWithdrawal || 50,

                        emailProvider: provider,
                        mailjetApiKey: s.mailjetApiKey || '',
                        mailjetSecretKey: s.mailjetSecretKey || '',
                        smtpHost: s.smtpHost || '',
                        smtpPort: s.smtpPort || 587,
                        smtpUser: s.smtpUser || '',
                        smtpPassword: s.smtpPassword || '',
                        smtpSecure: s.smtpSecure || false,
                        senderEmail: s.senderEmail || '',
                        senderName: s.senderName || 'Myf Capitals',
                        adminReceiverEmail: s.adminReceiverEmail || '',

                        seoTitle: s.seoTitle || '',
                        seoDescription: s.seoDescription || '',
                        seoKeywords: s.seoKeywords || '',
                        customScripts: s.customScripts || []
                    });
                }
            } catch (error) {
                console.error('Failed to fetch admin settings', error);
            }
        };
        fetchSettings();
    }, []);

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (event) => {
                const img = new Image();
                img.onload = () => {
                    const canvas = document.createElement('canvas');
                    let width = img.width;
                    let height = img.height;
                    const MAX_WIDTH = 500;
                    const MAX_HEIGHT = 500;
                    if (width > height) {
                        if (width > MAX_WIDTH) { height *= MAX_WIDTH / width; width = MAX_WIDTH; }
                    } else {
                        if (height > MAX_HEIGHT) { width *= MAX_HEIGHT / height; height = MAX_HEIGHT; }
                    }
                    canvas.width = width;
                    canvas.height = height;
                    const ctx = canvas.getContext('2d');
                    ctx?.drawImage(img, 0, 0, width, height);
                    const compressedBase64 = canvas.toDataURL('image/png', 0.8);
                    setFormData(prev => ({ ...prev, siteLogo: compressedBase64 }));
                };
                img.src = event.target?.result as string;
            };
            reader.readAsDataURL(file);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        try {
            const res = await fetch('/api/admin/settings', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'x-is-admin': 'true' },
                body: JSON.stringify(formData)
            });
            const data = await res.json();
            if (data.success) {
                setAlertState({ isOpen: true, title: 'Settings Saved', message: 'Settings updated successfully.', type: 'success' });
                refreshSettings();
            } else {
                throw new Error(data.error);
            }
        } catch (error: any) {
            setAlertState({ isOpen: true, title: 'Save Failed', message: error.message, type: 'error' });
        } finally {
            setLoading(false);
        }
    };

    const handleTestEmail = async () => {
        if (formData.emailProvider === 'none') return;
        setTestingEmail(true);
        try {
            const res = await fetch('/api/admin/settings/test-email', { method: 'POST' });
            const data = await res.json();
            if (data.success) {
                setAlertState({ isOpen: true, title: 'Test Successful', message: data.message || `Email sent successfully.`, type: 'success' });
            } else {
                throw new Error(data.error);
            }
        } catch (error: any) {
            setAlertState({ isOpen: true, title: 'Test Failed', message: error.message, type: 'error' });
        } finally {
            setTestingEmail(false);
        }
    };

    const addScript = () => {
        if (!scriptName || !scriptContent) return;
        setFormData(prev => ({
            ...prev,
            customScripts: [...prev.customScripts, { name: scriptName, content: scriptContent, location: scriptLocation, isActive: true }]
        }));
        setScriptName('');
        setScriptContent('');
    };

    const removeScript = (index: number) => {
        setFormData(prev => ({
            ...prev,
            customScripts: prev.customScripts.filter((_, i) => i !== index)
        }));
    };

    // ... rest of logic (hooks are here)

    if (showWarning) {
        return (
            <AdminLayout>
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
                    <div className="bg-primary-900 border border-red-500/50 rounded-2xl p-8 max-w-md w-full shadow-2xl animate-fade-in relative overflow-hidden">
                        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-red-500 to-orange-500"></div>
                        <div className="flex flex-col items-center text-center space-y-4">
                            <div className="w-16 h-16 rounded-full bg-red-500/10 flex items-center justify-center mb-2">
                                <FiAlertTriangle className="w-8 h-8 text-red-500" />
                            </div>
                            <h2 className="text-2xl font-bold text-white">Critical Area</h2>
                            <p className="text-gray-300">
                                You are about to access the <span className="text-white font-semibold">System Settings</span>.
                                Incorrect changes here can break the platform or cause data issues.
                            </p>
                            <p className="text-sm text-gray-500 bg-primary-950/50 p-3 rounded-lg border border-primary-800">
                                This section is intended for <span className="text-accent-gold">Developers and Technical Professionals</span> only.
                            </p>

                            <div className="flex w-full gap-4 pt-4">
                                <button
                                    onClick={handleDecline}
                                    className="flex-1 px-4 py-3 rounded-xl font-medium text-gray-400 hover:text-white hover:bg-white/5 transition-colors border border-transparent hover:border-white/10"
                                >
                                    Go Back
                                </button>
                                <button
                                    onClick={handleProceed}
                                    className="flex-1 px-4 py-3 rounded-xl font-bold text-white bg-red-600 hover:bg-red-700 transition-colors shadow-lg shadow-red-900/20"
                                >
                                    I Understand, Proceed
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </AdminLayout>
        );
    }

    return (
        <AdminLayout>
            <section className="py-8 px-6 lg:px-8">
                <div className="flex items-center justify-between mb-8">
                    <div className="flex items-center space-x-3">
                        <div className="w-12 h-12 rounded-xl bg-accent-gold/20 flex items-center justify-center">
                            <FiSettings className="w-6 h-6 text-accent-gold" />
                        </div>
                        <div>
                            <h1 className="text-3xl font-bold font-serif text-white">System Settings</h1>
                            <p className="text-gray-400">Configure platform identity, emails, and SEO.</p>
                        </div>
                    </div>
                </div>

                <div className="flex space-x-4 border-b border-primary-800 mb-8 overflow-x-auto">
                    {['general', 'email', 'seo'].map((tab) => (
                        <button
                            key={tab}
                            onClick={() => setActiveTab(tab as any)}
                            className={`pb-4 px-4 font-medium transition-colors relative whitespace-nowrap ${activeTab === tab ? 'text-accent-gold' : 'text-gray-400 hover:text-white'}`}
                        >
                            {tab === 'general' ? 'General Settings' : tab === 'email' ? 'Email Integration' : 'SEO & Scripts'}
                            {activeTab === tab && <span className="absolute bottom-0 left-0 right-0 h-0.5 bg-accent-gold rounded-t-full"></span>}
                        </button>
                    ))}
                </div>

                <div className="card-premium max-w-4xl">
                    <form onSubmit={handleSubmit} className="space-y-8">

                        {/* GENERAL TAB */}
                        {activeTab === 'general' && (
                            <div className="space-y-8 animate-fade-in">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                    <div>
                                        <label className="block text-sm text-gray-400 mb-2">Platform Name</label>
                                        <input type="text" value={formData.siteName} onChange={e => setFormData({ ...formData, siteName: e.target.value })} className="input-premium" required />
                                    </div>
                                    <div>
                                        <label className="block text-sm text-gray-400 mb-2">Support Email</label>
                                        <input type="email" value={formData.contactEmail} onChange={e => setFormData({ ...formData, contactEmail: e.target.value })} className="input-premium" />
                                    </div>
                                </div>
                                <hr className="border-primary-800" />
                                <div>
                                    <h3 className="text-lg font-bold text-white mb-4 flex items-center">
                                        <FiImage className="mr-2 text-accent-gold" /> Platform Logo
                                    </h3>
                                    <div className="flex flex-col md:flex-row items-center gap-8">
                                        <div className="w-40 h-40 bg-primary-900 border border-primary-700 rounded-xl flex items-center justify-center p-4 relative overflow-hidden">
                                            {formData.siteLogo ? <img src={formData.siteLogo} alt="Logo Preview" className="max-w-full max-h-full object-contain" /> : <span className="text-gray-600 text-sm">No Logo</span>}
                                        </div>
                                        <div className="flex-1">
                                            <input type="file" accept="image/*" onChange={handleFileChange} className="block w-full text-sm text-gray-400 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-primary-800 file:text-accent-gold hover:file:bg-primary-700 cursor-pointer" />
                                        </div>
                                    </div>
                                </div>
                                <hr className="border-primary-800" />
                                <div>
                                    <h3 className="text-lg font-bold text-white mb-4">Theme Colors</h3>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                        <div className="flex items-center space-x-3">
                                            <input type="color" value={formData.primaryColor} onChange={e => setFormData({ ...formData, primaryColor: e.target.value })} className="h-10 w-20 bg-transparent border border-primary-700 rounded cursor-pointer" />
                                            <input type="text" value={formData.primaryColor} onChange={e => setFormData({ ...formData, primaryColor: e.target.value })} className="input-premium flex-1" />
                                        </div>
                                        <div className="flex items-center space-x-3">
                                            <input type="color" value={formData.accentColor} onChange={e => setFormData({ ...formData, accentColor: e.target.value })} className="h-10 w-20 bg-transparent border border-primary-700 rounded cursor-pointer" />
                                            <input type="text" value={formData.accentColor} onChange={e => setFormData({ ...formData, accentColor: e.target.value })} className="input-premium flex-1" />
                                        </div>
                                    </div>
                                </div>
                                <hr className="border-primary-800" />
                                <div>
                                    <h3 className="text-lg font-bold text-white mb-4">Financial Limits</h3>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                        <div>
                                            <label className="block text-sm text-gray-400 mb-2">Minimum Deposit ($)</label>
                                            <input type="number" value={formData.minDeposit} onChange={e => setFormData({ ...formData, minDeposit: parseInt(e.target.value) })} className="input-premium" />
                                        </div>
                                        <div>
                                            <label className="block text-sm text-gray-400 mb-2">Minimum Withdrawal ($)</label>
                                            <input type="number" value={formData.minWithdrawal} onChange={e => setFormData({ ...formData, minWithdrawal: parseInt(e.target.value) })} className="input-premium" />
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}

                        {/* EMAIL TAB */}
                        {activeTab === 'email' && (
                            <div className="space-y-8 animate-fade-in">
                                <div className="flex flex-col md:flex-row items-center justify-between bg-primary-800/20 p-6 rounded-xl border border-primary-700 gap-4">
                                    <div className="flex items-center space-x-3">
                                        <div className={`w-10 h-10 rounded-lg flex items-center justify-center ${formData.emailProvider !== 'none' ? 'bg-accent-gold/20 text-accent-gold' : 'bg-gray-800 text-gray-500'}`}>
                                            {formData.emailProvider === 'mailjet' && <FiSend size={20} />}
                                            {formData.emailProvider === 'smtp' && <FiServer size={20} />}
                                            {formData.emailProvider === 'none' && <FiSlash size={20} />}
                                        </div>
                                        <div>
                                            <h3 className="text-white font-bold">Email Service Provider</h3>
                                            <p className="text-sm text-gray-400">Select which service to use for notifications</p>
                                        </div>
                                    </div>
                                    <div className="flex bg-primary-900 rounded-lg p-1 border border-primary-700">
                                        <button type="button" onClick={() => setFormData({ ...formData, emailProvider: 'smtp' })} className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${formData.emailProvider === 'smtp' ? 'bg-accent-gold text-primary-950 shadow-lg' : 'text-gray-400 hover:text-white'}`}>SMTP</button>
                                        <button type="button" onClick={() => setFormData({ ...formData, emailProvider: 'none' })} className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${formData.emailProvider === 'none' ? 'bg-gray-700 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}>Disabled</button>
                                        <button type="button" onClick={() => setFormData({ ...formData, emailProvider: 'mailjet' })} className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${formData.emailProvider === 'mailjet' ? 'bg-accent-gold text-primary-950 shadow-lg' : 'text-gray-400 hover:text-white'}`}>Mailjet</button>
                                    </div>
                                </div>

                                <div className={`space-y-8 transition-opacity duration-300 ${formData.emailProvider === 'none' ? 'opacity-50 pointer-events-none grayscale' : 'opacity-100'}`}>
                                    {formData.emailProvider === 'mailjet' && (
                                        <div className="animate-fade-in grid grid-cols-1 md:grid-cols-2 gap-8 p-6 bg-primary-900/10 border border-primary-700/50 rounded-xl">
                                            <div className="md:col-span-2 flex items-center space-x-2 text-accent-gold border-b border-primary-800 pb-2 mb-2"><FiKey /> <h3 className="font-bold">Mailjet Configuration</h3></div>
                                            <div><label className="block text-sm text-gray-400 mb-2">API Key</label><input type="text" value={formData.mailjetApiKey} onChange={e => setFormData({ ...formData, mailjetApiKey: e.target.value })} className="input-premium" /></div>
                                            <div><label className="block text-sm text-gray-400 mb-2">Secret Key</label><input type="password" value={formData.mailjetSecretKey} onChange={e => setFormData({ ...formData, mailjetSecretKey: e.target.value })} className="input-premium" /></div>
                                        </div>
                                    )}
                                    {formData.emailProvider === 'smtp' && (
                                        <div className="animate-fade-in grid grid-cols-1 md:grid-cols-2 gap-6 p-6 bg-primary-900/10 border border-primary-700/50 rounded-xl">
                                            <div className="md:col-span-2 flex items-center space-x-2 text-accent-gold border-b border-primary-800 pb-2 mb-2"><FiServer /> <h3 className="font-bold">SMTP Configuration</h3></div>
                                            <div><label className="block text-sm text-gray-400 mb-2">SMTP Host</label><input type="text" value={formData.smtpHost} onChange={e => setFormData({ ...formData, smtpHost: e.target.value })} className="input-premium" placeholder="smtp.example.com" /></div>
                                            <div><label className="block text-sm text-gray-400 mb-2">SMTP Port</label><input type="number" value={formData.smtpPort} onChange={e => setFormData({ ...formData, smtpPort: parseInt(e.target.value) })} className="input-premium" placeholder="587" /></div>
                                            <div><label className="block text-sm text-gray-400 mb-2">SMTP User</label><input type="text" value={formData.smtpUser} onChange={e => setFormData({ ...formData, smtpUser: e.target.value })} className="input-premium" placeholder="user@example.com" /></div>
                                            <div><label className="block text-sm text-gray-400 mb-2">SMTP Password</label><input type="password" value={formData.smtpPassword} onChange={e => setFormData({ ...formData, smtpPassword: e.target.value })} className="input-premium" placeholder="********" /></div>
                                            <div className="md:col-span-2 flex items-center space-x-2"><input type="checkbox" id="smtpSecure" checked={formData.smtpSecure} onChange={e => setFormData({ ...formData, smtpSecure: e.target.checked })} className="w-4 h-4 rounded" /><label htmlFor="smtpSecure" className="text-sm text-gray-400 cursor-pointer">Use Secure Connection (SSL/TLS)</label></div>
                                        </div>
                                    )}
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                        <div><label className="block text-sm text-gray-400 mb-2">Sender Email</label><input type="email" value={formData.senderEmail} onChange={e => setFormData({ ...formData, senderEmail: e.target.value })} className="input-premium" /></div>
                                        <div><label className="block text-sm text-gray-400 mb-2">Sender Name</label><input type="text" value={formData.senderName} onChange={e => setFormData({ ...formData, senderName: e.target.value })} className="input-premium" /></div>
                                    </div>
                                    <hr className="border-primary-800" />
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                        <div><label className="block text-sm text-gray-400 mb-2">Admin Receiver Email</label><input type="email" value={formData.adminReceiverEmail} onChange={e => setFormData({ ...formData, adminReceiverEmail: e.target.value })} className="input-premium" /></div>
                                        <div className="flex items-end"><button type="button" onClick={handleTestEmail} disabled={testingEmail || formData.emailProvider === 'none'} className="w-full btn-secondary h-[46px] flex items-center justify-center space-x-2">{testingEmail ? <span>Sending...</span> : <> <FiSend /> <span>Test Connection</span> </>}</button></div>
                                    </div>
                                </div>
                            </div>
                        )}

                        {/* SEO & SCRIPTS TAB */}
                        {activeTab === 'seo' && (
                            <div className="space-y-8 animate-fade-in">
                                <section>
                                    <h3 className="text-xl font-bold text-white mb-6 flex items-center"><FiGlobe className="mr-2 text-accent-gold" /> Global SEO Settings</h3>
                                    <div className="grid grid-cols-1 gap-6">
                                        <div>
                                            <label className="block text-sm text-gray-400 mb-2">Meta Title (Default)</label>
                                            <input type="text" value={formData.seoTitle} onChange={e => setFormData({ ...formData, seoTitle: e.target.value })} className="input-premium" />
                                        </div>
                                        <div>
                                            <label className="block text-sm text-gray-400 mb-2">Meta Description</label>
                                            <textarea value={formData.seoDescription} onChange={e => setFormData({ ...formData, seoDescription: e.target.value })} className="input-premium h-24" />
                                        </div>
                                        <div>
                                            <label className="block text-sm text-gray-400 mb-2">Meta Keywords</label>
                                            <input type="text" value={formData.seoKeywords} onChange={e => setFormData({ ...formData, seoKeywords: e.target.value })} className="input-premium" placeholder="invest, wealth, crypto..." />
                                        </div>
                                    </div>
                                </section>

                                <hr className="border-primary-800" />

                                <section>
                                    <h3 className="text-xl font-bold text-white mb-6 flex items-center"><FiCode className="mr-2 text-accent-gold" /> Custom Scripts & Widgets</h3>

                                    {/* Add New Script */}
                                    <div className="bg-primary-800/20 p-6 rounded-xl border border-primary-700 mb-6">
                                        <h4 className="text-white font-medium mb-4">Add New Script</h4>
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                                            <input type="text" value={scriptName} onChange={e => setScriptName(e.target.value)} placeholder="Script Name (e.g. Analytics)" className="input-premium" />
                                            <select value={scriptLocation} onChange={e => setScriptLocation(e.target.value as any)} className="input-premium bg-primary-950">
                                                <option value="head">Header (Head Tag)</option>
                                                <option value="body">Body (End of Body)</option>
                                            </select>
                                        </div>
                                        <div className="mb-4">
                                            <textarea value={scriptContent} onChange={e => setScriptContent(e.target.value)} placeholder="<script>...</script> or <div>...</div>" className="input-premium h-24 font-mono text-sm" />
                                        </div>
                                        <div className="flex justify-end">
                                            <button type="button" onClick={addScript} className="btn-secondary px-6 py-2 flex items-center"><FiPlus className="mr-2" /> Add Script</button>
                                        </div>
                                    </div>

                                    {/* Script List */}
                                    <div className="space-y-4">
                                        {formData.customScripts.map((script, idx) => (
                                            <div key={idx} className="bg-primary-900 border border-primary-700 rounded-lg p-4 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                                                <div>
                                                    <div className="flex items-center space-x-2">
                                                        <span className="font-bold text-white">{script.name}</span>
                                                        <span className="text-xs bg-primary-800 text-accent-gold px-2 py-1 rounded border border-primary-700 uppercase">{script.location}</span>
                                                    </div>
                                                    <div className="text-xs text-gray-500 mt-1 font-mono truncate max-w-sm">{script.content.substring(0, 50)}...</div>
                                                </div>
                                                <div className="flex items-center space-x-2">
                                                    <button
                                                        type="button"
                                                        onClick={() => {
                                                            const newScripts = [...formData.customScripts];
                                                            newScripts[idx].isActive = !newScripts[idx].isActive;
                                                            setFormData({ ...formData, customScripts: newScripts });
                                                        }}
                                                        className={`px-3 py-1 rounded text-xs font-medium border ${script.isActive ? 'border-green-500/50 text-green-500 bg-green-500/10' : 'border-gray-600 text-gray-400'}`}
                                                    >
                                                        {script.isActive ? 'Active' : 'Inactive'}
                                                    </button>
                                                    <button type="button" onClick={() => removeScript(idx)} className="p-2 text-red-400 hover:text-red-300 transition-colors"><FiTrash2 /></button>
                                                </div>
                                            </div>
                                        ))}
                                        {formData.customScripts.length === 0 && <p className="text-center text-gray-500 py-4">No custom scripts added yet.</p>}
                                    </div>
                                </section>
                            </div>
                        )}

                        <div className="border-t border-primary-800 pt-6 flex justify-end">
                            <button type="submit" disabled={loading} className="btn-primary px-8 py-3 flex items-center space-x-2">
                                {loading ? <span>Saving...</span> : <><FiSave /> <span>Save Changes</span></>}
                            </button>
                        </div>
                    </form>
                </div>
            </section >

            <AlertModal
                isOpen={alertState.isOpen}
                onClose={() => setAlertState(prev => ({ ...prev, isOpen: false }))}
                title={alertState.title}
                message={alertState.message}
                type={alertState.type}
            />
        </AdminLayout >
    );
}

'use client';

import { useState, useEffect, use } from 'react';
import AdminLayout from '@/components/AdminLayout';
import { useRouter } from 'next/navigation';
import { FiArrowLeft, FiUser, FiMail, FiPhone, FiMapPin, FiShield, FiClock, FiLock, FiEdit2, FiSave, FiPlus, FiMinus, FiCreditCard, FiSearch, FiTrash2, FiX, FiCheck, FiAlertCircle } from 'react-icons/fi';
import AlertModal from '@/components/AlertModal';

interface UserDetail {
    _id: string;
    firstName: string;
    lastName: string;
    email: string;
    phone: string;
    country: string;
    walletBalance: number;
    totalInvested: number;
    totalEarnings: number;
    isVerified: boolean;
    lastLoginIp?: string;
    lastLoginDevice?: string;
    lastLoginAt?: string;
    createdAt: string;
}

interface UserInvestment {
    _id: string;
    investmentId: string;
    planId: { name: string; roiPercentage: number };
    amount: number;
    expectedReturn: number;
    status: string;
    startDate: string;
    endDate: string;
}

export default function UserDetailsPage({ params }: { params: Promise<{ id: string }> }) {
    const { id } = use(params);
    const router = useRouter();

    const [user, setUser] = useState<UserDetail | null>(null);
    const [loading, setLoading] = useState(true);

    // Edit User States
    const [isEditing, setIsEditing] = useState(false);
    const [editForm, setEditForm] = useState<any>({});

    // Balance Adjust States
    const [showBalanceModal, setShowBalanceModal] = useState(false);
    const [balanceAction, setBalanceAction] = useState<'add' | 'subtract'>('add');
    const [balanceAmount, setBalanceAmount] = useState('');

    // Password Reset States
    const [showPasswordModal, setShowPasswordModal] = useState(false);
    const [newPassword, setNewPassword] = useState('');

    // Investment Table States
    const [investments, setInvestments] = useState<UserInvestment[]>([]);
    const [invLoading, setInvLoading] = useState(true);
    const [invFilter, setInvFilter] = useState('all');
    const [invSearch, setInvSearch] = useState('');
    const [invPage, setInvPage] = useState(1);

    // Investment Edit States
    const [editInvModalOpen, setEditInvModalOpen] = useState(false);
    const [selectedInv, setSelectedInv] = useState<UserInvestment | null>(null);
    const [newCapital, setNewCapital] = useState('');
    const [actionLoading, setActionLoading] = useState(false);

    const [alertState, setAlertState] = useState<{
        isOpen: boolean;
        title: string;
        message: string;
        type: 'success' | 'error' | 'info';
    }>({ isOpen: false, title: '', message: '', type: 'info' });

    // Fetch User Profile
    const fetchUserDetails = async () => {
        try {
            const res = await fetch(`/api/admin/users/${id}`);
            const data = await res.json();
            if (data.success) {
                setUser(data.user);
                setEditForm({
                    firstName: data.user.firstName,
                    lastName: data.user.lastName,
                    email: data.user.email,
                    phone: data.user.phone,
                    country: data.user.country,
                    isVerified: data.user.isVerified
                });
            } else {
                setAlertState({ isOpen: true, title: 'Error', message: 'User not found', type: 'error' });
            }
        } catch (error) {
            console.error('Error:', error);
        } finally {
            setLoading(false);
        }
    };

    // Fetch Investments
    const fetchInvestments = async () => {
        setInvLoading(true);
        try {
            const query = new URLSearchParams({
                userId: id,
                status: invFilter,
                search: invSearch,
                page: invPage.toString(),
                limit: '5'
            });
            const res = await fetch(`/api/admin/investments?${query.toString()}`);
            const data = await res.json();
            if (data.success) {
                setInvestments(data.investments);
            }
        } catch (error) {
            console.error(error);
        } finally {
            setInvLoading(false);
        }
    };

    useEffect(() => {
        fetchUserDetails();
    }, [id]);

    useEffect(() => {
        // Debounce fetch investments
        const timer = setTimeout(() => {
            fetchInvestments();
        }, 300);
        return () => clearTimeout(timer);
    }, [id, invFilter, invSearch, invPage]);

    // Handlers
    const handleSaveInfo = async () => {
        try {
            const res = await fetch(`/api/admin/users/${id}`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(editForm)
            });
            const data = await res.json();
            if (data.success) {
                setAlertState({ isOpen: true, title: 'Success', message: 'User updated.', type: 'success' });
                setUser(data.user);
                setIsEditing(false);
            } else {
                setAlertState({ isOpen: true, title: 'Error', message: data.error, type: 'error' });
            }
        } catch (error) {
            setAlertState({ isOpen: true, title: 'Error', message: 'Update failed', type: 'error' });
        }
    };

    const handleBalanceAdjust = async () => {
        const amount = Number(balanceAmount);
        if (!amount || amount <= 0) return;
        const adjustment = balanceAction === 'add' ? amount : -amount;

        try {
            const res = await fetch(`/api/admin/users/${id}`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ adjustBalance: adjustment })
            });
            const data = await res.json();
            if (data.success) {
                setAlertState({ isOpen: true, title: 'Success', message: 'Balance updated.', type: 'success' });
                setUser(data.user);
                setShowBalanceModal(false);
                setBalanceAmount('');
            } else {
                setAlertState({ isOpen: true, title: 'Error', message: data.error, type: 'error' });
            }
        } catch (error) {
            setAlertState({ isOpen: true, title: 'Error', message: 'Balance update failed', type: 'error' });
        }
    };

    const handlePasswordReset = async () => {
        if (!newPassword) return;
        try {
            const res = await fetch(`/api/admin/users/${id}`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ newPassword })
            });
            const data = await res.json();
            if (data.success) {
                setAlertState({ isOpen: true, title: 'Success', message: 'Password changed.', type: 'success' });
                setShowPasswordModal(false);
                setNewPassword('');
            } else {
                setAlertState({ isOpen: true, title: 'Error', message: data.error, type: 'error' });
            }
        } catch (error) {
            setAlertState({ isOpen: true, title: 'Error', message: 'Password reset failed', type: 'error' });
        }
    };

    // Investment Actions
    const handleCancelInv = async (invId: string) => {
        if (!confirm('Are you sure you want to cancel this investment? It will be deleted and refunded.')) return;
        try {
            const res = await fetch(`/api/admin/investments?id=${invId}`, { method: 'DELETE' });
            const data = await res.json();
            if (data.success) {
                setAlertState({ isOpen: true, title: 'Success', message: 'Investment cancelled.', type: 'success' });
                fetchInvestments();
                fetchUserDetails(); // Refresh balance
            } else {
                setAlertState({ isOpen: true, title: 'Error', message: data.error, type: 'error' });
            }
        } catch (error) {
            setAlertState({ isOpen: true, title: 'Error', message: 'Cancellation failed', type: 'error' });
        }
    };

    const handleEditInv = (inv: UserInvestment) => {
        setSelectedInv(inv);
        setNewCapital(inv.amount.toString());
        setEditInvModalOpen(true);
    };

    const saveInvCapital = async () => {
        if (!selectedInv) return;
        setActionLoading(true);
        try {
            const res = await fetch('/api/admin/investments', {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id: selectedInv._id, amount: newCapital })
            });
            const data = await res.json();
            if (data.success) {
                setAlertState({ isOpen: true, title: 'Success', message: 'Investment updated.', type: 'success' });
                setEditInvModalOpen(false);
                fetchInvestments();
                fetchUserDetails(); // Refresh balance
            } else {
                setAlertState({ isOpen: true, title: 'Error', message: data.error, type: 'error' });
            }
        } catch (error) {
            setAlertState({ isOpen: true, title: 'Error', message: 'Update failed', type: 'error' });
        } finally {
            setActionLoading(false);
        }
    };

    if (loading) return <AdminLayout><div className="flex h-screen items-center justify-center"><div className="animate-spin rounded-full h-12 w-12 border-t-2 border-accent-gold" /></div></AdminLayout>;
    if (!user) return <AdminLayout><div className="p-8 text-center text-white">User not found</div></AdminLayout>;

    return (
        <AdminLayout>
            <section className="py-8 px-4 sm:px-6 lg:px-8">
                {/* Header */}
                <div className="flex flex-col md:flex-row md:items-center space-y-4 md:space-y-0 md:space-x-4 mb-8">
                    <button onClick={() => router.back()} className="w-10 h-10 flex items-center justify-center bg-primary-900 rounded-lg hover:bg-primary-800 text-gray-300 hover:text-white transition-colors flex-shrink-0">
                        <FiArrowLeft className="w-5 h-5" />
                    </button>
                    <div>
                        <h1 className="text-2xl md:text-3xl font-bold font-serif text-white">User Management</h1>
                        <p className="text-gray-400 text-sm md:text-base">Manage user profile, investments, and security.</p>
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

                    {/* Left Column (2/3) */}
                    <div className="lg:col-span-2 space-y-8">

                        {/* Profile Card */}
                        <div className="card-premium">
                            <div className="flex flex-col md:flex-row justify-between items-start mb-6 gap-4">
                                <h3 className="text-xl font-bold text-white flex items-center">
                                    <FiUser className="mr-2 text-accent-gold" /> Personal Information
                                </h3>
                                {!isEditing ? (
                                    <button onClick={() => setIsEditing(true)} className="text-sm text-accent-gold hover:underline flex items-center">
                                        <FiEdit2 className="mr-1" /> Edit Info
                                    </button>
                                ) : (
                                    <div className="flex space-x-3 w-full md:w-auto">
                                        <button onClick={() => setIsEditing(false)} className="text-sm text-gray-400 hover:text-white flex-1 md:flex-none">Cancel</button>
                                        <button onClick={handleSaveInfo} className="text-sm text-emerald-400 hover:text-emerald-300 flex items-center font-bold flex-1 md:flex-none justify-center">
                                            <FiSave className="mr-1" /> Save
                                        </button>
                                    </div>
                                )}
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div><label className="text-xs text-gray-400 uppercase">First Name</label>{isEditing ? <input value={editForm.firstName} onChange={e => setEditForm({ ...editForm, firstName: e.target.value })} className="input-premium mt-1 py-1 w-full" /> : <p className="text-lg text-white font-medium break-words">{user.firstName}</p>}</div>
                                <div><label className="text-xs text-gray-400 uppercase">Last Name</label>{isEditing ? <input value={editForm.lastName} onChange={e => setEditForm({ ...editForm, lastName: e.target.value })} className="input-premium mt-1 py-1 w-full" /> : <p className="text-lg text-white font-medium break-words">{user.lastName}</p>}</div>
                                <div><label className="text-xs text-gray-400 uppercase">Email</label>{isEditing ? <input value={editForm.email} onChange={e => setEditForm({ ...editForm, email: e.target.value })} className="input-premium mt-1 py-1 w-full" /> : <p className="text-lg text-white font-medium break-all">{user.email}</p>}</div>
                                <div><label className="text-xs text-gray-400 uppercase">Phone</label>{isEditing ? <input value={editForm.phone} onChange={e => setEditForm({ ...editForm, phone: e.target.value })} className="input-premium mt-1 py-1 w-full" /> : <p className="text-lg text-white font-medium">{user.phone || 'N/A'}</p>}</div>
                                <div><label className="text-xs text-gray-400 uppercase">Country</label>{isEditing ? <input value={editForm.country} onChange={e => setEditForm({ ...editForm, country: e.target.value })} className="input-premium mt-1 py-1 w-full" /> : <p className="text-lg text-white font-medium">{user.country || 'N/A'}</p>}</div>
                                <div>
                                    <label className="text-xs text-gray-400 uppercase">Status</label>
                                    {isEditing ? (
                                        <div className="mt-1"><input type="checkbox" checked={editForm.isVerified} onChange={e => setEditForm({ ...editForm, isVerified: e.target.checked })} className="mr-2" /> <span className="text-white">Verified</span></div>
                                    ) : (
                                        <p className={`text-lg font-medium flex items-center ${user.isVerified ? 'text-green-400' : 'text-yellow-500'}`}><FiShield className="mr-2" />{user.isVerified ? 'Verified' : 'Unverified'}</p>
                                    )}
                                </div>
                            </div>
                            <div className="mt-6 border-t border-primary-800 pt-4">
                                <p className="text-sm text-gray-400 break-words"><FiClock className="inline mr-1" /> Last Login: <span className="text-white">{user.lastLoginAt ? new Date(user.lastLoginAt).toLocaleString() : 'Never'}</span> <span className="ml-2 text-xs text-gray-500 block md:inline mt-1 md:mt-0">IP: {user.lastLoginIp}</span></p>
                            </div>
                        </div>

                        {/* Investments Management */}
                        <div className="card-premium">
                            <div className="flex flex-col space-y-4 md:space-y-0 md:flex-row md:items-center justify-between gap-4 mb-6">
                                <h3 className="text-xl font-bold text-white flex items-center">
                                    <FiCreditCard className="mr-2 text-accent-gold" /> User Investments
                                </h3>
                                <div className="flex flex-wrap gap-2 bg-primary-900/50 p-1 rounded-lg">
                                    {['active', 'completed', 'all'].map(t => (
                                        <button key={t} onClick={() => setInvFilter(t)} className={`px-3 py-1 text-xs font-medium rounded whitespace-nowrap ${invFilter === t ? 'bg-accent-gold text-primary-950' : 'text-gray-400 hover:text-white'}`}>{t.charAt(0).toUpperCase() + t.slice(1)}</button>
                                    ))}
                                </div>
                            </div>

                            <div className="mb-4 relative">
                                <FiSearch className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                                <input type="text" placeholder="Search investment ID..." value={invSearch} onChange={e => setInvSearch(e.target.value)} className="input-premium pl-10 text-sm" />
                            </div>

                            <div className="overflow-x-auto">
                                <table className="w-full whitespace-nowrap">
                                    <thead className="text-xs uppercase text-gray-500 bg-primary-900/50">
                                        <tr>
                                            <th className="px-4 py-3 text-left">ID</th>
                                            <th className="px-4 py-3 text-left">Plan</th>
                                            <th className="px-4 py-3 text-left">Capital</th>
                                            <th className="px-4 py-3 text-left">Return</th>
                                            <th className="px-4 py-3 text-left">Status</th>
                                            <th className="px-4 py-3 text-right">Actions</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-primary-800 text-sm">
                                        {invLoading ? (
                                            <tr><td colSpan={6} className="px-4 py-8 text-center text-gray-400">Loading investments...</td></tr>
                                        ) : investments.length === 0 ? (
                                            <tr><td colSpan={6} className="px-4 py-8 text-center text-gray-400">No investments found.</td></tr>
                                        ) : (
                                            investments.map(inv => (
                                                <tr key={inv._id} className="hover:bg-primary-900/20">
                                                    <td className="px-4 py-3 font-mono text-gray-400">#{inv.investmentId}</td>
                                                    <td className="px-4 py-3 text-white">{inv.planId?.name} <span className="text-xs text-accent-gold">({inv.planId?.roiPercentage}%)</span></td>
                                                    <td className="px-4 py-3 font-mono text-white">${inv.amount.toLocaleString()}</td>
                                                    <td className="px-4 py-3 font-mono text-emerald-400">${(inv.expectedReturn || inv.amount).toLocaleString()}</td>
                                                    <td className="px-4 py-3"><span className={`px-2 py-0.5 rounded-full text-xs ${inv.status === 'active' ? 'bg-green-500/10 text-green-400' : inv.status === 'completed' ? 'bg-blue-500/10 text-blue-400' : 'bg-red-500/10 text-red-400'}`}>{inv.status}</span></td>
                                                    <td className="px-4 py-3 text-right">
                                                        {inv.status === 'active' && (
                                                            <div className="flex justify-end gap-2">
                                                                <button onClick={() => handleEditInv(inv)} className="p-1.5 hover:bg-white/5 rounded text-gray-400 hover:text-accent-gold"><FiEdit2 /></button>
                                                                <button onClick={() => handleCancelInv(inv._id)} className="p-1.5 hover:bg-red-500/10 rounded text-gray-400 hover:text-red-400"><FiTrash2 /></button>
                                                            </div>
                                                        )}
                                                    </td>
                                                </tr>
                                            ))
                                        )}
                                    </tbody>
                                </table>
                            </div>

                            {/* Pagination */}
                            <div className="mt-4 flex justify-between items-center text-xs text-gray-500">
                                <span>Showing {investments.length} items (Limit 5)</span>
                                <div className="flex gap-2">
                                    <button disabled={invPage <= 1} onClick={() => setInvPage(p => p - 1)} className="hover:text-white disabled:opacity-50">Previous</button>
                                    <button onClick={() => setInvPage(p => p + 1)} className="hover:text-white" disabled={investments.length < 5}>Next</button>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Right Column (1/3) */}
                    <div className="space-y-8">
                        <div className="card-premium bg-gradient-to-br from-primary-900 to-primary-950/80 border-accent-gold/20">
                            <h3 className="text-lg font-bold text-gray-300 mb-2">Wallet Balance</h3>
                            <div className="text-4xl font-mono font-bold text-white mb-6 break-words">${user.walletBalance.toLocaleString()}</div>
                            <div className="space-y-3">
                                <button onClick={() => { setBalanceAction('add'); setShowBalanceModal(true) }} className="w-full py-3 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-400 border border-emerald-500/20 rounded-xl font-bold flex justify-center items-center"><FiPlus className="mr-2" /> Add Funds</button>
                                <button onClick={() => { setBalanceAction('subtract'); setShowBalanceModal(true) }} className="w-full py-3 bg-red-500/10 hover:bg-red-500/20 text-red-400 border border-red-500/20 rounded-xl font-bold flex justify-center items-center"><FiMinus className="mr-2" /> Subtract Funds</button>
                            </div>
                        </div>
                        <div className="card-premium">
                            <h3 className="text-lg font-bold text-white mb-4">Security</h3>
                            <button onClick={() => setShowPasswordModal(true)} className="w-full py-3 bg-primary-800 hover:bg-primary-700 text-white rounded-xl flex justify-center items-center"><FiLock className="mr-2" /> Change Password</button>
                        </div>
                    </div>
                </div>

                {/* Modals */}
                {/* Balance Modal */}
                {showBalanceModal && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm px-4">
                        <div className="bg-background-dark border border-primary-700 rounded-2xl w-full max-w-sm p-6 animate-scale-in">
                            <h3 className="text-xl font-bold font-serif text-white mb-4">{balanceAction === 'add' ? 'Add Funds' : 'Subtract Funds'}</h3>
                            <input type="number" value={balanceAmount} onChange={e => setBalanceAmount(e.target.value)} className="input-premium text-lg font-mono mb-4 w-full" placeholder="0.00" autoFocus />
                            <div className="flex space-x-3"><button onClick={() => setShowBalanceModal(false)} className="btn-secondary flex-1">Cancel</button><button onClick={handleBalanceAdjust} className="btn-primary flex-1">Confirm</button></div>
                        </div>
                    </div>
                )}
                {/* Password Modal */}
                {showPasswordModal && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm px-4">
                        <div className="bg-background-dark border border-primary-700 rounded-2xl w-full max-w-sm p-6 animate-scale-in">
                            <h3 className="text-xl font-bold font-serif text-white mb-4">New Password</h3>
                            <input type="text" value={newPassword} onChange={e => setNewPassword(e.target.value)} className="input-premium mb-4 w-full" placeholder="Enter password" />
                            <div className="flex space-x-3"><button onClick={() => setShowPasswordModal(false)} className="btn-secondary flex-1">Cancel</button><button onClick={handlePasswordReset} className="btn-primary flex-1">Update</button></div>
                        </div>
                    </div>
                )}
                {/* Edit Investment Modal */}
                {editInvModalOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm px-4">
                        <div className="bg-background-dark border border-primary-700 rounded-2xl w-full max-w-md p-6 animate-scale-in">
                            <div className="flex justify-between mb-4"><h3 className="text-xl font-bold text-white">Edit Investment Amount</h3><button onClick={() => setEditInvModalOpen(false)}><FiX /></button></div>
                            <div className="bg-primary-900/30 p-3 rounded mb-4 border border-primary-800 text-xs text-gray-300"><FiAlertCircle className="inline mr-1 text-accent-gold" /> Modifying capital auto-adjusts user wallet.</div>
                            <input type="number" value={newCapital} onChange={e => setNewCapital(e.target.value)} className="input-premium text-lg font-mono mb-6 w-full" placeholder="0.00" />
                            <div className="flex space-x-3"><button onClick={() => setEditInvModalOpen(false)} className="btn-secondary flex-1">Cancel</button><button onClick={saveInvCapital} className="btn-primary flex-1" disabled={actionLoading}>{actionLoading ? 'Saving...' : 'Update'}</button></div>
                        </div>
                    </div>
                )}
                <AlertModal isOpen={alertState.isOpen} onClose={() => setAlertState(prev => ({ ...prev, isOpen: false }))} title={alertState.title} message={alertState.message} type={alertState.type} />
            </section>
        </AdminLayout>
    );
}

'use client';

import { useState, useEffect, useRef } from 'react';
import Navbar from '@/components/Navbar';
import DashboardFooter from '@/components/MobileFooter';
import { FiCopy, FiCheck, FiAlertCircle, FiCreditCard, FiInfo, FiUploadCloud, FiClock, FiCheckCircle, FiDollarSign, FiSearch, FiChevronLeft, FiChevronRight } from 'react-icons/fi';
import AlertModal from '@/components/AlertModal';

interface IWallet {
    _id: string;
    name: string;
    symbol: string;
    address: string;
    network?: string;
    logo?: string;
}

export default function DepositPage() {
    const [wallets, setWallets] = useState<IWallet[]>([]);
    const [selectedWallet, setSelectedWallet] = useState<IWallet | null>(null);
    const [loading, setLoading] = useState(true);
    const [copied, setCopied] = useState(false);

    // Deposit Flow State
    const [amount, setAmount] = useState('');
    const [proofFile, setProofFile] = useState<string | null>(null); // Base64
    const [depositStatus, setDepositStatus] = useState<'idle' | 'processing' | 'success'>('idle');
    const [alertState, setAlertState] = useState<{
        isOpen: boolean;
        title: string;
        message: string;
        type: 'success' | 'error' | 'info';
    }>({
        isOpen: false,
        title: '',
        message: '',
        type: 'info'
    });

    // Search & Pagination State
    const [searchTerm, setSearchTerm] = useState('');
    const [currentPage, setCurrentPage] = useState(1);
    const ITEMS_PER_PAGE = 5;

    // Refs for scrolling
    const methodRef = useRef<HTMLDivElement>(null);
    const detailsRef = useRef<HTMLDivElement>(null);

    // Redirect Timer State
    const [redirectTimer, setRedirectTimer] = useState(10);
    const timerRef = useRef<NodeJS.Timeout | null>(null);

    // Get user from local storage
    const [user, setUser] = useState<any>(null);

    const [minDeposit, setMinDeposit] = useState(100);

    useEffect(() => {
        if (depositStatus === 'success') {
            timerRef.current = setInterval(() => {
                setRedirectTimer((prev) => {
                    if (prev <= 1) {
                        if (timerRef.current) clearInterval(timerRef.current);
                        window.location.href = '/dashboard';
                        return 0;
                    }
                    return prev - 1;
                });
            }, 1000);
        }
        return () => {
            if (timerRef.current) clearInterval(timerRef.current);
        };
    }, [depositStatus]);

    useEffect(() => {
        const fetchInit = async () => {
            // Settings
            try {
                const sRes = await fetch('/api/settings');
                const sData = await sRes.json();
                if (sData.success) {
                    setMinDeposit(sData.settings.minDeposit || 100);
                }
            } catch (e) { console.error(e); }

            // User
            const userData = localStorage.getItem('user');
            if (userData) {
                setUser(JSON.parse(userData));
            }

            // Wallets
            try {
                const response = await fetch('/api/wallets');
                const data = await response.json();
                if (data.success) {
                    setWallets(data.wallets);
                }
            } catch (error) {
                console.error('Error fetching wallets:', error);
            } finally {
                setLoading(false);
            }
        };
        fetchInit();
    }, []);

    const handleSelectWallet = (wallet: IWallet) => {
        setSelectedWallet(wallet);
        setCopied(false);
        setTimeout(() => {
            detailsRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }, 100);
    };

    const copyToClipboard = () => {
        if (!selectedWallet) return;
        navigator.clipboard.writeText(selectedWallet.address);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            // Basic validation
            if (!file.type.startsWith('image/')) {
                setAlertState({ isOpen: true, title: 'Invalid File', message: 'Please upload a valid image file (JPEG, PNG).', type: 'error' });
                return;
            }

            const reader = new FileReader();
            reader.onload = (event) => {
                const img = new Image();
                img.onload = () => {
                    // Create canvas for compression
                    const canvas = document.createElement('canvas');
                    let width = img.width;
                    let height = img.height;

                    // Calculate new dimensions (Max width 1024px)
                    const MAX_WIDTH = 1024;
                    const MAX_HEIGHT = 1024;

                    if (width > height) {
                        if (width > MAX_WIDTH) {
                            height *= MAX_WIDTH / width;
                            width = MAX_WIDTH;
                        }
                    } else {
                        if (height > MAX_HEIGHT) {
                            width *= MAX_HEIGHT / height;
                            height = MAX_HEIGHT;
                        }
                    }

                    canvas.width = width;
                    canvas.height = height;

                    const ctx = canvas.getContext('2d');
                    ctx?.drawImage(img, 0, 0, width, height);

                    // Compress to JPEG with 0.7 quality matches "Premium" speed/quality balance
                    const compressedBase64 = canvas.toDataURL('image/jpeg', 0.7);
                    setProofFile(compressedBase64);
                };
                img.src = event.target?.result as string;
            };
            reader.readAsDataURL(file);
        }
    };

    const handleDepositSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!user) {
            setAlertState({ isOpen: true, title: 'Session Error', message: 'User session not found. Please refresh the page or log in again.', type: 'error' });
            return;
        }
        if (!amount || parseFloat(amount) < minDeposit) {
            setAlertState({ isOpen: true, title: 'Invalid Amount', message: `Please enter a deposit amount of at least $${minDeposit}.`, type: 'error' });
            return;
        }
        if (!selectedWallet) {
            setAlertState({ isOpen: true, title: 'Payment Method Required', message: 'Please select a payment method.', type: 'error' });
            return;
        }

        setDepositStatus('processing');

        // Simulate processing delay for animation
        await new Promise(resolve => setTimeout(resolve, 3000));

        try {
            const res = await fetch('/api/user/deposits', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    email: user.email,
                    user,
                    walletId: selectedWallet._id,
                    amount: parseFloat(amount),
                    proofImage: proofFile
                })
            });
            const data = await res.json();

            if (data.success) {
                setDepositStatus('success');
            } else {
                setAlertState({ isOpen: true, title: 'Deposit Failed', message: data.error || 'Failed to submit deposit', type: 'error' });
                setDepositStatus('idle');
            }
        } catch (error) {
            console.error('Deposit error:', error);
            setAlertState({ isOpen: true, title: 'Error', message: 'An unexpected error occurred. Please try again.', type: 'error' });
            setDepositStatus('idle');
        }
    };

    // Filter Logic
    const filteredWallets = wallets.filter(w =>
        w.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        w.symbol.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Pagination Logic
    const totalPages = Math.ceil(filteredWallets.length / ITEMS_PER_PAGE);
    const paginatedWallets = filteredWallets.slice(
        (currentPage - 1) * ITEMS_PER_PAGE,
        currentPage * ITEMS_PER_PAGE
    );

    // Reset pagination when search changes
    useEffect(() => {
        setCurrentPage(1);
    }, [searchTerm]);

    if (depositStatus === 'processing') {
        return (
            <main className="min-h-screen bg-background-dark flex flex-col items-center justify-center p-4">
                <div className="text-center space-y-6 animate-fade-in">
                    <div className="relative w-24 h-24 mx-auto">
                        <div className="absolute inset-0 border-4 border-primary-800 rounded-full"></div>
                        <div className="absolute inset-0 border-4 border-accent-gold rounded-full border-t-transparent animate-spin"></div>
                        <FiUploadCloud className="absolute inset-0 m-auto w-8 h-8 text-accent-gold animate-pulse" />
                    </div>
                    <div>
                        <h2 className="text-2xl font-bold text-white mb-2">Processing Deposit</h2>
                        <p className="text-gray-400">Verifying transaction details...</p>
                    </div>
                </div>
            </main>
        );
    }



    if (depositStatus === 'success') {
        return (
            <main className="min-h-screen bg-background-dark flex flex-col items-center justify-center p-4">
                <div className="card-premium max-w-md w-full text-center py-12 px-6 animate-fade-in space-y-6">
                    <div className="w-20 h-20 bg-green-500/10 rounded-full flex items-center justify-center mx-auto mb-4">
                        <FiCheckCircle className="w-10 h-10 text-green-500" />
                    </div>
                    <div>
                        <h2 className="text-3xl font-bold font-serif text-white mb-2">Deposit Submitted!</h2>
                        <p className="text-gray-400">
                            Your deposit of <span className="text-white font-bold">${parseFloat(amount).toLocaleString()}</span> is now pending review.
                        </p>
                    </div>
                    <div className="bg-primary-900/50 p-4 rounded-xl text-sm text-gray-400">
                        <p className="flex items-center justify-center space-x-2">
                            <FiClock className="w-4 h-4 text-accent-gold" />
                            <span>Usually approved within 5 minutes.</span>
                        </p>
                    </div>
                    <div className="text-center">
                        <p className="text-gray-400 text-sm mb-4">You will be redirected to dashboard in <span className="text-accent-gold font-bold">{redirectTimer}</span> seconds.</p>
                        <button
                            onClick={() => window.location.href = '/dashboard'}
                            className="btn-primary w-full"
                        >
                            Return to Dashboard
                        </button>
                    </div>
                </div>
            </main>
        );
    }

    return (
        <main className="min-h-screen bg-background-dark pb-24 md:pb-0">
            <Navbar isAuthenticated={true} user={user} />

            {/* Header */}
            <section className="pt-28 pb-8 bg-gradient-to-b from-primary-900/20 to-background-dark">
                <div className="section-container">
                    <div className="flex items-center space-x-3 mb-4">
                        <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-accent-gold to-accent-gold-dark flex items-center justify-center">
                            <FiCreditCard className="w-6 h-6 text-primary-950" />
                        </div>
                        <div>
                            <h1 className="text-3xl md:text-4xl font-bold font-serif text-white">
                                Deposit <span className="gradient-text">Funds</span>
                            </h1>
                            <p className="text-gray-400 text-sm">Follow the steps below to fund your wallet</p>
                        </div>
                    </div>
                </div>
            </section>

            {/* Main Content */}
            <section className="py-8">
                <div className="section-container space-y-8">

                    {/* Step 1: Amount */}
                    <div className="card-premium">
                        <label className="block text-lg font-bold text-white mb-4">1. Enter Deposit Amount <span className="text-sm font-normal text-gray-400 ml-2">(Min: ${minDeposit})</span></label>
                        <div className="relative max-w-xl">
                            <FiDollarSign className="absolute left-6 top-1/2 -translate-y-1/2 w-8 h-8 text-accent-gold" />
                            <input
                                type="number"
                                value={amount}
                                onChange={(e) => {
                                    setAmount(e.target.value);
                                }}
                                placeholder="0.00"
                                className="w-full bg-primary-900 border border-primary-700 rounded-2xl pl-16 pr-6 py-6 text-3xl font-bold text-white focus:outline-none focus:border-accent-gold focus:ring-1 focus:ring-accent-gold transition-all"
                                min={minDeposit}
                                step="0.01"
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                        {/* Left Column - Crypto Selection */}
                        <div ref={methodRef} className="lg:col-span-1 space-y-6">
                            <div className={`card-premium transition-opacity duration-300 ${!amount ? 'opacity-50 pointer-events-none' : 'opacity-100'}`}>
                                <h2 className="text-xl font-bold font-serif text-white mb-4">2. Select Payment Method</h2>

                                {/* Search Bar */}
                                <div className="relative mb-4">
                                    <FiSearch className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                                    <input
                                        type="text"
                                        placeholder="Search by name or symbol..."
                                        value={searchTerm}
                                        onChange={(e) => setSearchTerm(e.target.value)}
                                        className="w-full pl-10 pr-4 py-2.5 bg-primary-900/50 border border-primary-700/50 rounded-lg text-sm text-white focus:outline-none focus:border-accent-gold/50 placeholder-gray-500"
                                    />
                                </div>

                                {loading ? (
                                    <div className="flex justify-center py-8">
                                        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-accent-gold"></div>
                                    </div>
                                ) : filteredWallets.length > 0 ? (
                                    <div className="space-y-3">
                                        {/* List */}
                                        {paginatedWallets.map((wallet) => (
                                            <button
                                                key={wallet._id}
                                                onClick={() => handleSelectWallet(wallet)}
                                                className={`w-full flex items-center p-3 rounded-xl border transition-all duration-200 ${selectedWallet?._id === wallet._id
                                                    ? 'bg-primary-800 border-accent-gold shadow-lg shadow-accent-gold/10'
                                                    : 'bg-primary-900/30 border-primary-700/30 hover:bg-primary-800 hover:border-primary-600'
                                                    }`}
                                            >
                                                <div className="w-10 h-10 rounded-full bg-white flex items-center justify-center p-1 mr-3 flex-shrink-0">
                                                    {wallet.logo ? (
                                                        <img src={wallet.logo} alt={wallet.name} className="w-full h-full object-contain" />
                                                    ) : (
                                                        <span className="text-primary-900 font-bold">{wallet.symbol[0]}</span>
                                                    )}
                                                </div>
                                                <div className="text-left">
                                                    <p className={`font-bold ${selectedWallet?._id === wallet._id ? 'text-white' : 'text-gray-300'}`}>
                                                        {wallet.name}
                                                    </p>
                                                    <div className="flex items-center space-x-2">
                                                        <span className="text-xs font-mono text-accent-gold">{wallet.symbol}</span>
                                                        {wallet.network && (
                                                            <span className="text-[10px] bg-primary-700 text-gray-300 px-1.5 py-0.5 rounded">
                                                                {wallet.network}
                                                            </span>
                                                        )}
                                                    </div>
                                                </div>
                                                {selectedWallet?._id === wallet._id && (
                                                    <div className="ml-auto text-accent-emerald">
                                                        <FiCheck className="w-5 h-5" />
                                                    </div>
                                                )}
                                            </button>
                                        ))}

                                        {/* Pagination Controls */}
                                        {totalPages > 1 && (
                                            <div className="flex items-center justify-between pt-4 border-t border-primary-700/30">
                                                <button
                                                    onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                                                    disabled={currentPage === 1}
                                                    className="p-2 text-gray-400 hover:text-white disabled:opacity-30 disabled:hover:text-gray-400 transition-colors"
                                                >
                                                    <FiChevronLeft className="w-5 h-5" />
                                                </button>
                                                <span className="text-xs text-gray-500">
                                                    Page {currentPage} of {totalPages}
                                                </span>
                                                <button
                                                    onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                                                    disabled={currentPage === totalPages}
                                                    className="p-2 text-gray-400 hover:text-white disabled:opacity-30 disabled:hover:text-gray-400 transition-colors"
                                                >
                                                    <FiChevronRight className="w-5 h-5" />
                                                </button>
                                            </div>
                                        )}
                                    </div>
                                ) : (
                                    <div className="text-center py-8 text-gray-500">
                                        No payment methods found.
                                    </div>
                                )}
                            </div>

                            <div className="card-premium">
                                <div className="flex items-start space-x-3">
                                    <FiInfo className="w-5 h-5 text-accent-gold flex-shrink-0 mt-0.5" />
                                    <p className="text-sm text-gray-400">
                                        Deposits are automatically processed after network confirmation. This usually takes 10-30 minutes.
                                    </p>
                                </div>
                            </div>
                        </div>

                        {/* Right Column - Deposit Details */}
                        <div ref={detailsRef} className="lg:col-span-2">
                            <div className={`card-premium h-full transition-all duration-500 ${selectedWallet ? 'opacity-100 translate-y-0' : 'opacity-50 translate-y-4 grayscale blur-[1px]'}`}>
                                <h2 className="text-2xl font-bold font-serif text-white mb-6 flex items-center">
                                    3. Make Payment {selectedWallet && <span className="text-accent-gold ml-2">via {selectedWallet.name}</span>}
                                </h2>

                                {selectedWallet ? (
                                    <>
                                        {/* Important Instructions */}
                                        <div className="mb-8 p-4 bg-primary-900 border border-primary-700 rounded-xl">
                                            <h3 className="text-lg font-bold text-white mb-3 flex items-center">
                                                <FiAlertCircle className="mr-2 text-accent-gold" /> Important Instructions
                                            </h3>
                                            <div className="space-y-2 text-sm text-gray-400">
                                                <p>1. Send exactly <strong className="text-white">${parseFloat(amount).toLocaleString()} USD worth of {selectedWallet.symbol}</strong>.</p>
                                                <p>2. Send to the address below using the <strong className="text-white">{selectedWallet.network || selectedWallet.symbol}</strong> network.</p>
                                            </div>
                                        </div>

                                        <div className="bg-primary-900/50 rounded-2xl p-6 border border-primary-700/50 mb-8 text-center">
                                            <p className="text-sm text-gray-400 mb-4">Scan QR Code or Copy Address</p>

                                            <div className="w-48 h-48 mx-auto bg-white p-2 rounded-xl mb-6 flex items-center justify-center">
                                                <img
                                                    src={`https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${selectedWallet.address}`}
                                                    alt="Wallet QR Code"
                                                    className="w-full h-full"
                                                />
                                            </div>

                                            <div className="max-w-md mx-auto">
                                                <div className="flex items-center justify-between text-xs text-gray-400 mb-1 px-1">
                                                    <span>Wallet Address ({selectedWallet.network || selectedWallet.symbol})</span>
                                                    {copied && <span className="text-accent-emerald">Copied!</span>}
                                                </div>
                                                <div className="relative group">
                                                    <div className="w-full bg-primary-950 border border-primary-700 rounded-xl py-3 pl-4 pr-12 text-sm font-mono text-white break-all">
                                                        {selectedWallet.address}
                                                    </div>
                                                    <button
                                                        onClick={copyToClipboard}
                                                        className="absolute right-2 top-1/2 -translate-y-1/2 p-2 text-gray-400 hover:text-white bg-primary-800 hover:bg-primary-700 rounded-lg transition-colors"
                                                        title="Copy Address"
                                                    >
                                                        {copied ? <FiCheck className="w-4 h-4 text-accent-emerald" /> : <FiCopy className="w-4 h-4" />}
                                                    </button>
                                                </div>
                                            </div>
                                        </div>

                                        {/* Proof of Payment Form */}
                                        <div className="border-t border-primary-800 pt-8">
                                            <h3 className="text-xl font-bold text-white mb-4">Confirm Payment</h3>
                                            <form onSubmit={handleDepositSubmit} className="space-y-4">

                                                <div>
                                                    <label className="block text-sm text-gray-400 mb-1">Upload Payment Proof (Screenshot)</label>
                                                    <div className="relative group">
                                                        <input
                                                            type="file"
                                                            accept="image/*"
                                                            onChange={handleFileChange}
                                                            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                                                        />
                                                        <div className={`w-full bg-primary-900 border-2 border-dashed ${proofFile ? 'border-accent-emerald' : 'border-primary-700'} rounded-lg px-4 py-6 text-center transition-colors group-hover:border-accent-gold/50`}>
                                                            {proofFile ? (
                                                                <div className="flex items-center justify-center space-x-2 text-accent-emerald">
                                                                    <FiCheck className="w-5 h-5" />
                                                                    <span>Proof Attached</span>
                                                                </div>
                                                            ) : (
                                                                <div className="flex flex-col items-center justify-center text-gray-500">
                                                                    <FiUploadCloud className="w-8 h-8 mb-2" />
                                                                    <span>Click to upload screenshot</span>
                                                                </div>
                                                            )}
                                                        </div>
                                                    </div>
                                                </div>

                                                <button
                                                    type="submit"
                                                    className={`btn-primary w-full py-4 mt-4 font-bold text-lg shadow-lg shadow-accent-gold/20 ${(!amount || !selectedWallet) ? 'opacity-70 cursor-not-allowed' : ''}`}
                                                >
                                                    I Have Made The Payment
                                                </button>
                                            </form>
                                        </div>
                                    </>
                                ) : (
                                    <div className="h-64 flex flex-col items-center justify-center text-center">
                                        <div className="w-16 h-16 rounded-full bg-primary-800/50 flex items-center justify-center mb-4">
                                            <FiCreditCard className="w-8 h-8 text-gray-600" />
                                        </div>
                                        <p className="text-gray-400">
                                            Complete Step 1 & 2 to view payment details.
                                        </p>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </section>

            <AlertModal
                isOpen={alertState.isOpen}
                onClose={() => setAlertState(prev => ({ ...prev, isOpen: false }))}
                title={alertState.title}
                message={alertState.message}
                type={alertState.type}
            />
            <DashboardFooter />
            <div className="h-24 lg:h-40"></div>
        </main>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { FiCheck, FiX, FiShield, FiUpload, FiMapPin, FiUser, FiInfo } from 'react-icons/fi';

// Placeholder for user context/auth usage 
// In this project, user auth is likely stored in localStorage or Context.
// I'll grab user ID from localStorage as per typical patterns in this codebase or assume it's available.
// Actually, looking at `Sidebar` or `AdminSidebar`, it uses Props or `localStorage.getItem('user')`.
// I will use `localStorage` to get userId.

export default function KYCPage() {
    const router = useRouter();
    const [step, setStep] = useState(1);
    const [file, setFile] = useState<File | null>(null);
    const [previewUrl, setPreviewUrl] = useState<string | null>(null);
    const [formData, setFormData] = useState({
        fullName: '',
        country: '',
        address: ''
    });
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [viewState, setViewState] = useState<'loading' | 'form' | 'pending' | 'verified' | 'rejected'>('loading');
    const [rejectionMsg, setRejectionMsg] = useState('');

    useEffect(() => {
        const checkStatus = async () => {
            const userStr = localStorage.getItem('user');
            if (!userStr) { router.push('/login'); return; }
            const localUser = JSON.parse(userStr);

            try {
                const res = await fetch(`/api/user/profile?email=${localUser.email}`);
                const data = await res.json();
                if (data.success) {
                    const u = data.user;
                    if (u.isVerified) {
                        setViewState('verified');
                    } else if (u.kycStatus === 'pending') {
                        setViewState('pending');
                    } else if (u.kycStatus === 'rejected') {
                        setViewState('rejected');
                        setRejectionMsg(u.kycRejectionReason || 'Document rejected. Please try again.');
                    } else {
                        setViewState('form');
                    }
                } else {
                    setViewState('form');
                }
            } catch (e) {
                setViewState('form');
            }
        };
        checkStatus();
    }, []);

    // Convert file to Base64
    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const selectedFile = e.target.files[0];
            if (selectedFile.size > 5 * 1024 * 1024) { // 5MB limit
                setError('File size too large (max 5MB)');
                return;
            }
            setFile(selectedFile);
            setPreviewUrl(URL.createObjectURL(selectedFile));
            setError('');
        }
    };

    const convertToBase64 = (file: File): Promise<string> => {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onload = () => resolve(reader.result as string);
            reader.onerror = error => reject(error);
        });
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        try {
            const userStr = localStorage.getItem('user');
            if (!userStr) {
                setError('User not found. Please log in.');
                return;
            }
            const user = JSON.parse(userStr);

            if (!file) {
                setError('Please upload an ID document.');
                return;
            }

            const base64File = await convertToBase64(file);

            const res = await fetch('/api/user/kyc', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    userId: user.id || user._id, // Handle potential ID field names
                    ...formData,
                    idDocument: base64File
                })
            });

            const data = await res.json();
            if (data.success) {
                setViewState('pending');
                window.scrollTo(0, 0);
            } else {
                setError(data.error || 'Submission failed');
            }
        } catch (err) {
            setError('Something went wrong. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    if (viewState === 'loading') {
        return (
            <div className="min-h-screen bg-primary-950 flex items-center justify-center">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-accent-gold"></div>
            </div>
        );
    }

    if (viewState === 'verified') {
        return (
            <div className="min-h-screen bg-primary-950 p-6 flex items-center justify-center">
                <div className="card-premium max-w-md w-full text-center py-12">
                    <div className="w-20 h-20 bg-green-500/10 rounded-full flex items-center justify-center mx-auto mb-6">
                        <FiShield className="w-10 h-10 text-green-400" />
                    </div>
                    <h2 className="text-2xl font-bold text-white mb-2">Account Verified</h2>
                    <p className="text-gray-400 mb-8">Your identity has been verified. You now have full access to all features including withdrawals.</p>
                    <button onClick={() => router.push('/dashboard')} className="btn-primary w-full">Go to Dashboard</button>
                </div>
            </div>
        );
    }

    if (viewState === 'pending') {
        return (
            <div className="min-h-screen bg-primary-950 p-6 flex items-center justify-center">
                <div className="card-premium max-w-md w-full text-center py-12">
                    <div className="w-20 h-20 bg-yellow-500/10 rounded-full flex items-center justify-center mx-auto mb-6">
                        <FiInfo className="w-10 h-10 text-yellow-500" />
                    </div>
                    <h2 className="text-2xl font-bold text-white mb-2">Verification Pending</h2>
                    <p className="text-sm text-gray-400 mb-8">Your documents are currently under review. This process usually takes 24-48 hours. You will be notified/emailed once the review is complete.</p>
                    <button onClick={() => router.push('/dashboard')} className="btn-secondary w-full">Return to Dashboard</button>
                </div>
            </div>
        );
    }

    if (viewState === 'rejected') {
        return (
            <div className="min-h-screen bg-primary-950 p-6 flex items-center justify-center">
                <div className="card-premium max-w-md w-full text-center py-12">
                    <div className="w-20 h-20 bg-red-500/10 rounded-full flex items-center justify-center mx-auto mb-6">
                        <FiX className="w-10 h-10 text-red-500" />
                    </div>
                    <h2 className="text-2xl font-bold text-white mb-2">Verification Failed</h2>
                    <p className="text-gray-400 mb-4">Your KYC submission was rejected.</p>
                    {rejectionMsg && <div className="bg-red-500/20 text-red-300 p-3 rounded mb-6 text-sm">{rejectionMsg}</div>}

                    <button onClick={() => setViewState('form')} className="btn-primary w-full">Try Again</button>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-primary-950 py-12 px-4 sm:px-6 lg:px-8">
            <div className="max-w-2xl mx-auto">
                <div className="text-center mb-10">
                    <h1 className="text-3xl font-bold font-serif text-white mb-2">Identity Verification</h1>
                    <p className="text-gray-400">Complete KYC to unlock full account features including withdrawals.</p>
                </div>

                <div className="card-premium">
                    <div className="flex items-center justify-center mb-8">
                        <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold transition-all ${step >= 1 ? 'bg-accent-gold text-primary-950' : 'bg-primary-800 text-gray-500'}`}>1</div>
                        <div className={`h-1 w-20 mx-2 transition-all ${step >= 2 ? 'bg-accent-gold' : 'bg-primary-800'}`}></div>
                        <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold transition-all ${step >= 2 ? 'bg-accent-gold text-primary-950' : 'bg-primary-800 text-gray-500'}`}>2</div>
                    </div>

                    <form onSubmit={handleSubmit}>
                        {step === 1 && (
                            <div className="space-y-6 animate-fade-in">
                                <div>
                                    <label className="block text-sm font-medium text-gray-400 mb-2">Full Name</label>
                                    <div className="relative">
                                        <FiUser className="absolute left-3 top-3.5 text-gray-500" />
                                        <input
                                            type="text"
                                            required
                                            value={formData.fullName}
                                            onChange={e => setFormData({ ...formData, fullName: e.target.value })}
                                            className="input-premium pl-10 w-full"
                                            placeholder="Enter your legal name"
                                        />
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-400 mb-2">Country</label>
                                    <div className="relative">
                                        <FiMapPin className="absolute left-3 top-3.5 text-gray-500" />
                                        <input
                                            type="text"
                                            required
                                            value={formData.country}
                                            onChange={e => setFormData({ ...formData, country: e.target.value })}
                                            className="input-premium pl-10 w-full"
                                            placeholder="Your country of residence"
                                        />
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-400 mb-2">Address</label>
                                    <textarea
                                        required
                                        value={formData.address}
                                        onChange={e => setFormData({ ...formData, address: e.target.value })}
                                        className="input-premium w-full h-32 pt-3"
                                        placeholder="Full residential address"
                                    ></textarea>
                                </div>
                                <button type="button" onClick={() => {
                                    if (formData.fullName && formData.country && formData.address) setStep(2);
                                    else setError('Please fill all fields');
                                }} className="btn-primary w-full py-3 mt-4">Next Step</button>
                            </div>
                        )}

                        {step === 2 && (
                            <div className="space-y-6 animate-fade-in">
                                <div className="text-center p-6 border-2 border-dashed border-primary-700 rounded-xl hover:border-accent-gold transition-colors cursor-pointer group relative">
                                    <input
                                        type="file"
                                        accept="image/*"
                                        onChange={handleFileChange}
                                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                                    />
                                    <div className="space-y-4">
                                        {previewUrl ? (
                                            <img src={previewUrl} alt="Preview" className="max-h-64 mx-auto rounded-lg shadow-lg" />
                                        ) : (
                                            <>
                                                <div className="w-16 h-16 bg-primary-800 rounded-full flex items-center justify-center mx-auto group-hover:bg-primary-700 transition-colors">
                                                    <FiUpload className="w-8 h-8 text-accent-gold" />
                                                </div>
                                                <div>
                                                    <p className="text-white font-medium">Click to upload ID Document</p>
                                                    <p className="text-sm text-gray-500 mt-1">Passport, Driver's License, or National ID</p>
                                                    <p className="text-xs text-gray-600 mt-2">Max 5MB • JPG, PNG</p>
                                                </div>
                                            </>
                                        )}
                                    </div>
                                </div>

                                <div className="flex gap-4">
                                    <button type="button" onClick={() => setStep(1)} className="btn-secondary flex-1 py-3">Back</button>
                                    <button type="submit" disabled={loading || !file} className="btn-primary flex-1 py-3 disabled:opacity-50 disabled:cursor-not-allowed">
                                        {loading ? 'Submitting...' : 'Submit Verification'}
                                    </button>
                                </div>
                            </div>
                        )}

                        {error && (
                            <div className="mt-4 p-3 bg-red-500/10 border border-red-500/20 text-red-400 text-sm rounded-lg flex items-center">
                                <FiInfo className="mr-2" /> {error}
                            </div>
                        )}
                    </form>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import Navbar from '@/components/Navbar';
import DashboardFooter from '@/components/MobileFooter';
import Link from 'next/link';
import {
    FiTrendingUp,
    FiDollarSign,
    FiPieChart,
    FiClock,
    FiArrowUp,
    FiArrowDown,
    FiEye,
    FiEyeOff,
    FiRefreshCw,
    FiCalendar,
    FiCheckCircle,
    FiActivity
} from 'react-icons/fi';
import { LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';

export default function DashboardPage() {
    const [balanceVisible, setBalanceVisible] = useState(true);
    const [user, setUser] = useState<any>(null);
    const [loading, setLoading] = useState(true);
    const [recentTransactions, setRecentTransactions] = useState<any[]>([]);

    // Charts and Investments state
    const [activeInvestments, setActiveInvestments] = useState<any[]>([]);
    const [completedInvestments, setCompletedInvestments] = useState<any[]>([]);
    const [stats, setStats] = useState({
        totalInvested: 0,
        totalEarnings: 0
    });

    useEffect(() => {
        const fetchData = async () => {
            const userData = localStorage.getItem('user');
            if (!userData) {
                setLoading(false);
                return;
            }

            const parsedUser = JSON.parse(userData);
            setUser(parsedUser); // Initial load from cache

            try {
                // Fetch fresh profile (balance AND investments now)
                const profileRes = await fetch(`/api/user/profile?email=${parsedUser.email}`);
                const profileData = await profileRes.json();

                if (profileData.success) {
                    setUser(profileData.user);
                    setStats({
                        totalInvested: profileData.user.totalInvested || 0,
                        totalEarnings: profileData.user.totalEarnings || 0
                    });

                    // Set Investments Lists
                    setActiveInvestments(profileData.activeInvestments || []);
                    setCompletedInvestments(profileData.completedInvestments || []);

                    // Update localStorage to keep it fresh
                    localStorage.setItem('user', JSON.stringify(profileData.user));
                }

                // Fetch recent transactions
                const txRes = await fetch(`/api/user/transactions?email=${parsedUser.email}`);
                const txData = await txRes.json();

                if (txData.success) {
                    setRecentTransactions(txData.transactions.slice(0, 5)); // Limit to 5
                }

            } catch (error) {
                console.error('Dashboard fetch error:', error);
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, []);

    // Real user data
    const walletBalance = user?.walletBalance || 0;
    const totalInvested = stats.totalInvested;
    const totalEarnings = stats.totalEarnings;

    // Static Chart Data for now
    const earningsData: any[] = [];
    const portfolioData: any[] = [];

    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('en-US', {
            style: 'currency',
            currency: 'USD',
            minimumFractionDigits: 2,
        }).format(amount);
    };

    const formatDate = (dateString: string) => {
        if (!dateString) return 'N/A';
        const date = new Date(dateString);
        return isNaN(date.getTime()) ? 'N/A' : date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    };

    const categoryConfig: Record<string, { gradient: string; icon: string }> = {
        crypto: { gradient: 'from-orange-500 to-yellow-500', icon: '₿' },
        'real-estate': { gradient: 'from-blue-500 to-cyan-500', icon: '🏢' },
        agriculture: { gradient: 'from-green-500 to-emerald-500', icon: '🌾' },
        stocks: { gradient: 'from-purple-500 to-pink-500', icon: '📈' },
    };

    return (
        <main className="min-h-screen bg-background-dark">
            <Navbar isAuthenticated={true} user={user} />

            {/* Dashboard Header */}
            <section className="pt-28 pb-8 bg-gradient-to-b from-primary-900/20 to-background-dark">
                <div className="section-container">
                    <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-8">
                        <div>
                            <h1 className="text-4xl font-bold font-serif text-white mb-2">
                                Welcome back, <span className="gradient-text">{user?.firstName || 'Investor'}</span>
                            </h1>
                            <p className="text-gray-400">Here's your investment overview</p>
                        </div>
                    </div>

                    {/* Stats Cards */}
                    <div className="grid grid-cols-2 md:grid-cols-2 lg:grid-cols-4 gap-3 md:gap-6">
                        {/* Wallet Balance */}
                        <div className="card-premium p-4 md:p-6 shadow-lg shadow-black/20">
                            <div className="flex items-center justify-between mb-3 md:mb-4">
                                <div className="w-10 h-10 md:w-12 md:h-12 rounded-xl bg-gradient-to-br from-accent-gold to-accent-gold-dark flex items-center justify-center shadow-lg shadow-accent-gold/20">
                                    <FiDollarSign className="w-5 h-5 md:w-6 md:h-6 text-primary-950" />
                                </div>
                                <button onClick={() => setBalanceVisible(!balanceVisible)} className="text-gray-400 hover:text-accent-gold transition-colors p-1">
                                    {balanceVisible ? <FiEye className="w-4 h-4 md:w-5 md:h-5" /> : <FiEyeOff className="w-4 h-4 md:w-5 md:h-5" />}
                                </button>
                            </div>
                            <p className="text-xs md:text-sm text-gray-400 mb-1 md:mb-2 font-medium">Wallet Balance</p>
                            <p className="text-lg md:text-3xl font-bold text-white font-mono tracking-tight text-nowrap overflow-hidden text-ellipsis">
                                {balanceVisible ? formatCurrency(walletBalance) : '••••••'}
                            </p>
                            <div className="flex items-center space-x-1.5 md:space-x-2 mt-2 md:mt-3 text-[10px] md:text-sm text-gray-400">
                                <FiRefreshCw className="w-3 h-3 md:w-4 md:h-4" />
                                <span>Updated now</span>
                            </div>
                        </div>

                        {/* Total Invested */}
                        <div className="card-premium p-4 md:p-6 shadow-lg shadow-black/20">
                            <div className="w-10 h-10 md:w-12 md:h-12 rounded-xl bg-gradient-to-br from-blue-500 to-cyan-500 flex items-center justify-center mb-3 md:mb-4 shadow-lg shadow-blue-500/20">
                                <FiPieChart className="w-5 h-5 md:w-6 md:h-6 text-white" />
                            </div>
                            <p className="text-xs md:text-sm text-gray-400 mb-1 md:mb-2 font-medium">Total Invested</p>
                            <p className="text-lg md:text-3xl font-bold text-white font-mono tracking-tight text-nowrap overflow-hidden text-ellipsis">
                                {formatCurrency(totalInvested)}
                            </p>
                            <div className="flex items-center space-x-1.5 md:space-x-2 mt-2 md:mt-3 text-[10px] md:text-sm text-gray-400">
                                <FiActivity className="w-3 h-3 md:w-4 md:h-4" />
                                <span>{activeInvestments.length} active plans</span>
                            </div>
                        </div>

                        {/* Total Earnings */}
                        <div className="card-premium p-4 md:p-6 shadow-lg shadow-black/20">
                            <div className="w-10 h-10 md:w-12 md:h-12 rounded-xl bg-gradient-to-br from-green-500 to-emerald-500 flex items-center justify-center mb-3 md:mb-4 shadow-lg shadow-green-500/20">
                                <FiTrendingUp className="w-5 h-5 md:w-6 md:h-6 text-white" />
                            </div>
                            <p className="text-xs md:text-sm text-gray-400 mb-1 md:mb-2 font-medium">Total Earnings</p>
                            <p className="text-lg md:text-3xl font-bold text-white font-mono tracking-tight text-nowrap overflow-hidden text-ellipsis">
                                {formatCurrency(totalEarnings)}
                            </p>
                            <div className="flex items-center space-x-1.5 md:space-x-2 mt-2 md:mt-3 text-[10px] md:text-sm text-gray-400">
                                <FiCheckCircle className="w-3 h-3 md:w-4 md:h-4" />
                                <span>{completedInvestments.length} completed</span>
                            </div>
                        </div>

                        {/* Portfolio */}
                        <div className="card-premium p-4 md:p-6 shadow-lg shadow-black/20">
                            <div className="w-10 h-10 md:w-12 md:h-12 rounded-xl bg-gradient-to-br from-purple-500 to-pink-500 flex items-center justify-center mb-3 md:mb-4 shadow-lg shadow-purple-500/20">
                                <FiDollarSign className="w-5 h-5 md:w-6 md:h-6 text-white" />
                            </div>
                            <p className="text-xs md:text-sm text-gray-400 mb-1 md:mb-2 font-medium">Portfolio Value</p>
                            <p className="text-lg md:text-3xl font-bold text-white font-mono tracking-tight text-nowrap overflow-hidden text-ellipsis">
                                {formatCurrency(totalInvested + totalEarnings)}
                            </p>
                            <div className="flex items-center space-x-1.5 md:space-x-2 mt-2 md:mt-3 text-[10px] md:text-sm text-gray-400">
                                <FiCalendar className="w-3 h-3 md:w-4 md:h-4" />
                                <span>All time</span>
                            </div>
                        </div>
                    </div>
                </div>
            </section>

            {/* Main Dashboard Content */}
            <section className="py-8">
                <div className="section-container">
                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                        {/* Left Column */}
                        <div className="lg:col-span-2 space-y-8">
                            {/* Earnings Chart (Placeholder) */}
                            <div className="card-premium">
                                <h2 className="text-2xl font-bold font-serif text-white mb-6">Earnings Overview</h2>
                                {earningsData.length > 0 ? (
                                    <ResponsiveContainer width="100%" height={300}>
                                        <LineChart data={earningsData}>
                                            <CartesianGrid strokeDasharray="3 3" stroke="#334e68" />
                                            <XAxis dataKey="month" stroke="#9fb3c8" />
                                            <YAxis stroke="#9fb3c8" />
                                            <Tooltip contentStyle={{ backgroundColor: '#1f2937', border: '1px solid #334e68', borderRadius: '8px' }} labelStyle={{ color: '#953bad' }} />
                                            <Line type="monotone" dataKey="earnings" stroke="#953bad" strokeWidth={3} dot={{ fill: '#953bad', r: 5 }} />
                                        </LineChart>
                                    </ResponsiveContainer>
                                ) : (
                                    <div className="flex flex-col items-center justify-center py-12 bg-primary-900/30 rounded-xl border border-primary-700/30">
                                        <div className="w-16 h-16 rounded-full bg-primary-800 flex items-center justify-center mb-4">
                                            <FiTrendingUp className="w-8 h-8 text-gray-400" />
                                        </div>
                                        <p className="text-gray-400">No earnings data available yet</p>
                                    </div>
                                )}
                            </div>

                            {/* Active Investments */}
                            <div className="card-premium">
                                <div className="flex items-center justify-between mb-6">
                                    <h2 className="text-2xl font-bold font-serif text-white">Active Investments</h2>
                                    <Link href="/plans" className="text-accent-gold hover:text-accent-gold-light transition-colors text-sm font-medium">
                                        + New Investment
                                    </Link>
                                </div>

                                {activeInvestments.length > 0 ? (
                                    <div className="space-y-4">
                                        {activeInvestments.map((investment) => {
                                            const category = categoryConfig[investment.category || 'crypto'];
                                            return (
                                                <Link
                                                    href={`/dashboard/investments/${investment._id}`}
                                                    key={investment._id}
                                                    className="block p-4 bg-primary-900/30 rounded-xl border border-primary-700/30 hover:border-accent-gold/50 transition-all hover:bg-primary-900/50 group"
                                                >
                                                    <div className="flex items-start justify-between mb-4">
                                                        <div className="flex items-center space-x-3">
                                                            <div className={`w-12 h-12 rounded-lg bg-gradient-to-br ${category.gradient} flex items-center justify-center text-xl shadow-lg`}>
                                                                {category.icon}
                                                            </div>
                                                            <div>
                                                                <h3 className="text-lg font-bold text-white group-hover:text-accent-gold transition-colors">{investment.planName}</h3>
                                                                <p className="text-sm text-gray-400">{formatCurrency(investment.amount)} invested</p>
                                                            </div>
                                                        </div>
                                                        <div className="text-right">
                                                            <p className="text-lg font-bold text-accent-emerald font-mono">+{investment.roiPercentage}%</p>
                                                            <p className="text-xs text-gray-400">{investment.daysRemaining} days left</p>
                                                        </div>
                                                    </div>

                                                    <div className="mb-3">
                                                        <div className="flex justify-between text-sm text-gray-400 mb-2">
                                                            <span>Progress</span>
                                                            <span>{investment.progress}%</span>
                                                        </div>
                                                        <div className="progress-bar">
                                                            <div className="progress-fill" style={{ width: `${investment.progress}%` }} />
                                                        </div>
                                                    </div>

                                                    <div className="flex justify-between items-center">
                                                        <div>
                                                            <p className="text-xs text-gray-500">Current Return</p>
                                                            <p className="text-sm font-bold text-white font-mono">{formatCurrency(investment.currentReturn)}</p>
                                                        </div>
                                                        <div className="text-right">
                                                            <p className="text-xs text-gray-500">Expected Return</p>
                                                            <p className="text-sm font-bold text-accent-gold font-mono">{formatCurrency(investment.expectedReturn)}</p>
                                                        </div>
                                                    </div>
                                                </Link>
                                            );
                                        })}
                                    </div>
                                ) : (
                                    <div className="flex flex-col items-center justify-center py-12 bg-primary-900/30 rounded-xl border border-primary-700/30">
                                        <div className="w-16 h-16 rounded-full bg-primary-800 flex items-center justify-center mb-4">
                                            <FiActivity className="w-8 h-8 text-gray-400" />
                                        </div>
                                        <p className="text-gray-300 font-semibold mb-2">No active investments</p>
                                        <p className="text-gray-400 text-sm mb-6 text-center max-w-sm">
                                            Start your journey by choosing one of our premium investment plans.
                                        </p>
                                        <Link href="/plans" className="btn-primary">
                                            Browse Investment Plans
                                        </Link>
                                    </div>
                                )}
                            </div>

                            {/* Completed Investments (Brief View) */}
                            <div className="card-premium">
                                <h2 className="text-2xl font-bold font-serif text-white mb-6">Completed Investments</h2>
                                {completedInvestments.length > 0 ? (
                                    <div className="space-y-3">
                                        {completedInvestments.map((investment) => {
                                            const category = categoryConfig[investment.category || 'crypto'];
                                            return (
                                                <div key={investment._id} className="flex items-center justify-between p-4 bg-primary-900/20 rounded-lg border border-primary-700/20">
                                                    <div className="flex items-center space-x-3">
                                                        <div className={`w-10 h-10 rounded-lg bg-gradient-to-br ${category.gradient} flex items-center justify-center text-lg`}>
                                                            {category.icon}
                                                        </div>
                                                        <div>
                                                            <h3 className="font-bold text-white">{investment.planName}</h3>
                                                            <p className="text-sm text-gray-400">{formatDate(investment.completedAt || investment.endDate)}</p>
                                                        </div>
                                                    </div>
                                                    <div className="text-right">
                                                        <p className="text-lg font-bold text-accent-emerald font-mono">+{formatCurrency(investment.actualReturn)}</p>
                                                        <p className="text-xs text-gray-400">{investment.roiPercentage}% ROI</p>
                                                    </div>
                                                </div>
                                            );
                                        })}
                                    </div>
                                ) : (
                                    <div className="text-center py-8 text-gray-400 text-sm">
                                        No completed investments yet
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Right Column (Transactions, etc) -- kept same */}
                        <div className="space-y-8">
                            {/* Transactions Component Reuse */}
                            <div className="card-premium">
                                <h2 className="text-xl font-bold font-serif text-white mb-6">Recent Transactions</h2>
                                {recentTransactions.length > 0 ? (
                                    <div className="space-y-3">
                                        {recentTransactions.map((transaction, index) => (
                                            <div key={transaction._id || index} className="flex items-center justify-between py-3 border-b border-primary-700/30 last:border-0">
                                                <div className="flex items-center space-x-3">
                                                    <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${transaction.type === 'profit' || transaction.type === 'deposit' ? 'bg-accent-emerald/20' : 'bg-primary-800'}`}>
                                                        {transaction.amount > 0 ? (
                                                            <FiArrowUp className="w-4 h-4 text-accent-emerald" />
                                                        ) : (
                                                            <FiArrowDown className="w-4 h-4 text-gray-400" />
                                                        )}
                                                    </div>
                                                    <div>
                                                        <p className="text-sm font-medium text-white">{transaction.description}</p>
                                                        <p className="text-xs text-gray-500">{formatDate(transaction.createdAt || transaction.date)}</p>
                                                    </div>
                                                </div>
                                                <div className="text-right">
                                                    <p className={`text-sm font-bold font-mono ${transaction.amount > 0 ? 'text-accent-emerald' : 'text-white'}`}>
                                                        {transaction.amount > 0 ? '+' : ''}{formatCurrency(Math.abs(transaction.amount))}
                                                    </p>
                                                    {transaction.status === 'pending' && <span className="text-[10px] text-yellow-500 block">Pending</span>}
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <div className="text-center py-8 text-gray-400 text-sm">No recent transactions</div>
                                )}
                                <Link href="/dashboard/transactions" className="block text-center text-accent-gold hover:text-accent-gold-light transition-colors text-sm font-medium mt-4">
                                    View All Transactions
                                </Link>
                            </div>
                        </div>
                    </div>
                </div>
            </section>
            <DashboardFooter />
            <div className="h-24 lg:h-40"></div>
        </main>
    );
}

'use client';

import { useState, useEffect } from 'react';
import Navbar from '@/components/Navbar';
import DashboardFooter from '@/components/MobileFooter';
import { FiDollarSign, FiAlertCircle, FiCheckCircle, FiChevronDown, FiCreditCard, FiSearch, FiX } from 'react-icons/fi';

export default function WithdrawPage() {
    const [amount, setAmount] = useState('');
    const [walletAddress, setWalletAddress] = useState('');
    const [selectedCrypto, setSelectedCrypto] = useState('');

    // Auth & Data State
    const [user, setUser] = useState<any>(null);
    const [loading, setLoading] = useState(false);
    const [pageLoading, setPageLoading] = useState(true);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState(false);

    // Crypto Options (Top 20 + Variants)
    const cryptoOptions = [
        { id: 'btc', symbol: 'BTC', name: 'Bitcoin', network: 'Bitcoin' },
        { id: 'eth', symbol: 'ETH', name: 'Ethereum', network: 'ERC20' },
        { id: 'usdt_trc20', symbol: 'USDT', name: 'USDT (TRC20)', network: 'TRC20' },
        { id: 'usdt_erc20', symbol: 'USDT', name: 'USDT (ERC20)', network: 'ERC20' },
        { id: 'usdt_bep20', symbol: 'USDT', name: 'USDT (BEP20)', network: 'BEP20' },
        { id: 'bnb', symbol: 'BNB', name: 'BNB', network: 'BEP20' },
        { id: 'sol', symbol: 'SOL', name: 'Solana', network: 'Solana' },
        { id: 'xrp', symbol: 'XRP', name: 'XRP', network: 'Ripple' },
        { id: 'usdc', symbol: 'USDC', name: 'USDC', network: 'ERC20' },
        { id: 'ada', symbol: 'ADA', name: 'Cardano', network: 'Cardano' },
        { id: 'avax', symbol: 'AVAX', name: 'Avalanche', network: 'C-Chain' },
        { id: 'doge', symbol: 'DOGE', name: 'Dogecoin', network: 'Dogecoin' },
        { id: 'trx', symbol: 'TRX', name: 'TRON', network: 'TRC20' },
        { id: 'dot', symbol: 'DOT', name: 'Polkadot', network: 'Polkadot' },
        { id: 'link', symbol: 'LINK', name: 'Chainlink', network: 'ERC20' },
        { id: 'ton', symbol: 'TON', name: 'Toncoin', network: 'TON' },
        { id: 'matic', symbol: 'MATIC', name: 'Polygon', network: 'Polygon' },
        { id: 'shib', symbol: 'SHIB', name: 'Shiba Inu', network: 'ERC20' },
        { id: 'ltc', symbol: 'LTC', name: 'Litecoin', network: 'Litecoin' },
        { id: 'bch', symbol: 'BCH', name: 'Bitcoin Cash', network: 'Bitcoin Cash' },
        { id: 'uni', symbol: 'UNI', name: 'Uniswap', network: 'ERC20' },
        { id: 'near', symbol: 'NEAR', name: 'NEAR Protocol', network: 'NEAR' }
    ];

    const [isDropdownOpen, setIsDropdownOpen] = useState(false);
    const [currencySearch, setCurrencySearch] = useState('');

    const [minWithdrawal, setMinWithdrawal] = useState(50);

    useEffect(() => {
        const initData = async () => {
            // Fetch Settings
            try {
                const sInfo = await fetch('/api/settings');
                const sData = await sInfo.json();
                if (sData.success) {
                    setMinWithdrawal(sData.settings.minWithdrawal || 50);
                }
            } catch (e) {
                console.error("Settings fetch error", e);
            }

            // Fetch User
            const userData = localStorage.getItem('user');
            if (userData) {
                const parsed = JSON.parse(userData);
                try {
                    const res = await fetch(`/api/user/profile?email=${parsed.email}`);
                    const data = await res.json();
                    if (data.success) {
                        setUser(data.user);
                        localStorage.setItem('user', JSON.stringify(data.user));
                    } else {
                        setUser(parsed);
                    }
                } catch (e) {
                    setUser(parsed);
                }
            } else {
                window.location.href = '/login';
            }
            setPageLoading(false);
        };
        initData();
    }, []);

    const selectedOption = cryptoOptions.find(c => c.id === selectedCrypto);
    const filteredOptions = cryptoOptions.filter(opt =>
        opt.name.toLowerCase().includes(currencySearch.toLowerCase()) ||
        opt.symbol.toLowerCase().includes(currencySearch.toLowerCase())
    );

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setSuccess(false);

        // Validation
        const withdrawAmount = parseFloat(amount);
        if (isNaN(withdrawAmount) || withdrawAmount < minWithdrawal) {
            setError(`Minimum withdrawal is ${formatCurrency(minWithdrawal)}`);
            return;
        }

        if (user && withdrawAmount > user.walletBalance) {
            setError('Insufficient balance');
            return;
        }

        if (user && !user.isVerified) {
            setError('Account verification (KYC) required for withdrawals.');
            return;
        }

        if (!selectedCrypto) {
            setError('Please select a withdrawal method');
            return;
        }

        if (!walletAddress.trim()) {
            setError('Please enter your wallet address');
            return;
        }

        if (walletAddress.length < 10) {
            setError('Please enter a valid wallet address');
            return;
        }

        setLoading(true);

        const cryptoDetails = cryptoOptions.find(c => c.id === selectedCrypto);

        try {
            const response = await fetch('/api/user/withdrawals', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    email: user.email,
                    amount: withdrawAmount,
                    walletAddress: walletAddress.trim(),
                    cryptoSymbol: cryptoDetails?.symbol,
                    cryptoName: cryptoDetails?.name,
                    network: cryptoDetails?.network
                }),
            });

            const data = await response.json();

            if (data.success) {
                setSuccess(true);
                setAmount('');
                setWalletAddress('');
                setSelectedCrypto('');
                // Update local balance
                setUser({ ...user, walletBalance: data.newBalance });
                localStorage.setItem('user', JSON.stringify({ ...user, walletBalance: data.newBalance }));

                // Scroll to top to see success message
                window.scrollTo(0, 0);
            } else {
                setError(data.error || 'Failed to submit withdrawal request');
            }
        } catch (error) {
            setError('An error occurred. Please try again.');
            console.error('Withdrawal error:', error);
        } finally {
            setLoading(false);
        }
    };

    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('en-US', {
            style: 'currency',
            currency: 'USD',
            minimumFractionDigits: 2,
        }).format(amount);
    };

    if (pageLoading) {
        return (
            <div className="min-h-screen bg-background-dark flex items-center justify-center">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-accent-gold"></div>
            </div>
        );
    }

    return (
        <main className="min-h-screen bg-background-dark pb-24 md:pb-0">
            <Navbar isAuthenticated={true} user={user} />

            {/* Header */}
            <section className="pt-28 pb-8 bg-gradient-to-b from-primary-900/20 to-background-dark">
                <div className="section-container">
                    <div className="flex items-center space-x-3 mb-4">
                        <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-green-500 to-emerald-500 flex items-center justify-center">
                            <FiDollarSign className="w-6 h-6 text-white" />
                        </div>
                        <div>
                            <h1 className="text-3xl md:text-4xl font-bold font-serif text-white">
                                Withdraw <span className="gradient-text">Funds</span>
                            </h1>
                            <p className="text-gray-400 text-sm">Request a withdrawal from your wallet</p>
                        </div>
                    </div>

                    {/* KYC Warning - If Unverified or Pending */}
                    {user && !user.isVerified && (
                        <div className={`mb-6 p-4 border rounded-xl animate-scale-in ${user.kycStatus === 'pending' ? 'bg-yellow-500/10 border-yellow-500/30' : 'bg-red-500/10 border-red-500/30'}`}>
                            <div className="flex items-start">
                                {user.kycStatus === 'pending' ? (
                                    <FiAlertCircle className="text-yellow-500 mt-1 mr-3 flex-shrink-0" size={20} />
                                ) : (
                                    <FiAlertCircle className="text-red-400 mt-1 mr-3 flex-shrink-0" size={20} />
                                )}
                                <div>
                                    <h3 className={`font-bold mb-1 ${user.kycStatus === 'pending' ? 'text-yellow-500' : 'text-red-400'}`}>
                                        {user.kycStatus === 'pending' ? 'Verification Pending' : 'Account Verification Required'}
                                    </h3>
                                    <p className="text-sm text-gray-300 mb-3">
                                        {user.kycStatus === 'pending'
                                            ? 'Your Identity Verification (KYC) is currently under review. Withdrawals will be enabled once approved.'
                                            : 'Your account is currently unverified. To ensure security and compliance, you must complete your Identity Verification (KYC) before you can withdraw funds.'
                                        }
                                    </p>
                                    {user.kycStatus !== 'pending' && (
                                        <a href="/dashboard/kyc" className="inline-flex items-center px-4 py-2 bg-red-500/20 hover:bg-red-500/30 text-red-300 text-xs font-bold uppercase rounded-lg transition-colors">
                                            Complete KYC Verification
                                        </a>
                                    )}
                                </div>
                            </div>
                        </div>
                    )}

                    {/* Balance Card */}
                    <div className="card-premium mt-6">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-sm text-gray-400 mb-1">Available Balance</p>
                                <p className="text-2xl md:text-3xl font-bold text-white font-mono">
                                    {user ? formatCurrency(user.walletBalance) : '$0.00'}
                                </p>
                            </div>
                            <div className="w-12 h-12 rounded-xl bg-accent-gold/20 flex items-center justify-center">
                                <FiDollarSign className="w-6 h-6 text-accent-gold" />
                            </div>
                        </div>
                    </div>
                </div>
            </section>

            {/* Withdrawal Form */}
            <section className="py-8">
                <div className="section-container">
                    <div className="max-w-2xl mx-auto space-y-6">
                        {/* Success Message */}
                        {success && (
                            <div className="flex items-start space-x-3 p-4 bg-green-500/10 border border-green-500/30 rounded-lg animate-fade-in">
                                <FiCheckCircle className="w-5 h-5 text-green-400 flex-shrink-0 mt-0.5" />
                                <div>
                                    <p className="text-green-300 text-sm font-semibold mb-1">Withdrawal Request Submitted</p>
                                    <p className="text-green-200/80 text-xs">
                                        Your request has been processed. Funds have been deducted and status is Pending.
                                        You will be notified once the admin approves the transaction.
                                    </p>
                                </div>
                            </div>
                        )}

                        {/* Error Message */}
                        {error && (
                            <div className="flex items-start space-x-3 p-4 bg-red-500/10 border border-red-500/30 rounded-lg animate-fade-in">
                                <FiAlertCircle className="w-5 h-5 text-red-400 flex-shrink-0 mt-0.5" />
                                <div>
                                    <p className="text-red-300 text-sm font-semibold">{error}</p>
                                </div>
                            </div>
                        )}

                        {/* Withdrawal Form Card */}
                        <div className="card-premium">
                            <h2 className="text-2xl font-bold font-serif text-white mb-6">Withdrawal Request</h2>

                            <form onSubmit={handleSubmit} className="space-y-6">
                                {/* Amount Input */}
                                <div>
                                    <label className="block text-sm font-semibold text-gray-300 mb-2">
                                        Withdrawal Amount
                                    </label>
                                    <div className="relative">
                                        <span className="absolute left-4 top-3.5 text-gray-400 font-mono">$</span>
                                        <input
                                            type="number"
                                            step="0.01"
                                            min="0"
                                            max={user?.walletBalance || 0}
                                            value={amount}
                                            onChange={(e) => setAmount(e.target.value)}
                                            placeholder="0.00"
                                            className="w-full pl-8 pr-4 py-3 bg-primary-900/50 border border-primary-700/50 rounded-lg text-white font-mono focus:outline-none focus:border-accent-gold/50 transition-colors"
                                            required
                                        />
                                    </div>
                                    <div className="flex justify-between mt-2">
                                        <p className="text-xs text-gray-500">
                                            Min: {formatCurrency(minWithdrawal)}
                                        </p>
                                        <button
                                            type="button"
                                            onClick={() => setAmount(user?.walletBalance?.toString() || '0')}
                                            className="text-xs text-accent-gold hover:text-white transition-colors"
                                        >
                                            Max Amount
                                        </button>
                                    </div>
                                </div>

                                {/* Wallet Select Dropdown */}
                                <div className="relative">
                                    <label className="block text-sm font-semibold text-gray-300 mb-2">
                                        Select Withdrawal Method
                                    </label>

                                    {/* Custom Select Trigger */}
                                    <button
                                        type="button"
                                        onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                                        className="w-full flex items-center justify-between px-4 py-3 bg-primary-900/50 border border-primary-700/50 rounded-lg text-white focus:outline-none focus:border-accent-gold/50 transition-colors group hover:border-accent-gold/30"
                                    >
                                        <div className="flex items-center space-x-3">
                                            <FiCreditCard className="text-gray-400 group-hover:text-accent-gold transition-colors" />
                                            <span className={selectedOption ? 'text-white font-medium' : 'text-gray-400'}>
                                                {selectedOption ? `${selectedOption.name} (${selectedOption.symbol})` : 'Select Cryptocurrency'}
                                            </span>
                                        </div>
                                        <FiChevronDown className={`w-5 h-5 text-gray-400 transition-transform duration-300 ${isDropdownOpen ? 'rotate-180 text-accent-gold' : ''}`} />
                                    </button>

                                    {/* Dropdown Menu */}
                                    {isDropdownOpen && (
                                        <div className="absolute top-full left-0 right-0 mt-2 z-50 bg-background-dark-secondary border border-primary-700 rounded-lg shadow-xl max-h-80 flex flex-col animate-slide-down overflow-hidden backdrop-blur-3xl">
                                            {/* Search Bar */}
                                            <div className="p-3 border-b border-primary-700/50 sticky top-0 bg-background-dark-secondary/95 z-10 backdrop-blur-md">
                                                <div className="relative">
                                                    <FiSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                                                    <input
                                                        type="text"
                                                        placeholder="Search crypto..."
                                                        value={currencySearch}
                                                        onChange={(e) => setCurrencySearch(e.target.value)}
                                                        className="w-full bg-primary-900/50 border border-primary-700/50 rounded-md pl-9 pr-8 py-2 text-sm text-white focus:outline-none focus:border-accent-gold/50 placeholder-gray-500"
                                                        autoFocus
                                                    />
                                                    {currencySearch && (
                                                        <button
                                                            type="button"
                                                            onClick={() => setCurrencySearch('')}
                                                            className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-white"
                                                        >
                                                            <FiX className="w-3 h-3" />
                                                        </button>
                                                    )}
                                                </div>
                                            </div>

                                            {/* Options List */}
                                            <div className="overflow-y-auto flex-1 p-1 custom-scrollbar">
                                                {filteredOptions.length > 0 ? (
                                                    filteredOptions.map((opt) => (
                                                        <button
                                                            key={opt.id}
                                                            type="button"
                                                            onClick={() => {
                                                                setSelectedCrypto(opt.id);
                                                                setIsDropdownOpen(false);
                                                            }}
                                                            className={`w-full text-left px-3 py-3 rounded-md flex items-center justify-between transition-colors group ${selectedCrypto === opt.id ? 'bg-accent-gold/10 border border-accent-gold/20' : 'hover:bg-primary-800/50 border border-transparent'}`}
                                                        >
                                                            <div className="flex flex-col">
                                                                <span className="font-bold text-white text-sm group-hover:text-accent-gold transition-colors">{opt.name}</span>
                                                                <span className="text-xs text-gray-400">{opt.network}</span>
                                                            </div>
                                                            <div className="text-xs font-mono text-accent-gold bg-accent-gold/10 px-2 py-1 rounded border border-accent-gold/20">{opt.symbol}</div>
                                                        </button>
                                                    ))
                                                ) : (
                                                    <div className="p-6 text-center text-gray-500 text-sm italic">
                                                        No results for "{currencySearch}"
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    )}

                                    {/* Selected Network Info */}
                                    {selectedOption && (
                                        <div className="mt-3 flex items-start space-x-2 text-xs text-accent-emerald bg-accent-emerald/5 p-3 rounded-lg border border-accent-emerald/10 animate-fade-in">
                                            <FiCheckCircle className="w-4 h-4 mt-0.5 flex-shrink-0" />
                                            <p>
                                                Using Network: <span className="font-bold text-accent-emerald">{selectedOption.network}</span>.
                                                <br />Please ensure the destination address supports this network.
                                            </p>
                                        </div>
                                    )}
                                </div>


                                {/* Wallet Address Input */}
                                <div>
                                    <label className="block text-sm font-semibold text-gray-300 mb-2">
                                        Destination Wallet Address
                                    </label>
                                    <input
                                        type="text"
                                        value={walletAddress}
                                        onChange={(e) => setWalletAddress(e.target.value)}
                                        placeholder="Paste your wallet address here"
                                        className="w-full px-4 py-3 bg-primary-900/50 border border-primary-700/50 rounded-lg text-white font-mono text-sm focus:outline-none focus:border-accent-gold/50 transition-colors"
                                        required
                                    />
                                    <p className="text-xs text-amber-500/80 mt-2">
                                        Ensure the address matches the selected network ({selectedCrypto ? cryptoOptions.find(c => c.id === selectedCrypto)?.network : '...'}).
                                    </p>
                                </div>

                                {/* Submit Button */}
                                <button
                                    type="submit"
                                    disabled={loading}
                                    className="btn-primary w-full disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                    {loading ? 'Processing...' : 'Submit Withdrawal Request'}
                                </button>
                            </form>
                        </div>
                    </div>
                </div>
            </section>

            <DashboardFooter />
            <div className="h-24 lg:h-40"></div>
        </main>
    );
}

'use client';

import { useState } from 'react';
import Link from 'next/link';
import { useSiteSettings } from '@/context/SiteContext';
import { FiMail, FiLock, FiEye, FiEyeOff, FiCheckCircle, FiAlertCircle, FiArrowLeft } from 'react-icons/fi';
import { useRouter } from 'next/navigation';

export default function ForgotPasswordPage() {
    const { settings, loading: settingsLoading } = useSiteSettings();
    const router = useRouter();
    const [step, setStep] = useState<1 | 2>(1);

    // Form states
    const [email, setEmail] = useState('');
    const [otp, setOtp] = useState('');
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');

    // UI states
    const [showPassword, setShowPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');
    const [successMessage, setSuccessMessage] = useState('');

    const handleRequestOtp = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!settings.emailEnabled) {
            setError('Password reset is currently disabled. Please contact support.');
            return;
        }

        setIsLoading(true);
        setError('');
        setSuccessMessage('');

        try {
            const response = await fetch('/api/auth/forgot-password', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email }),
            });

            const data = await response.json();

            if (data.success) {
                setSuccessMessage(data.message);
                setStep(2);
            } else {
                setError(data.message || 'Failed to send OTP');
            }
        } catch (error) {
            setError('An error occurred. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };

    const handleResetPassword = async (e: React.FormEvent) => {
        e.preventDefault();

        if (password !== confirmPassword) {
            setError('Passwords do not match');
            return;
        }

        setIsLoading(true);
        setError('');
        setSuccessMessage('');

        try {
            const response = await fetch('/api/auth/reset-password', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email, otp, newPassword: password }),
            });

            const data = await response.json();

            if (data.success) {
                setSuccessMessage('Password reset successfully! Redirecting to login...');
                setTimeout(() => {
                    router.push('/login');
                }, 2000);
            } else {
                setError(data.message || 'Failed to reset password');
            }
        } catch (error) {
            setError('An error occurred. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <main className="min-h-screen flex items-center justify-center bg-gradient-to-br from-background-dark via-primary-950 to-background-dark relative overflow-hidden">
            {/* Background Elements */}
            <div className="absolute top-0 right-0 w-96 h-96 bg-accent-gold/10 rounded-full blur-3xl" />
            <div className="absolute bottom-0 left-0 w-96 h-96 bg-accent-emerald/10 rounded-full blur-3xl" />

            <div className="section-container relative z-10 py-12">
                <div className="max-w-md mx-auto">
                    {/* Logo */}
                    <Link href="/" className="flex items-center justify-center space-x-2 mb-8">
                        {settings.siteLogo ? (
                            <img src={settings.siteLogo} alt={settings.siteName} className="h-12 w-auto object-contain" />
                        ) : (
                            <div className="w-12 h-12 bg-gradient-to-br from-accent-gold to-accent-gold-dark rounded-xl flex items-center justify-center">
                                <span className="text-primary-950 font-bold text-2xl font-serif">{settings.siteName.charAt(0)}</span>
                            </div>
                        )}
                    </Link>

                    {/* Card */}
                    <div className="card-premium">
                        <div className="text-center mb-8">
                            <h1 className="text-3xl font-bold font-serif text-white mb-2">
                                {step === 1 ? 'Forgot Password' : 'Reset Password'}
                            </h1>
                            <p className="text-gray-400">
                                {step === 1
                                    ? 'Enter your email to receive a verification code'
                                    : 'Enter the code sent to your email and your new password'}
                            </p>
                        </div>

                        {/* Error Message */}
                        {error && (
                            <div className="mb-6 p-4 bg-red-500/10 border border-red-500/30 rounded-lg flex items-center space-x-3">
                                <FiAlertCircle className="w-5 h-5 text-red-400 flex-shrink-0" />
                                <p className="text-red-300 text-sm">{error}</p>
                            </div>
                        )}

                        {/* Success Message */}
                        {successMessage && (
                            <div className="mb-6 p-4 bg-green-500/10 border border-green-500/30 rounded-lg flex items-center space-x-3">
                                <FiCheckCircle className="w-5 h-5 text-green-400 flex-shrink-0" />
                                <p className="text-green-300 text-sm">{successMessage}</p>
                            </div>
                        )}

                        {/* Warning if Email Disabled */}
                        {!settingsLoading && !settings.emailEnabled && step === 1 && (
                            <div className="mb-6 p-4 bg-yellow-500/10 border border-yellow-500/30 rounded-lg flex items-center space-x-3">
                                <FiAlertCircle className="w-5 h-5 text-yellow-500 flex-shrink-0" />
                                <p className="text-yellow-200 text-sm">Password reset is currently unavailable. Please contact support.</p>
                            </div>
                        )}

                        {step === 1 ? (
                            <form onSubmit={handleRequestOtp} className="space-y-6">
                                <div>
                                    <label htmlFor="email" className="block text-sm font-medium text-gray-300 mb-2">
                                        Email Address
                                    </label>
                                    <div className="relative">
                                        <FiMail className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                        <input
                                            id="email"
                                            type="email"
                                            value={email}
                                            onChange={(e) => setEmail(e.target.value)}
                                            placeholder="you@example.com"
                                            className="input-premium pl-12"
                                            required
                                        />
                                    </div>
                                </div>
                                <button
                                    type="submit"
                                    disabled={isLoading || !settings.emailEnabled}
                                    className="btn-primary w-full text-lg disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                    {isLoading ? 'Sending OTP...' : 'Send OTP'}
                                </button>
                            </form>
                        ) : (
                            <form onSubmit={handleResetPassword} className="space-y-6">
                                {/* OTP */}
                                <div>
                                    <label htmlFor="otp" className="block text-sm font-medium text-gray-300 mb-2">
                                        Verification Code (OTP)
                                    </label>
                                    <input
                                        id="otp"
                                        type="text"
                                        value={otp}
                                        onChange={(e) => setOtp(e.target.value)}
                                        placeholder="Enter 6-digit code"
                                        className="input-premium text-center tracking-widest text-lg"
                                        required
                                        maxLength={6}
                                    />
                                </div>

                                {/* Password */}
                                <div>
                                    <label htmlFor="password" className="block text-sm font-medium text-gray-300 mb-2">
                                        New Password
                                    </label>
                                    <div className="relative">
                                        <FiLock className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                        <input
                                            id="password"
                                            type={showPassword ? 'text' : 'password'}
                                            value={password}
                                            onChange={(e) => setPassword(e.target.value)}
                                            placeholder="••••••••"
                                            className="input-premium pl-12 pr-12"
                                            required
                                            minLength={6}
                                        />
                                        <button
                                            type="button"
                                            onClick={() => setShowPassword(!showPassword)}
                                            className="absolute right-4 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-accent-gold transition-colors"
                                        >
                                            {showPassword ? <FiEyeOff className="w-5 h-5" /> : <FiEye className="w-5 h-5" />}
                                        </button>
                                    </div>
                                </div>

                                {/* Confirm Password */}
                                <div>
                                    <label htmlFor="confirmPassword" className="block text-sm font-medium text-gray-300 mb-2">
                                        Confirm New Password
                                    </label>
                                    <div className="relative">
                                        <FiLock className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                        <input
                                            id="confirmPassword"
                                            type={showConfirmPassword ? 'text' : 'password'}
                                            value={confirmPassword}
                                            onChange={(e) => setConfirmPassword(e.target.value)}
                                            placeholder="••••••••"
                                            className="input-premium pl-12 pr-12"
                                            required
                                            minLength={6}
                                        />
                                        <button
                                            type="button"
                                            onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                                            className="absolute right-4 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-accent-gold transition-colors"
                                        >
                                            {showConfirmPassword ? <FiEyeOff className="w-5 h-5" /> : <FiEye className="w-5 h-5" />}
                                        </button>
                                    </div>
                                </div>

                                <button
                                    type="submit"
                                    disabled={isLoading}
                                    className="btn-primary w-full text-lg disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                    {isLoading ? 'Resetting Password...' : 'Reset Password'}
                                </button>

                                <div className="text-center mt-4">
                                    <button
                                        type="button"
                                        onClick={() => setStep(1)}
                                        className="text-sm text-gray-400 hover:text-accent-gold transition-colors"
                                    >
                                        Change Email / Resend Code
                                    </button>
                                </div>
                            </form>
                        )}
                    </div>

                    {/* Back to Login */}
                    <div className="text-center mt-6">
                        <Link href="/login" className="text-gray-400 hover:text-accent-gold transition-colors text-sm flex items-center justify-center space-x-2">
                            <FiArrowLeft className="w-4 h-4" />
                            <span>Back to Login</span>
                        </Link>
                    </div>
                </div>
            </div>
        </main>
    );
}

'use client';

import { useState } from 'react';
import Link from 'next/link';
import { useSiteSettings } from '@/context/SiteContext';
import { FiMail, FiLock, FiEye, FiEyeOff, FiShield, FiAlertCircle } from 'react-icons/fi';

export default function LoginPage() {
    const { settings } = useSiteSettings();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);
        setError('');

        try {
            const response = await fetch('/api/auth/login', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ email, password }),
            });

            const data = await response.json();

            if (data.success) {
                // Store user data in localStorage (in production, use secure session/JWT)
                localStorage.setItem('user', JSON.stringify(data.user));

                // Redirect based on user role
                window.location.href = data.redirectTo;
            } else {
                setError(data.message || 'Login failed');
            }
        } catch (error) {
            console.error('Login error:', error);
            setError('An error occurred. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <main className="min-h-screen flex items-center justify-center bg-gradient-to-br from-background-dark via-primary-950 to-background-dark relative overflow-hidden">
            {/* Background Elements */}
            <div className="absolute top-0 right-0 w-96 h-96 bg-accent-gold/10 rounded-full blur-3xl" />
            <div className="absolute bottom-0 left-0 w-96 h-96 bg-accent-emerald/10 rounded-full blur-3xl" />

            <div className="section-container relative z-10 py-12">
                <div className="max-w-md mx-auto">
                    {/* Logo */}
                    <Link href="/" className="flex items-center justify-center space-x-2 mb-8">
                        {settings.siteLogo ? (
                            <img src={settings.siteLogo} alt={settings.siteName} className="h-12 w-auto object-contain" />
                        ) : (
                            <div className="w-12 h-12 bg-gradient-to-br from-accent-gold to-accent-gold-dark rounded-xl flex items-center justify-center">
                                <span className="text-primary-950 font-bold text-2xl font-serif">{settings.siteName.charAt(0)}</span>
                            </div>
                        )}
                        <span className="text-2xl font-serif font-bold gradient-text">
                            {settings.siteName}
                        </span>
                    </Link>

                    {/* Login Card */}
                    <div className="card-premium">
                        <div className="text-center mb-8">
                            <h1 className="text-3xl font-bold font-serif text-white mb-2">Welcome Back</h1>
                            <p className="text-gray-400">Sign in to access your investment portfolio</p>
                        </div>

                        {/* Error Message */}
                        {error && (
                            <div className="mb-6 p-4 bg-red-500/10 border border-red-500/30 rounded-lg flex items-center space-x-3">
                                <FiAlertCircle className="w-5 h-5 text-red-400 flex-shrink-0" />
                                <p className="text-red-300 text-sm">{error}</p>
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-6">
                            {/* Email */}
                            <div>
                                <label htmlFor="email" className="block text-sm font-medium text-gray-300 mb-2">
                                    Email Address
                                </label>
                                <div className="relative">
                                    <FiMail className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                    <input
                                        id="email"
                                        type="email"
                                        value={email}
                                        onChange={(e) => setEmail(e.target.value)}
                                        placeholder="you@example.com"
                                        className="input-premium pl-12"
                                        required
                                    />
                                </div>
                            </div>

                            {/* Password */}
                            <div>
                                <label htmlFor="password" className="block text-sm font-medium text-gray-300 mb-2">
                                    Password
                                </label>
                                <div className="relative">
                                    <FiLock className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                    <input
                                        id="password"
                                        type={showPassword ? 'text' : 'password'}
                                        value={password}
                                        onChange={(e) => setPassword(e.target.value)}
                                        placeholder="••••••••"
                                        className="input-premium pl-12 pr-12"
                                        required
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setShowPassword(!showPassword)}
                                        className="absolute right-4 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-accent-gold transition-colors"
                                    >
                                        {showPassword ? <FiEyeOff className="w-5 h-5" /> : <FiEye className="w-5 h-5" />}
                                    </button>
                                </div>
                            </div>

                            {/* Forgot Password */}
                            <div className="flex items-center justify-between">
                                <label className="flex items-center space-x-2 cursor-pointer">
                                    <input type="checkbox" className="w-4 h-4 rounded border-primary-700 bg-primary-800 text-accent-gold focus:ring-accent-gold/50" />
                                    <span className="text-sm text-gray-400">Remember me</span>
                                </label>
                                <Link href="/forgot-password" className="text-sm text-accent-gold hover:text-accent-gold-light transition-colors">
                                    Forgot password?
                                </Link>
                            </div>

                            {/* Submit Button */}
                            <button
                                type="submit"
                                disabled={isLoading}
                                className="btn-primary w-full text-lg disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                {isLoading ? 'Signing in...' : 'Sign In'}
                            </button>
                        </form>

                        {/* Divider */}
                        <div className="relative my-8">
                            <div className="divider" />
                            <span className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 bg-background-dark-secondary px-4 text-sm text-gray-400">
                                or
                            </span>
                        </div>

                        {/* Sign Up Link */}
                        <p className="text-center text-gray-400">
                            Don't have an account?{' '}
                            <Link href="/register" className="text-accent-gold hover:text-accent-gold-light font-semibold transition-colors">
                                Create Account
                            </Link>
                        </p>

                        {/* Trust Indicators */}
                        <div className="mt-8 pt-6 border-t border-primary-700/30">
                            <div className="flex items-center justify-center space-x-2 text-sm text-gray-400">
                                <FiShield className="w-4 h-4 text-accent-emerald" />
                                <span>Secure login with 256-bit encryption</span>
                            </div>
                        </div>
                    </div>

                    {/* Back to Home */}
                    <div className="text-center mt-6">
                        <Link href="/" className="text-gray-400 hover:text-accent-gold transition-colors text-sm">
                            ← Back to Home
                        </Link>
                    </div>
                </div>
            </div>
        </main>
    );
}

'use client';

import { useState } from 'react';
import Link from 'next/link';
import { useSiteSettings } from '@/context/SiteContext';
import { FiMail, FiLock, FiEye, FiEyeOff, FiUser, FiPhone, FiShield, FiCheckCircle, FiGlobe } from 'react-icons/fi';
import { countries } from '@/lib/countries';

export default function RegisterPage() {
    const { settings } = useSiteSettings();
    const [formData, setFormData] = useState({
        firstName: '',
        lastName: '',
        email: '',
        country: '',
        phoneCode: '',
        phone: '',
        password: '',
        confirmPassword: '',
    });
    const [showPassword, setShowPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);
    const [agreedToTerms, setAgreedToTerms] = useState(false);
    const [isLoading, setIsLoading] = useState(false);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleCountryChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        const selectedCountry = countries.find(c => c.name === e.target.value);
        setFormData({
            ...formData,
            country: e.target.value,
            phoneCode: selectedCountry?.phoneCode || ''
        });
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (formData.password !== formData.confirmPassword) {
            alert('Passwords do not match');
            return;
        }

        if (!agreedToTerms) {
            alert('Please agree to the terms and conditions');
            return;
        }

        setIsLoading(true);

        try {
            const response = await fetch('/api/auth/register', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    firstName: formData.firstName,
                    lastName: formData.lastName,
                    email: formData.email,
                    phone: `${formData.phoneCode}${formData.phone}`,
                    country: formData.country,
                    password: formData.password
                })
            });

            const data = await response.json();

            if (data.success) {
                // Save session
                localStorage.setItem('user', JSON.stringify(data.user));
                window.location.href = '/dashboard';
            } else {
                alert(data.message || 'Registration failed');
            }
        } catch (error) {
            console.error('Registration error:', error);
            alert('Registration failed. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };

    const passwordStrength = (password: string) => {
        if (password.length === 0) return { strength: 0, label: '' };
        if (password.length < 6) return { strength: 25, label: 'Weak', color: 'bg-red-500' };
        if (password.length < 10) return { strength: 50, label: 'Fair', color: 'bg-yellow-500' };
        if (password.length < 14) return { strength: 75, label: 'Good', color: 'bg-blue-500' };
        return { strength: 100, label: 'Strong', color: 'bg-accent-emerald' };
    };

    const strength = passwordStrength(formData.password);

    return (
        <main className="min-h-screen flex items-center justify-center bg-gradient-to-br from-background-dark via-primary-950 to-background-dark relative overflow-hidden py-12">
            {/* Background Elements */}
            <div className="absolute top-0 right-0 w-96 h-96 bg-accent-gold/10 rounded-full blur-3xl" />
            <div className="absolute bottom-0 left-0 w-96 h-96 bg-accent-emerald/10 rounded-full blur-3xl" />

            <div className="section-container relative z-10">
                <div className="max-w-2xl mx-auto">
                    {/* Logo */}
                    <Link href="/" className="flex items-center justify-center space-x-2 mb-8">
                        {settings.siteLogo ? (
                            <img src={settings.siteLogo} alt={settings.siteName} className="h-12 w-auto object-contain" />
                        ) : (
                            <div className="w-12 h-12 bg-gradient-to-br from-accent-gold to-accent-gold-dark rounded-xl flex items-center justify-center">
                                <span className="text-primary-950 font-bold text-2xl font-serif">{settings.siteName.charAt(0)}</span>
                            </div>
                        )}
                        <span className="text-2xl font-serif font-bold gradient-text">
                            {settings.siteName}
                        </span>
                    </Link>

                    {/* Register Card */}
                    <div className="card-premium">
                        <div className="text-center mb-8">
                            <h1 className="text-3xl font-bold font-serif text-white mb-2">Create Your Account</h1>
                            <p className="text-gray-400">Start your investment journey today</p>
                        </div>

                        <form onSubmit={handleSubmit} className="space-y-6">
                            {/* Name Fields */}
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label htmlFor="firstName" className="block text-sm font-medium text-gray-300 mb-2">
                                        First Name
                                    </label>
                                    <div className="relative">
                                        <FiUser className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                        <input
                                            id="firstName"
                                            name="firstName"
                                            type="text"
                                            value={formData.firstName}
                                            onChange={handleChange}
                                            placeholder="John"
                                            className="input-premium pl-12"
                                            required
                                        />
                                    </div>
                                </div>
                                <div>
                                    <label htmlFor="lastName" className="block text-sm font-medium text-gray-300 mb-2">
                                        Last Name
                                    </label>
                                    <div className="relative">
                                        <FiUser className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                        <input
                                            id="lastName"
                                            name="lastName"
                                            type="text"
                                            value={formData.lastName}
                                            onChange={handleChange}
                                            placeholder="Doe"
                                            className="input-premium pl-12"
                                            required
                                        />
                                    </div>
                                </div>
                            </div>

                            {/* Email */}
                            <div>
                                <label htmlFor="email" className="block text-sm font-medium text-gray-300 mb-2">
                                    Email Address
                                </label>
                                <div className="relative">
                                    <FiMail className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                    <input
                                        id="email"
                                        name="email"
                                        type="email"
                                        value={formData.email}
                                        onChange={handleChange}
                                        placeholder="you@example.com"
                                        className="input-premium pl-12"
                                        required
                                    />
                                </div>
                            </div>

                            {/* Country */}
                            <div>
                                <label htmlFor="country" className="block text-sm font-medium text-gray-300 mb-2">
                                    Country *
                                </label>
                                <div className="relative">
                                    <FiGlobe className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                    <select
                                        id="country"
                                        name="country"
                                        value={formData.country}
                                        onChange={handleCountryChange}
                                        className="input-premium pl-12 appearance-none cursor-pointer"
                                        required
                                    >
                                        <option value="">Select your country</option>
                                        {countries.map((country) => (
                                            <option key={country.code} value={country.name}>
                                                {country.name} ({country.phoneCode})
                                            </option>
                                        ))}
                                    </select>
                                </div>
                            </div>

                            {/* Phone */}
                            <div>
                                <label htmlFor="phone" className="block text-sm font-medium text-gray-300 mb-2">
                                    Phone Number <span className="text-gray-500">(Optional)</span>
                                </label>
                                <div className="flex space-x-2">
                                    <div className="relative w-32">
                                        <input
                                            type="text"
                                            value={formData.phoneCode}
                                            readOnly
                                            placeholder="Code"
                                            className="input-premium text-center bg-primary-800/50 cursor-not-allowed"
                                        />
                                    </div>
                                    <div className="relative flex-1">
                                        <FiPhone className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                        <input
                                            id="phone"
                                            name="phone"
                                            type="tel"
                                            value={formData.phone}
                                            onChange={handleChange}
                                            placeholder="123-4567"
                                            className="input-premium pl-12"
                                            disabled={!formData.country}
                                        />
                                    </div>
                                </div>
                                {!formData.country && (
                                    <p className="mt-1 text-xs text-gray-500">Please select a country first</p>
                                )}
                            </div>

                            {/* Password */}
                            <div>
                                <label htmlFor="password" className="block text-sm font-medium text-gray-300 mb-2">
                                    Password
                                </label>
                                <div className="relative">
                                    <FiLock className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                    <input
                                        id="password"
                                        name="password"
                                        type={showPassword ? 'text' : 'password'}
                                        value={formData.password}
                                        onChange={handleChange}
                                        placeholder="••••••••"
                                        className="input-premium pl-12 pr-12"
                                        required
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setShowPassword(!showPassword)}
                                        className="absolute right-4 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-accent-gold transition-colors"
                                    >
                                        {showPassword ? <FiEyeOff className="w-5 h-5" /> : <FiEye className="w-5 h-5" />}
                                    </button>
                                </div>
                                {formData.password && (
                                    <div className="mt-2">
                                        <div className="flex items-center justify-between mb-1">
                                            <span className="text-xs text-gray-400">Password strength</span>
                                            <span className={`text-xs font-semibold ${strength.strength >= 75 ? 'text-accent-emerald' : strength.strength >= 50 ? 'text-yellow-400' : 'text-red-400'}`}>
                                                {strength.label}
                                            </span>
                                        </div>
                                        <div className="progress-bar h-1">
                                            <div className={`h-full rounded-full transition-all duration-300 ${strength.color}`} style={{ width: `${strength.strength}%` }} />
                                        </div>
                                    </div>
                                )}
                            </div>

                            {/* Confirm Password */}
                            <div>
                                <label htmlFor="confirmPassword" className="block text-sm font-medium text-gray-300 mb-2">
                                    Confirm Password
                                </label>
                                <div className="relative">
                                    <FiLock className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                    <input
                                        id="confirmPassword"
                                        name="confirmPassword"
                                        type={showConfirmPassword ? 'text' : 'password'}
                                        value={formData.confirmPassword}
                                        onChange={handleChange}
                                        placeholder="••••••••"
                                        className="input-premium pl-12 pr-12"
                                        required
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                                        className="absolute right-4 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-accent-gold transition-colors"
                                    >
                                        {showConfirmPassword ? <FiEyeOff className="w-5 h-5" /> : <FiEye className="w-5 h-5" />}
                                    </button>
                                </div>
                                {formData.confirmPassword && formData.password !== formData.confirmPassword && (
                                    <p className="mt-1 text-xs text-red-400">Passwords do not match</p>
                                )}
                            </div>

                            {/* Terms Agreement */}
                            <div className="flex items-start space-x-3">
                                <input
                                    id="terms"
                                    type="checkbox"
                                    checked={agreedToTerms}
                                    onChange={(e) => setAgreedToTerms(e.target.checked)}
                                    className="w-5 h-5 mt-0.5 rounded border-primary-700 bg-primary-800 text-accent-gold focus:ring-accent-gold/50"
                                    required
                                />
                                <label htmlFor="terms" className="text-sm text-gray-400">
                                    I agree to the{' '}
                                    <Link href="/terms" className="text-accent-gold hover:text-accent-gold-light">
                                        Terms & Conditions
                                    </Link>{' '}
                                    and{' '}
                                    <Link href="/privacy" className="text-accent-gold hover:text-accent-gold-light">
                                        Privacy Policy
                                    </Link>
                                </label>
                            </div>

                            {/* Submit Button */}
                            <button
                                type="submit"
                                disabled={isLoading}
                                className="btn-primary w-full text-lg disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                {isLoading ? 'Creating Account...' : 'Create Account'}
                            </button>
                        </form>

                        {/* Divider */}
                        <div className="relative my-8">
                            <div className="divider" />
                            <span className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 bg-background-dark-secondary px-4 text-sm text-gray-400">
                                or
                            </span>
                        </div>

                        {/* Sign In Link */}
                        <p className="text-center text-gray-400">
                            Already have an account?{' '}
                            <Link href="/login" className="text-accent-gold hover:text-accent-gold-light font-semibold transition-colors">
                                Sign In
                            </Link>
                        </p>

                        {/* Trust Indicators */}
                        <div className="mt-8 pt-6 border-t border-primary-700/30">
                            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 text-center">
                                <div className="flex flex-col items-center space-y-2">
                                    <FiShield className="w-5 h-5 text-accent-emerald" />
                                    <span className="text-xs text-gray-400">Secure Registration</span>
                                </div>
                                <div className="flex flex-col items-center space-y-2">
                                    <FiCheckCircle className="w-5 h-5 text-accent-emerald" />
                                    <span className="text-xs text-gray-400">Instant Verification</span>
                                </div>
                                <div className="flex flex-col items-center space-y-2">
                                    <FiLock className="w-5 h-5 text-accent-emerald" />
                                    <span className="text-xs text-gray-400">Data Protected</span>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Back to Home */}
                    <div className="text-center mt-6">
                        <Link href="/" className="text-gray-400 hover:text-accent-gold transition-colors text-sm">
                            ← Back to Home
                        </Link>
                    </div>
                </div>
            </div>
        </main>
    );
}

'use client';

import { useState, useRef, useEffect } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { FiMenu, FiBell, FiChevronDown, FiUser, FiLogOut, FiSettings, FiCheck, FiInfo, FiDollarSign, FiShield } from 'react-icons/fi';
import { useSiteSettings } from '@/context/SiteContext';

interface AdminHeaderProps {
    user: any;
    onMenuClick: () => void;
}

interface Notification {
    _id: string;
    type: 'deposit' | 'withdrawal' | 'kyc' | 'registration';
    title: string;
    message: string;
    isRead: boolean;
    createdAt: string;
}

export default function AdminHeader({ user, onMenuClick }: AdminHeaderProps) {
    const { settings } = useSiteSettings();
    const router = useRouter();
    const siteName = settings.siteName;
    const [dropdownOpen, setDropdownOpen] = useState(false);
    const [notifDropdownOpen, setNotifDropdownOpen] = useState(false);
    const [notifications, setNotifications] = useState<Notification[]>([]);
    const [unreadCount, setUnreadCount] = useState(0);
    const [loading, setLoading] = useState(false);
    const [page, setPage] = useState(1);
    const [hasMore, setHasMore] = useState(true);

    const dropdownRef = useRef<HTMLDivElement>(null);
    const notifRef = useRef<HTMLDivElement>(null);

    // Close dropdowns when clicking outside
    useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setDropdownOpen(false);
            }
            if (notifRef.current && !notifRef.current.contains(event.target as Node)) {
                setNotifDropdownOpen(false);
            }
        }
        document.addEventListener("mousedown", handleClickOutside);
        return () => {
            document.removeEventListener("mousedown", handleClickOutside);
        };
    }, []);

    const fetchNotifications = async (isLoadMore = false) => {
        if (loading) return;
        setLoading(true);
        try {
            // If refreshing (page 1), reset
            const currentPage = isLoadMore ? page + 1 : 1;

            const res = await fetch(`/api/admin/notifications?page=${currentPage}&limit=5`);
            const data = await res.json();

            if (data.success) {
                if (isLoadMore) {
                    setNotifications(prev => [...prev, ...data.notifications]);
                    setPage(currentPage);
                } else {
                    setNotifications(data.notifications);
                    setPage(1);
                }
                setUnreadCount(data.unreadCount);
                setHasMore(data.pagination.page < data.pagination.pages);
            }
        } catch (error) {
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        // Initial fetch
        fetchNotifications();

        // Poll every 30 seconds
        const interval = setInterval(() => fetchNotifications(), 30000);
        return () => clearInterval(interval);
    }, []);

    const handleMarkAsRead = async (id?: string) => {
        try {
            if (id) {
                // Optimistic update
                setNotifications(prev => prev.map(n => n._id === id ? { ...n, isRead: true } : n));
                setUnreadCount(prev => Math.max(0, prev - 1));

                await fetch('/api/admin/notifications', {
                    method: 'PATCH',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id })
                });
            } else {
                // Mark all
                setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
                setUnreadCount(0);
                await fetch('/api/admin/notifications', {
                    method: 'PATCH',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ type: 'markAllRead' })
                });
            }
        } catch (error) {
            console.error(error);
        }
    };

    const handleNotificationClick = (notif: Notification) => {
        if (!notif.isRead) handleMarkAsRead(notif._id);
        setNotifDropdownOpen(false);

        // Routing logic based on type
        switch (notif.type) {
            case 'deposit': router.push('/admin/deposits'); break;
            case 'withdrawal': router.push('/admin/withdrawals'); break;
            case 'kyc': router.push('/admin/kyc'); break;
            case 'registration': router.push('/admin/users'); break;
            default: break;
        }
    };

    const getIcon = (type: string) => {
        switch (type) {
            case 'deposit': return <FiDollarSign className="text-green-400" />;
            case 'withdrawal': return <FiDollarSign className="text-red-400" />;
            case 'kyc': return <FiShield className="text-blue-400" />;
            default: return <FiUser className="text-accent-gold" />;
        }
    };

    const handleLogout = () => {
        localStorage.removeItem('user');
        window.location.href = '/login';
    };

    return (
        <header className="fixed top-0 right-0 left-0 lg:left-64 h-16 bg-primary-900/95 backdrop-blur-md border-b border-primary-800 z-30 transition-all duration-300">
            <div className="h-full px-4 sm:px-6 flex items-center justify-between">
                {/* Left: Mobile Menu & Brand (Mobile only) */}
                <div className="flex items-center gap-3">
                    <button
                        onClick={onMenuClick}
                        className="lg:hidden p-2 text-gray-300 hover:text-white hover:bg-primary-800 rounded-lg transition-colors"
                    >
                        <FiMenu size={24} />
                    </button>
                    {/* Mobile Brand */}
                    <span className="lg:hidden text-lg font-bold font-serif text-white tracking-wider">
                        {siteName}
                    </span>
                </div>

                {/* Right: Actions & Profile */}
                <div className="flex items-center gap-4 ml-auto">
                    {/* Notifications */}
                    <div className="relative" ref={notifRef}>
                        <button
                            onClick={() => { setNotifDropdownOpen(!notifDropdownOpen); if (!notifDropdownOpen) fetchNotifications(); }}
                            className="p-2 text-gray-400 hover:text-white relative hover:bg-white/5 rounded-full transition-colors"
                        >
                            <FiBell size={20} />
                            {unreadCount > 0 && (
                                <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-red-500 rounded-full animate-pulse shadow-lg shadow-red-500/50"></span>
                            )}
                        </button>

                        {/* Notifications Dropdown */}
                        {notifDropdownOpen && (
                            <div className="absolute right-0 top-full mt-2 w-80 md:w-96 bg-primary-900 border border-primary-700 rounded-xl shadow-xl overflow-hidden animate-scale-in origin-top-right z-50">
                                <div className="p-4 border-b border-primary-800 flex justify-between items-center bg-primary-800/20">
                                    <h3 className="font-bold text-white">Notifications</h3>
                                    {unreadCount > 0 && (
                                        <button onClick={() => handleMarkAsRead()} className="text-xs text-accent-gold hover:text-white transition-colors">
                                            Mark all as read
                                        </button>
                                    )}
                                </div>
                                <div className="max-h-[60vh] overflow-y-auto">
                                    {notifications.length === 0 ? (
                                        <div className="p-8 text-center text-gray-500">
                                            <FiBell className="mx-auto w-8 h-8 mb-2 opacity-50" />
                                            <p>No notifications yet</p>
                                        </div>
                                    ) : (
                                        <div className="divide-y divide-primary-800">
                                            {notifications.map(notif => (
                                                <div
                                                    key={notif._id}
                                                    onClick={() => handleNotificationClick(notif)}
                                                    className={`p-4 hover:bg-primary-800/50 transition-colors cursor-pointer flex gap-3 ${!notif.isRead ? 'bg-primary-800/10 border-l-2 border-accent-gold' : ''}`}
                                                >
                                                    <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 bg-primary-800`}>
                                                        {getIcon(notif.type)}
                                                    </div>
                                                    <div className="flex-1 min-w-0">
                                                        <p className={`text-sm ${!notif.isRead ? 'font-semibold text-white' : 'text-gray-300'}`}>
                                                            {notif.title}
                                                        </p>
                                                        <p className="text-xs text-gray-400 truncate mt-0.5">{notif.message}</p>
                                                        <p className="text-[10px] text-gray-500 mt-1">{new Date(notif.createdAt).toLocaleString()}</p>
                                                    </div>
                                                </div>
                                            ))}
                                            {hasMore && (
                                                <button
                                                    onClick={(e) => { e.stopPropagation(); fetchNotifications(true); }}
                                                    className="w-full py-3 text-xs text-center text-gray-400 hover:text-white hover:bg-primary-800 transition-colors"
                                                    disabled={loading}
                                                >
                                                    {loading ? 'Loading...' : 'Load more'}
                                                </button>
                                            )}
                                        </div>
                                    )}
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Profile Dropdown */}
                    <div className="relative" ref={dropdownRef}>
                        <button
                            onClick={() => setDropdownOpen(!dropdownOpen)}
                            className="flex items-center gap-3 p-1.5 rounded-lg hover:bg-primary-800 transition-colors"
                        >
                            <div className="w-8 h-8 rounded-full bg-gradient-to-br from-accent-gold to-yellow-600 flex items-center justify-center text-primary-950 font-bold text-sm">
                                {user?.firstName?.charAt(0) || 'A'}
                            </div>
                            <span className="hidden md:block text-sm font-medium text-white">
                                {user?.firstName} {user?.lastName}
                            </span>
                            <FiChevronDown className={`text-gray-400 transition-transform ${dropdownOpen ? 'rotate-180' : ''}`} />
                        </button>

                        {/* Dropdown Menu */}
                        {dropdownOpen && (
                            <div className="absolute right-0 top-full mt-2 w-48 bg-primary-900 border border-primary-700 rounded-xl shadow-xl overflow-hidden animate-scale-in origin-top-right">
                                <div className="p-3 border-b border-primary-800 md:hidden">
                                    <p className="text-sm font-bold text-white">{user?.firstName} {user?.lastName}</p>
                                    <p className="text-xs text-gray-400 truncate">{user?.email}</p>
                                </div>
                                <div className="py-1">
                                    <Link
                                        href="/admin/profile"
                                        onClick={() => setDropdownOpen(false)}
                                        className="flex items-center gap-3 px-4 py-3 text-sm text-gray-300 hover:bg-primary-800 hover:text-white transition-colors"
                                    >
                                        <FiUser size={16} /> Profile Settings
                                    </Link>
                                    <button
                                        onClick={handleLogout}
                                        className="w-full flex items-center gap-3 px-4 py-3 text-sm text-red-400 hover:bg-red-500/10 hover:text-red-300 transition-colors text-left"
                                    >
                                        <FiLogOut size={16} /> Logout
                                    </button>
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </header>
    );
}

'use client';

import Link from 'next/link';
import { useState, useEffect, useRef } from 'react';
import { usePathname, useRouter } from 'next/navigation';
import { useSiteSettings } from '@/context/SiteContext';
import { FiMenu, FiX, FiUser, FiLogOut, FiArrowLeft, FiSettings, FiHelpCircle, FiGrid, FiChevronDown, FiBell, FiDollarSign, FiTrendingUp, FiShield } from 'react-icons/fi';

interface NavbarProps {
    isAuthenticated?: boolean;
    isAdmin?: boolean;
    user?: {
        _id?: string;
        firstName: string;
        lastName: string;
        email?: string;
    } | null;
}

export default function Navbar({ isAuthenticated: propIsAuthenticated, isAdmin: propIsAdmin, user: propUser }: NavbarProps) {
    const { settings } = useSiteSettings();
    const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
    const [profileDropdownOpen, setProfileDropdownOpen] = useState(false);

    // Internal Auth State (to handle client-side checks on public pages)
    const [isLoggedIn, setIsLoggedIn] = useState(!!propIsAuthenticated);
    const [currentUser, setCurrentUser] = useState(propUser || null);
    const [isAdminState, setIsAdminState] = useState(!!propIsAdmin);

    // Sync propUser with state
    useEffect(() => {
        if (propUser) setCurrentUser(propUser);
    }, [propUser]);

    const pathname = usePathname();
    const router = useRouter();
    const dropdownRef = useRef<HTMLDivElement>(null);
    const notifRef = useRef<HTMLDivElement>(null);

    // Notification State
    const [notifDropdownOpen, setNotifDropdownOpen] = useState(false);
    const [notifications, setNotifications] = useState<any[]>([]);
    const [unreadCount, setUnreadCount] = useState(0);
    const [loading, setLoading] = useState(false);
    const [page, setPage] = useState(1);
    const [hasMore, setHasMore] = useState(true);

    // Fetch Notifications
    const fetchNotifications = async (isLoadMore = false) => {
        if (!currentUser?._id || loading) return;
        setLoading(true);
        try {
            const currentPage = isLoadMore ? page + 1 : 1;
            const res = await fetch(`/api/user/notifications?userId=${currentUser._id}&page=${currentPage}&limit=5`);
            const data = await res.json();

            if (data.success) {
                if (isLoadMore) {
                    setNotifications(prev => [...prev, ...data.notifications]);
                    setPage(currentPage);
                } else {
                    setNotifications(data.notifications);
                    setPage(1);
                }
                setUnreadCount(data.unreadCount);
                setHasMore(data.pagination.page < data.pagination.pages);
            }
        } catch (error) {
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    // Mark as Read
    const handleMarkAsRead = async (id?: string) => {
        if (!currentUser?._id) return;
        try {
            if (id) {
                setNotifications(prev => prev.map(n => n._id === id ? { ...n, isRead: true } : n));
                setUnreadCount(prev => Math.max(0, prev - 1));
                await fetch('/api/user/notifications', { method: 'PATCH', body: JSON.stringify({ id, userId: currentUser._id }) });
            } else {
                setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
                setUnreadCount(0);
                await fetch('/api/user/notifications', { method: 'PATCH', body: JSON.stringify({ type: 'markAllRead', userId: currentUser._id }) });
            }
        } catch (error) {
            console.error(error);
        }
    };

    useEffect(() => {
        if (currentUser?._id) {
            fetchNotifications();
            const interval = setInterval(() => fetchNotifications(), 10000); // Poll every 10s
            return () => clearInterval(interval);
        }
    }, [currentUser?._id]);

    // Close on click outside
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setProfileDropdownOpen(false);
            }
            if (notifRef.current && !notifRef.current.contains(event.target as Node)) {
                setNotifDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleLogout = () => {
        localStorage.removeItem('user');
        localStorage.removeItem('token');
        setIsLoggedIn(false);
        setCurrentUser(null);
        setProfileDropdownOpen(false);
        router.push('/login');
    };

    const navLinks = [
        { href: '/', label: 'Home' },
        { href: '/plans', label: 'Investment Plans' },
        { href: '/about', label: 'About' },
        { href: '/contact', label: 'Contact' },
    ];

    // Show Back Button if logged in and NOT on the main dashboard or home
    const showBackButton = isLoggedIn && pathname !== '/dashboard' && pathname !== '/';

    return (
        <nav className="fixed top-0 left-0 right-0 z-50 bg-background-dark/80 backdrop-blur-xl border-b border-primary-800/50">
            <div className="section-container">
                <div className="flex items-center justify-between h-20">

                    {/* Left Section: Back Button + Logo */}
                    <div className="flex items-center gap-4">
                        {showBackButton && (
                            <Link
                                href="/dashboard"
                                className="p-2 -ml-2 text-gray-300 hover:text-accent-gold transition-colors duration-200 rounded-full hover:bg-white/5"
                                aria-label="Back to Dashboard"
                            >
                                <FiArrowLeft className="w-6 h-6" />
                            </Link>
                        )}

                        {/* Logo */}
                        <Link href="/" className="flex items-center space-x-2 group">
                            {settings.siteLogo ? (
                                <img src={settings.siteLogo} alt={settings.siteName} className="h-10 w-auto object-contain" />
                            ) : (
                                <div className="flex items-center space-x-2">
                                    <div className="w-10 h-10 bg-gradient-to-br from-accent-gold to-accent-gold-dark rounded-lg flex items-center justify-center group-hover:scale-110 transition-transform duration-300">
                                        <span className="text-primary-950 font-bold text-xl font-serif">{settings.siteName.charAt(0)}</span>
                                    </div>
                                    <span className="text-xl font-serif font-bold gradient-text hidden sm:block">
                                        {settings.siteName}
                                    </span>
                                </div>
                            )}
                        </Link>
                    </div>

                    {/* Desktop Navigation */}
                    <div className="hidden md:flex items-center space-x-8">
                        {navLinks.map((link) => (
                            <Link
                                key={link.href}
                                href={link.href}
                                className={`transition-colors duration-200 font-medium ${pathname === link.href ? 'text-accent-gold' : 'text-gray-300 hover:text-accent-gold'
                                    }`}
                            >
                                {link.label}
                            </Link>
                        ))}
                    </div>

                    {/* Desktop Auth Buttons / User Profile */}
                    <div className="hidden md:flex items-center space-x-4">
                        {isLoggedIn ? (
                            <>
                                {/* User Notifications */}
                                <div className="relative" ref={notifRef}>
                                    <button
                                        onClick={() => { setNotifDropdownOpen(!notifDropdownOpen); if (!notifDropdownOpen) fetchNotifications(); }}
                                        className="p-2 text-gray-300 hover:text-accent-gold relative transition-colors"
                                    >
                                        <FiBell className="w-6 h-6" />
                                        {unreadCount > 0 && (
                                            <span className="absolute top-1 right-1 w-2.5 h-2.5 bg-red-500 rounded-full animate-pulse border border-background-dark"></span>
                                        )}
                                    </button>

                                    {/* Notifications Dropdown */}
                                    {notifDropdownOpen && (
                                        <div className="absolute right-0 top-full mt-4 w-80 md:w-96 bg-primary-900 border border-primary-700/50 rounded-xl shadow-xl shadow-black/50 overflow-hidden animate-slide-up origin-top-right z-50">
                                            <div className="p-4 border-b border-primary-800 flex justify-between items-center bg-primary-800/20">
                                                <h3 className="font-bold text-white font-serif">Notifications</h3>
                                                {unreadCount > 0 && (
                                                    <button onClick={() => handleMarkAsRead()} className="text-xs text-accent-gold hover:text-white transition-colors font-medium">
                                                        Mark all as read
                                                    </button>
                                                )}
                                            </div>
                                            <div className="max-h-[60vh] overflow-y-auto custom-scrollbar">
                                                {notifications.length === 0 ? (
                                                    <div className="p-8 text-center text-gray-500">
                                                        <FiBell className="mx-auto w-8 h-8 mb-3 opacity-30" />
                                                        <p>No notifications yet</p>
                                                    </div>
                                                ) : (
                                                    <div className="divide-y divide-primary-800/50">
                                                        {notifications.map(notif => (
                                                            <div
                                                                key={notif._id}
                                                                onClick={() => !notif.isRead && handleMarkAsRead(notif._id)}
                                                                className={`p-4 hover:bg-primary-800/30 transition-colors flex gap-3 ${!notif.isRead ? 'bg-primary-800/10' : ''}`}
                                                            >
                                                                <div className={`w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0 ${notif.type === 'deposit' ? 'bg-green-500/20 text-green-500' :
                                                                    notif.type === 'withdrawal' ? 'bg-red-500/20 text-red-500' :
                                                                        notif.type === 'kyc' ? 'bg-blue-500/20 text-blue-500' :
                                                                            notif.type === 'investment' ? 'bg-accent-gold/20 text-accent-gold' :
                                                                                'bg-gray-700/50 text-gray-400'
                                                                    }`}>
                                                                    {notif.type === 'deposit' ? <FiDollarSign /> :
                                                                        notif.type === 'withdrawal' ? <FiDollarSign /> :
                                                                            notif.type === 'kyc' ? <FiShield /> :
                                                                                notif.type === 'investment' ? <FiTrendingUp /> : <FiBell />}
                                                                </div>
                                                                <div className="flex-1 min-w-0">
                                                                    <div className="flex justify-between items-start mb-0.5">
                                                                        <p className={`text-sm ${!notif.isRead ? 'font-bold text-white' : 'text-gray-300 font-medium'}`}>
                                                                            {notif.title}
                                                                        </p>
                                                                        {!notif.isRead && (
                                                                            <span className="w-2 h-2 bg-accent-gold rounded-full flex-shrink-0 mt-1.5 ml-2"></span>
                                                                        )}
                                                                    </div>
                                                                    <p className="text-xs text-gray-400 leading-relaxed">{notif.message}</p>
                                                                    <p className="text-[10px] text-gray-500 mt-2 font-medium">
                                                                        {new Date(notif.createdAt).toLocaleDateString()} • {new Date(notif.createdAt).toLocaleTimeString()}
                                                                    </p>
                                                                </div>
                                                            </div>
                                                        ))}
                                                        {hasMore && (
                                                            <button
                                                                onClick={(e) => { e.stopPropagation(); fetchNotifications(true); }}
                                                                className="w-full py-3 text-xs font-medium text-center text-gray-400 hover:text-white hover:bg-primary-800/30 transition-colors"
                                                                disabled={loading}
                                                            >
                                                                {loading ? 'Loading...' : 'Load more'}
                                                            </button>
                                                        )}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    )}
                                </div>

                                <div className="relative" ref={dropdownRef}>
                                    <button
                                        onClick={() => setProfileDropdownOpen(!profileDropdownOpen)}
                                        className="flex items-center space-x-2 text-gray-300 hover:text-accent-gold transition-colors duration-200 focus:outline-none"
                                    >
                                        <div className="w-8 h-8 rounded-full bg-primary-800 flex items-center justify-center border border-primary-700">
                                            <FiUser className="w-4 h-4" />
                                        </div>
                                        <span className="font-medium">
                                            {currentUser ? `${currentUser.firstName} ${currentUser.lastName}` : 'Account'}
                                        </span>
                                        <FiChevronDown className={`w-4 h-4 transition-transform ${profileDropdownOpen ? 'rotate-180' : ''}`} />
                                    </button>

                                    {/* Dropdown Menu */}
                                    {profileDropdownOpen && (
                                        <div className="absolute right-0 mt-3 w-56 bg-primary-900 border border-primary-700/50 rounded-xl shadow-xl shadow-black/50 overflow-hidden animate-slide-up origin-top-right">
                                            {/* ... content ... */}
                                            <div className="px-4 py-3 border-b border-primary-800/50">
                                                <p className="text-sm text-gray-400">Signed in as</p>
                                                <p className="text-sm font-bold text-white truncate">{currentUser?.email}</p>
                                            </div>
                                            <div className="py-1">
                                                <Link
                                                    href={isAdminState ? '/admin' : '/dashboard'}
                                                    className="flex items-center px-4 py-2.5 text-sm text-gray-300 hover:bg-primary-800 hover:text-accent-gold transition-colors"
                                                    onClick={() => setProfileDropdownOpen(false)}
                                                >
                                                    <FiGrid className="mr-3 w-4 h-4" />
                                                    Dashboard
                                                </Link>
                                                <Link
                                                    href="/dashboard/settings"
                                                    className="flex items-center px-4 py-2.5 text-sm text-gray-300 hover:bg-primary-800 hover:text-accent-gold transition-colors"
                                                    onClick={() => setProfileDropdownOpen(false)}
                                                >
                                                    <FiSettings className="mr-3 w-4 h-4" />
                                                    Profile Settings
                                                </Link>
                                                <Link
                                                    href="/contact"
                                                    className="flex items-center px-4 py-2.5 text-sm text-gray-300 hover:bg-primary-800 hover:text-accent-gold transition-colors"
                                                    onClick={() => setProfileDropdownOpen(false)}
                                                >
                                                    <FiHelpCircle className="mr-3 w-4 h-4" />
                                                    Support
                                                </Link>
                                            </div>
                                            <div className="border-t border-primary-800/50 py-1">
                                                <button
                                                    onClick={handleLogout}
                                                    className="flex w-full items-center px-4 py-2.5 text-sm text-red-400 hover:bg-red-500/10 transition-colors"
                                                >
                                                    <FiLogOut className="mr-3 w-4 h-4" />
                                                    Logout
                                                </button>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </>
                        ) : (
                            <>
                                <Link href="/login" className="btn-secondary">
                                    Login
                                </Link>
                                <Link href="/register" className="btn-primary">
                                    Get Started
                                </Link>
                            </>
                        )}
                    </div>

                    {/* Mobile Profile & Menu */}
                    <div className="flex items-center gap-2 md:hidden">
                        {isLoggedIn && (
                            <div className="relative" ref={dropdownRef}>
                                <button
                                    onClick={() => setProfileDropdownOpen(!profileDropdownOpen)}
                                    className="w-9 h-9 rounded-full bg-gradient-to-br from-accent-gold to-accent-gold-dark flex items-center justify-center text-primary-950 font-bold shadow-lg"
                                >
                                    {currentUser?.firstName?.charAt(0) || <FiUser />}
                                </button>

                                {/* Mobile Profile Dropdown */}
                                {profileDropdownOpen && (
                                    <div className="absolute right-0 top-full mt-3 w-64 bg-primary-900 border border-primary-700/50 rounded-xl shadow-xl shadow-black/50 overflow-hidden animate-slide-up origin-top-right z-50">
                                        <div className="px-4 py-4 bg-primary-800/30 border-b border-primary-700/50">
                                            <div className="flex items-center gap-3 mb-2">
                                                <div className="w-10 h-10 rounded-full bg-accent-gold/20 flex items-center justify-center text-accent-gold">
                                                    <span className="font-bold text-lg">{currentUser?.firstName?.charAt(0)}</span>
                                                </div>
                                                <div className="overflow-hidden">
                                                    <p className="font-bold text-white truncate">{currentUser?.firstName} {currentUser?.lastName}</p>
                                                    <p className="text-xs text-gray-400 truncate">{currentUser?.email}</p>
                                                </div>
                                            </div>
                                        </div>
                                        <div className="p-2 space-y-1">
                                            <Link
                                                href={isAdminState ? '/admin' : '/dashboard'}
                                                className="flex items-center px-4 py-3 text-sm font-medium text-gray-300 hover:bg-primary-800 hover:text-white rounded-lg transition-colors"
                                                onClick={() => setProfileDropdownOpen(false)}
                                            >
                                                <FiGrid className="mr-3 w-4 h-4 text-accent-gold" />
                                                Dashboard
                                            </Link>
                                            <Link
                                                href="/dashboard/settings"
                                                className="flex items-center px-4 py-3 text-sm font-medium text-gray-300 hover:bg-primary-800 hover:text-white rounded-lg transition-colors"
                                                onClick={() => setProfileDropdownOpen(false)}
                                            >
                                                <FiSettings className="mr-3 w-4 h-4 text-accent-gold" />
                                                Profile Settings
                                            </Link>
                                            <Link
                                                href="/contact"
                                                className="flex items-center px-4 py-3 text-sm font-medium text-gray-300 hover:bg-primary-800 hover:text-white rounded-lg transition-colors"
                                                onClick={() => setProfileDropdownOpen(false)}
                                            >
                                                <FiHelpCircle className="mr-3 w-4 h-4 text-accent-gold" />
                                                Support
                                            </Link>
                                            <div className="border-t border-primary-800/50 my-1"></div>
                                            <button
                                                onClick={() => { setProfileDropdownOpen(false); handleLogout(); }}
                                                className="flex w-full items-center px-4 py-3 text-sm font-medium text-red-400 hover:bg-red-500/10 rounded-lg transition-colors"
                                            >
                                                <FiLogOut className="mr-3 w-4 h-4" />
                                                Logout
                                            </button>
                                        </div>
                                    </div>
                                )}
                            </div>
                        )}

                        {/* Mobile Menu Button */}
                        <button
                            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
                            className="p-2 text-gray-300 hover:text-accent-gold transition-colors duration-200"
                        >
                            {mobileMenuOpen ? <FiX className="w-6 h-6" /> : <FiMenu className="w-6 h-6" />}
                        </button>
                    </div>
                </div>

                {/* Mobile Menu */}
                {mobileMenuOpen && (
                    <div className="md:hidden py-4 border-t border-primary-800/50 animate-slide-down bg-background-dark/95 backdrop-blur-xl absolute left-0 right-0 px-4 shadow-2xl h-screen">
                        <div className="flex flex-col space-y-4">
                            {navLinks.map((link) => (
                                <Link
                                    key={link.href}
                                    href={link.href}
                                    className={`font-medium py-3 px-4 rounded-lg transition-colors duration-200 ${pathname === link.href ? 'bg-primary-800/50 text-accent-gold' : 'text-gray-300 hover:bg-white/5 hover:text-accent-gold'
                                        }`}
                                    onClick={() => setMobileMenuOpen(false)}
                                >
                                    {link.label}
                                </Link>
                            ))}

                            {!isLoggedIn && (
                                <div className="grid grid-cols-2 gap-4 mt-4 pt-4 border-t border-primary-800/50">
                                    <Link href="/login" className="btn-secondary w-full text-center justify-center p-3" onClick={() => setMobileMenuOpen(false)}>
                                        Login
                                    </Link>
                                    <Link href="/register" className="btn-primary w-full text-center justify-center p-3" onClick={() => setMobileMenuOpen(false)}>
                                        Get Started
                                    </Link>
                                </div>
                            )}
                        </div>
                    </div>
                )}
            </div>
        </nav>
    );
}

'use client';

import { useEffect, useRef, memo } from 'react';

// 1. Ticker Tape Widget (Scrolling Top Bar)
export const TickerTape = memo(() => {
    const container = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!container.current) return;
        const script = document.createElement("script");
        script.src = "https://s3.tradingview.com/external-embedding/embed-widget-ticker-tape.js";
        script.type = "text/javascript";
        script.async = true;
        script.innerHTML = JSON.stringify({
            "symbols": [
                { "proName": "FOREXCOM:SPXUSD", "title": "S&P 500" },
                { "proName": "FOREXCOM:NSXUSD", "title": "US 100" },
                { "proName": "FX_IDC:EURUSD", "title": "EUR/USD" },
                { "proName": "BITSTAMP:BTCUSD", "title": "Bitcoin" },
